INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-baker-wedding-dress',
      'ชุดแต่งงานต้องคำสาปแห่งตระกูลเบเกอร์ (แอนนา เบเกอร์)',
      'The Cursed Wedding Dress of Anna Baker (Baker Mansion)',
      'curse',
      'เพนซิลเวเนีย',
      'Pennsylvania',
      'อัลทูนา',
      'Altoona',
      40.5097,
      -78.4111,
      'whisper',
      'แอนนา เบเกอร์ บุตรสาวของมหาเศรษฐีเจ้าของคฤหาสน์เบเกอร์ ตกหลุมรักคนงานโรงเหล็กผู้ต่ำศักดิ์ เธอแอบสั่งตัดชุดแต่งงานลูกไม้สีขาวสุดวิจิตรไว้เพื่อหวังจะได้ครองรัก ทว่าบิดาของเธอกลับสั่งห้ามและขับไล่คนรักของเธอไป แอนนาตรอมใจและปฏิญาณว่าจะไม่แต่งงานกับใครตลอดชีวิต หลังจากเธอเสียชีวิต ชุดแต่งงานที่ตั้งโชว์ในตู้กระจกมักจะขยับ โยกไหว หรือสะบัดชายกระโปรงเองในคืนพระจันทร์เต็มดวง ราวกับวิญญาณของแอนนายังคงสวมใส่ชุดเพื่อเต้นรำในความมืด',
      'Anna Baker, daughter of an iron baron, bought a magnificent lace wedding gown in secret for her planned elopement with a low-status ironworker. When her father discovered the affair, he banished the lover. Heartbroken, Anna vowed never to marry and died a bitter spinster. Today displayed in a sealed glass case at Baker Mansion, the dress is said to sway and shake violently on full moon nights, as if Anna''s frustrated phantom is dancing inside it.',
      'คฤหาสน์เบเกอร์สร้างขึ้นในปี 1849 โดย เอเลียส เบเกอร์ ปัจจุบันกลายเป็นพิพิธภัณฑ์ประวัติศาสตร์ประจำเมืองอัลทูนา เรื่องราวของชุดแต่งงานขยับได้กลายเป็นหนึ่งในเรื่องเล่าอาถรรพ์ที่โด่งดังที่สุดของสหรัฐอเมริกา และได้รับการสืบสวนโดยทีมนักล่าผีหลายรุ่น',
      'Built in 1849 by Elias Baker, Baker Mansion is now a historic museum in Blair County. Visitors and staff have repeatedly reported the glass case vibrating and the fabric billowing without any air currents, making it one of America''s most enduring haunted object legends.',
      'ห้ามเคาะกระจกตู้โชว์ชุดแต่งงาน หรือเยาะเย้ยความรักที่ล้มเหลวของเธอ',
      'Never tap on the glass casing or mock Anna Baker''s unfulfilled love.',
      'https://i.ytimg.com/vi/PPdOyyMtadg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/PPdOyyMtadg/hqdefault.jpg","title":"ชุดแต่งงานต้องคำสาปแห่งตระกูลเบเกอร์ (แอนนา เบเกอร์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=PPdOyyMtadg","title":"The Haunted Wedding Dress of Anna Baker: Heartbreak or Curse?","thumbnail":"https://i.ytimg.com/vi/PPdOyyMtadg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-bettiscombe-screaming-skull',
      'กะโหลกกรีดร้องแห่งเบตติสคอมบ์ (อาถรรพ์กะโหลกห้ามย้าย)',
      'The Screaming Skull of Bettiscombe Manor',
      'curse',
      'ดอร์เซต',
      'Dorset',
      'เบตติสคอมบ์',
      'Bettiscombe',
      50.8115,
      -2.8394,
      'creepy_wind',
      'ตำนานเล่าถึงทาสชาวแอฟริกันที่ถูกนำตัวมายังคฤหาสน์เบตติสคอมบ์ในศตวรรษที่ 18 ก่อนเสียชีวิตเขาได้ขอร้องให้นำร่างของเขากลับไปฝังยังบ้านเกิดที่แอฟริกา ทว่าเจ้านายกลับนำไปฝังในสุสานท้องถิ่น นับแต่นั้นเกิดเสียงกรีดร้องโหยหวนและฝันร้ายสะพรึงไปทั่วบ้าน จนต้องขุดนำกะโหลกขึ้นมาเก็บบนคฤหาสน์ หากกะโหลกนี้ถูกเคลื่อนย้ายหรือนำออกจากบ้าน ตัวบ้านจะสั่นสะเทือน พืชผลจะเหี่ยวเฉา และจะมีคนในบ้านต้องตายอย่างเป็นปริศนา',
      'According to Dorset legend, an enslaved African brought to Bettiscombe Manor swore on his deathbed that he would never rest unless returned to his homeland. When he was buried locally, horrific shrieks and supernatural storms shook the manor. When his skull was brought back inside, peace returned. The curse dictates that if the skull is ever removed, the house will shudder to its foundations and fatal misfortunes will strike the inhabitants.',
      'เรื่องเล่ากะโหลกกรีดร้องของเกาะอังกฤษเป็นหนึ่งในนิทานพื้นบ้านดั้งเดิมที่สะท้อนถึงบาปของการค้าทาสในอดีต กะโหลกดังกล่าวยังคงถูกเก็บรักษาไว้ในคฤหาสน์จนถึงปัจจุบัน',
      'Screaming skull traditions are unique to British folklore, often reflecting historical injustices. Anthropological studies revealed the skull to be centuries old, and it remains safely kept in the manor to avoid triggering the ancestral curse.',
      'ห้ามนำกะโหลกศีรษะออกจากคฤหาสน์โดยเด็ดขาด',
      'Never attempt to remove or displace the skull from the manor grounds.',
      'https://i.ytimg.com/vi/sXuzBFIabv4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/sXuzBFIabv4/hqdefault.jpg","title":"กะโหลกกรีดร้องแห่งเบตติสคอมบ์ (อาถรรพ์กะโหลกห้ามย้าย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=sXuzBFIabv4","title":"The Screaming Skull Of Bettiscombe Manor - Dorset England | Episode 4","thumbnail":"https://i.ytimg.com/vi/sXuzBFIabv4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-dybbuk-box-mannis',
      'กล่องดึบบุก (กล่องไวน์กักขังวิญญาณร้ายแห่งพอร์ตแลนด์)',
      'The Dybbuk Box (Haunted Jewish Wine Cabinet)',
      'curse',
      'ออริกอน',
      'Oregon',
      'พอร์ตแลนด์',
      'Portland',
      45.5152,
      -122.6784,
      'whisper',
      'กล่องใส่ขวดไวน์ไม้โบราณที่นำมาจากผู้รอดชีวิตจากการฆ่าล้างเผ่าพันธุ์ชาวยิว ภายในบรรจุสิ่งของลึกลับ เช่น ปอยผม เหรียญเพนนี และข้อความภาษาฮีบรู เมื่อ เควิน แมนนิส ซื้อกล่องนี้มาเปิด ทุกคนที่ครอบครองต่างเผชิญกับฝันร้ายเรื่องหญิงแก่หน้าตาน่ากลัว กลิ่นแอมโมเนียและดอกไม้เน่าคละคลุ้ง ผมร่วงเป็นหย่อม หลอดไฟแตกกระจาย และอาการป่วยกระทันหัน จนเชื่อกันว่าเป็นกล่องกักขัง ''ดึบบุก'' หรือวิญญาณพยาบาทตามคติยิว',
      'Purchased at an estate sale in Oregon, this vintage Spanish wine box belonged to a Holocaust survivor who had trapped a malevolent Jewish spirit—a Dybbuk—inside. Subsequent owners reported horrifying sleep paralysis, horrific visions of an ancient hag, phantom smells of cat urine and rotten lilies, sudden hair loss, and bizarre mechanical breakdowns.',
      'ดึบบุกบอกซ์กลายเป็นหนึ่งในวัตถุต้องคำสาปที่โด่งดังที่สุดในยุคอินเทอร์เน็ต ถูกนำไปจัดแสดงที่พิพิธภัณฑ์ของแซค บากันส์ ในลาสเวกัส และสร้างแรงบันดาลใจให้ภาพยนตร์สยองขวัญเรื่อง The Possession',
      'The Dybbuk Box captured global attention after being listed on eBay in 2004. It inspired the Hollywood horror movie ''The Possession'' and is now kept under heavy blessing and protection in Zak Bagans'' The Haunted Museum.',
      'ห้ามเปิดกล่องหรือเผากล่องเด็ดขาด เพราะจะทำให้วิญญาณดึบบุกหลุดออกมาสิงสู่',
      'Never break the sealed wax or open the box, lest the malicious spirit possess you.',
      'https://i.ytimg.com/vi/3sX8EWOql24/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/3sX8EWOql24/hqdefault.jpg","title":"กล่องดึบบุก (กล่องไวน์กักขังวิญญาณร้ายแห่งพอร์ตแลนด์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=3sX8EWOql24","title":"The Most Haunted Object in the World | The Terrifying True Story of the Dybbuk Box","thumbnail":"https://i.ytimg.com/vi/3sX8EWOql24/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-black-orlov-brahma-eye',
      'คำสาปเพชรแบล็กออร์ลอฟ (ดวงเนตรพระพรหม)',
      'The Curse of the Black Orlov Diamond (Eye of Brahma)',
      'curse',
      'อุตตรประเทศ',
      'Uttar Pradesh',
      'กานปุระ',
      'Kanpur',
      26.4499,
      80.3319,
      'jungle_curse',
      'เพชรสีดำอมเทาขนาด 67.5 กะรัต หรือที่รู้จักในนาม ''ดวงเนตรพระพรหม'' มีตำนานว่าถูกขโมยมาจากดวงพระเนตรของเทวรูปพระพรหมในศาลเจ้าเมืองปอนดิเชอร์รี คำสาปแห่งเทพเจ้าส่งผลให้ผู้ครอบครองตกอยู่ในชะตากรรมสยอง ทั้งพ่อค้าเพชร เจ.ดับเบิลยู. ปารีส และเจ้าหญิงรัสเซีย นาเดีย วียิกิน-ออร์ลอฟ ต่างกระโดดตึกเสียชีวิตอย่างปริศนา จนเพชรเม็ดนี้ต้องถูกนำไปเจียระไนแบ่งเป็นสามส่วนเพื่อทำลายอาถรรพ์',
      'The Black Orlov, a haunting cushion-cut diamond of 67.5 carats, was reportedly stolen from an eye of a sacred statue of Brahma in southern India. A devastating curse trailed its owners: gem dealer J.W. Paris leaped to his death from a New York skyscraper in 1932, followed by Russian Princess Nadia Vygin-Orlov and Princess Leonila Galitsine-Bariatinsky, who both jumped to their deaths in Rome in 1947.',
      'เพชรสีดำเป็นอัญมณีหายากอย่างยิ่ง ในศตวรรษที่ 20 ช่างเจียระไนชาวอเมริกันได้ทำการตัดแบ่งเพชรออกเป็น 3 เม็ดเพื่อสลายพลังงานคำสาป และหลังจากนั้นการเสียชีวิตต่อเนื่องจึงยุติลง',
      'The gemstone was eventually recut into three separate stones to shatter the hex. While skeptics debate the historical authenticity of the princesses'' suicide dates, the Black Orlov remains one of history''s most feared cursed jewels.',
      'ห้ามขโมยหรือครอบครองอัญมณีศักดิ์สิทธิ์ที่ถูกฉกชิงจากเทวรูป',
      'Never wear or covet sacred gemstones plundered from consecrated religious shrines.',
      'https://i.ytimg.com/vi/1WdjFqF52J4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/1WdjFqF52J4/hqdefault.jpg","title":"คำสาปเพชรแบล็กออร์ลอฟ (ดวงเนตรพระพรหม)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=1WdjFqF52J4","title":"The History of The Black Orlov Diamond","thumbnail":"https://i.ytimg.com/vi/1WdjFqF52J4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-myrtles-plantation-mirror',
      'กระจกสะกดวิญญาณแห่งมายร์เทิลส์ แพลนเทชัน',
      'The Haunted Mirror of the Myrtles Plantation',
      'curse',
      'ลุยเซียนา',
      'Louisiana',
      'เซนต์ฟรานซิสวิลล์',
      'St. Francisville',
      30.8041,
      -91.3853,
      'whisper',
      'กระจกโบราณกรอบทองที่ตั้งอยู่ในโถงทางเดินของคฤหาสน์มายร์เทิลส์ เชื่อกันว่ากักขังวิญญาณของ ซารา วูดรัฟฟ์ และลูกๆ สองคนของเธอที่ถูกวางยาพิษเสียชีวิต ตามประเพณีภาคใต้ของสหรัฐฯ เมื่อมีคนตายต้องนำผ้าดำมาคลุมกระจกทุกบาน มิฉะนั้นวิญญาณจะติดอยู่ในกระจก ทว่าในวันเกิดเหตุมีกระจกบานนี้เพียงบานเดียวที่ไม่มีใครคลุมผ้าไว้ ผู้มาเยือนมักเห็นรอยมือเด็กปรากฏจากด้านในกระจกและเงาเลือนรางที่จ้องมองออกมา',
      'The gilded hallway mirror at the Myrtles Plantation is said to trap the restless souls of Sara Woodruff and her two children, poisoned in the 1820s. Tradition dictated that all mirrors be draped in black upon a death so spirits could cross over, but this mirror was missed. Visitors regularly photograph shadowy figures trapped inside the glass and faint child handprints that appear beneath the surface and cannot be wiped off.',
      'มายร์เทิลส์ แพลนเทชัน สร้างขึ้นเมื่อปี 1796 และได้รับการขนานนามว่าเป็นหนึ่งในบ้านที่มีผีดุที่สุดในอเมริกา โดยมีเรื่องเล่าของวิญญาณทาสคลออี (Chloe) และเหยื่อฆาตกรรมมากมายในอดีต',
      'The Myrtles Plantation has been featured extensively on paranormal documentaries. Staff maintain that even when cleaned with harsh solvents, the child handprints reappear from within the glass pane.',
      'ห้ามเพ่งมองกระจกเกินสามนาทีในเวลาเที่ยงคืน หรือแตะต้องกระจกโดยไม่ได้รับอนุญาต',
      'Never gaze deep into the antique mirror at midnight or touch the glass surface.',
      'https://i.ytimg.com/vi/MFkmzNkfzo0/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/MFkmzNkfzo0/hqdefault.jpg","title":"กระจกสะกดวิญญาณแห่งมายร์เทิลส์ แพลนเทชัน"},{"type":"youtube","url":"https://www.youtube.com/watch?v=MFkmzNkfzo0","title":"The Myrtles Plantation (Most Terrifying Places In America)","thumbnail":"https://i.ytimg.com/vi/MFkmzNkfzo0/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-busby-stoop-chair-thirsk',
      'เก้าอี้มรณะแห่งบัสบี (เก้าอี้คนตายที่ห้ามนั่ง)',
      'Busby''s Stoop Chair (The Dead Man''s Chair of Thirsk)',
      'curse',
      'นอร์ท ยอร์กเชียร์',
      'North Yorkshire',
      'เทิร์สก์',
      'Thirsk',
      54.2333,
      -1.3431,
      'creepy_wind',
      'โทมัส บัสบี ฆาตกรที่ถูกตัดสินประหารชีวิตด้วยการแขวนคอในปี 1702 จากการสังหารพ่อตาของตนเอง ก่อนถูกนำตัวไปลานประหาร เขาได้สาปแช่งในผับท้องถิ่นว่า ''ขอให้ความตายกระทันหันจงมาเยือนใครก็ตามที่กล้ามานั่งบนเก้าอี้ตัวโปรดของข้า'' ตลอดหลายร้อยปี มีผู้ท้าทายลองนั่งเก้าอี้ตัวนี้กว่า 60 คน ทั้งทหาร นักบิน และช่างก่อสร้าง ซึ่งทุกคนต่างประสบอุบัติเหตุเสียชีวิตอย่างรวดเร็วหลังลุกจากเก้าอี้ จนพิพิธภัณฑ์ต้องนำไปแขวนไว้บนเพดานสูงเพื่อไม่ให้ใครนั่งได้อีก',
      'In 1702, Thomas Busby was sentenced to death for murdering his father-in-law over a dispute involving his favorite oak chair. Before being hanged in chains, Busby cursed: ''May sudden death come to anyone who dares sit in my chair.'' Over decades, dozens of RAF pilots, builders, and visitors who sat in it died shortly after in horrific road crashes and fatal heart attacks. The Thirsk Museum finally suspended the chair five feet above the floor so no human can ever sit on it again.',
      'เก้าอี้ตัวนี้ถูกเก็บรักษาไว้ที่พิพิธภัณฑ์เทิร์สก์ เจ้าของผับบัสบีสโตอปอินน์ตัดสินใจส่งมอบเก้าอี้ให้แก่พิพิธภัณฑ์ในปี 1978 หลังจากมีผู้เสียชีวิตติดต่อกันหลายรายหลังจากนั่งเก้าอี้',
      'The Busby Stoop Chair is one of the most rigorously recorded cursed physical artifacts in English paranormal history, preserved untouched at Thirsk Museum.',
      'ห้ามนั่งหรือแม้แต่วางสิ่งของลงบนเก้าอี้ของบัสบีเด็ดขาด',
      'Never sit or place your weight upon the suspended Dead Man''s Chair.',
      'https://i.ytimg.com/vi/ARc0NZBat08/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/ARc0NZBat08/hqdefault.jpg","title":"เก้าอี้มรณะแห่งบัสบี (เก้าอี้คนตายที่ห้ามนั่ง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=ARc0NZBat08","title":"Busby’s Chair: The Cursed Chair That Terrified Britain | Documentary","thumbnail":"https://i.ytimg.com/vi/ARc0NZBat08/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-belcourt-castle-chairs',
      'เก้าอี้อาถรรพ์ผลักคนล้มแห่งปราสาทเบลคอร์ท',
      'The Haunted Armor & Ghost Chairs of Belcourt Castle',
      'curse',
      'โรดไอแลนด์',
      'Rhode Island',
      'นิวพอร์ต',
      'Newport',
      41.4552,
      -71.3065,
      'creepy_wind',
      'ปราสาทเบลคอร์ท คฤหาสน์หรูยุคทองสไตล์ฝรั่งเศส มีห้องบอลรูมที่รวบรวมของเก่าโบราณจากทั่วยุโรป สิ่งที่น่ากลัวที่สุดคือเก้าอี้สองตัวสไตล์โกธิกที่มีวิญญาณสิงสถิต ผู้ใดที่พยายามนั่งลงจะถูกพลังงานที่มองไม่เห็นผลักจนล้มลงกับพื้นอย่างรุนแรง บางคนรู้สึกเหมือนนั่งทับร่างคนที่เย็นเฉียบและหายใจไม่ออก นอกจากนี้ยังมีชุดเกราะอัศวินโบราณที่ส่งเสียงกรีดร้องโหยหวนและขยับเองได้ในยามค่ำคืน',
      'Belcourt Castle, a 60-room Gilded Age mansion in Newport, houses two infamous Gothic chairs imbued with dark spectral energy. Anyone attempting to sit in them feels an intense icy draft followed by an unseen force violently ejecting them onto the floor. Visitors have reported nausea and the suffocating feeling of sitting directly on another person''s unseen body, alongside screams emanating from an antique suit of armor.',
      'ปราสาทเบลคอร์ทสร้างขึ้นในปี 1894 โดย โอลิเวอร์ ฮาซาร์ด เพอร์รี เบลมอนต์ เป็นศูนย์รวมของสะสมโบราณที่นำเข้ามาจากปราสาทและโบสถ์เก่าในยุโรป ซึ่งมักเชื่อว่าเป็นที่มาของพลังงานลึกลับที่ติดมากับวัตถุ',
      'Designed by Richard Morris Hunt for Oliver Belmont, the mansion features an eclectic collection of authentic European medieval relics that are believed to have retained historical psychic trauma.',
      'ห้ามนั่งลงบนเก้าอี้โกธิกโบราณในห้องบอลรูม',
      'Never attempt to sit upon the Gothic chairs in the ballroom.',
      'https://i.ytimg.com/vi/L3LAKHmbzuY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/L3LAKHmbzuY/hqdefault.jpg","title":"เก้าอี้อาถรรพ์ผลักคนล้มแห่งปราสาทเบลคอร์ท"},{"type":"youtube","url":"https://www.youtube.com/watch?v=L3LAKHmbzuY","title":"The Dark Secrets of Belcourt: America''s Haunted Castle","thumbnail":"https://i.ytimg.com/vi/L3LAKHmbzuY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-dudleytown-dark-entry',
      'ดัดลีย์ทาวน์ ป่ามืดต้องคำสาปแห่งคอนเนตทิคัต',
      'Dudleytown & The Dark Entry Forest Hex',
      'curse',
      'คอนเนตทิคัต',
      'Connecticut',
      'คอร์นวอลล์',
      'Cornwall',
      41.8153,
      -73.3444,
      'jungle_curse',
      'หมู่บ้านร้างที่ซ่อนตัวอยู่ในป่าดาร์กเอนทรี ก่อตั้งโดยลูกหลานของ เอ็ดมันด์ ดัดลีย์ ขุนนางอังกฤษที่ถูกตัดหัวในข้อหากบฏ และเชื่อว่ามีคำสาปสืบทอดทางสายเลือด ชาวบ้านในดัดลีย์ทาวน์ต้องเผชิญกับโศกนาฏกรรมต่อเนื่อง ทั้งการฆ่าตัวตาย อาการคลุ้มคลั่งเห็นภาพหลอน โรคระบาด และฟ้าผ่าบ้านเรือนจนวอดวาย ในที่สุดเมืองก็ถูกทิ้งร้างกลายเป็นเมืองผี ปัจจุบันป่าแห่งนี้เงียบสงัดไร้เสียงนกร้อง และมีพลังงานลบกดดันจนผู้บุกรุกมักเป็นลมหมดสติ',
      'Settled in the mid-1700s by the descendants of Edmund Dudley—beheaded for treason in England—Dudleytown became cursed ground. Settlers suffered waves of madness, hallucinations of demons in the dense forest, bizarre suicides, and fatal lightning strikes. The settlement was completely abandoned. Today, the Dark Entry Forest is eerily devoid of wildlife and bird songs, with trespassers experiencing profound nausea, disorientation, and phantom claw marks.',
      'ดัดลีย์ทาวน์ปัจจุบันเป็นพื้นที่ป่าส่วนบุคคลที่ปิดห้ามบุคคลภายนอกเข้าโดยเด็ดขาด ตำนานคำสาปของตระกูลดัดลีย์ได้รับการบันทึกและสืบสวนโดย เอ็ด และ ลอร์เรน วอร์เรน ซึ่งยกให้เป็นหนึ่งในสถานที่ต้องคำสาปที่อันตรายที่สุดในอเมริกา',
      'The Dark Entry Association enforces strict no-trespassing rules with police patrols. Famed demonologists Ed and Lorraine Warren investigated Dudleytown and declared the land thoroughly demonically tainted.',
      'ห้ามบุกรุกเข้าไปในเขตกักกันดัดลีย์ทาวน์ หรือเก็บหินและใบไม้ออกมา',
      'Never trespass into Dudleytown or take stones and wood from the dark forest.',
      'https://i.ytimg.com/vi/6LBnbV2yKYY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/6LBnbV2yKYY/hqdefault.jpg","title":"ดัดลีย์ทาวน์ ป่ามืดต้องคำสาปแห่งคอนเนตทิคัต"},{"type":"youtube","url":"https://www.youtube.com/watch?v=6LBnbV2yKYY","title":"The Untold Story Of Dudleytown - Connecticut (CT)","thumbnail":"https://i.ytimg.com/vi/6LBnbV2yKYY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-silverpilen-ghost-train',
      'ซิลเวอร์พิเลน รถไฟผีสีเงินแห่งสตอกโฮล์ม',
      'The Silverpilen (Silver Arrow Cursed Ghost Train of Stockholm)',
      'curse',
      'สตอกโฮล์ม',
      'Stockholm',
      'สตอกโฮล์ม',
      'Stockholm',
      59.3293,
      18.0686,
      'creepy_wind',
      'รถไฟใต้ดินขบวนอะลูมิเนียมสีเงินแวววาวที่สร้างขึ้นในยุค 1960 โดยไม่มีการพ่นสีเขียวเหมือนขบวนอื่น จึงดูแปลกแยกและน่าขนลุก ตำนานเมืองสตอกโฮล์มเล่าว่า หากใครขึ้นรถไฟซิลเวอร์พิเลนหลังเที่ยงคืน จะพบว่าผู้โดยสารทุกคนในขบวนล้วนมีใบหน้าซีดเผือดไร้วิญญาณ รถไฟจะไม่ยอมจอดที่สถานีใดๆ เลย ยกเว้นสถานีร้าง คึมลิงเง (Kymlinge) ซึ่งเป็น ''สถานีของคนตาย'' ผู้ที่ก้าวขึ้นไปอาจหายสาบสูญไปนับสิบปี หรือเมื่อกลับออกมาเวลาบนโลกจะผ่านไปแล้วหลายปี',
      'The Silverpilen (Silver Arrow) was an unpainted, silvery aluminum subway train built in the 1960s that contrasted sharply with Stockholm''s typical green fleet. According to urban legend, boarding this train late at night is a one-way trip: the train only stops at Kymlinge, the infamous unfinished ghost station ''built only for the dead.'' Passengers inside appear vacant and spectral, and anyone trapped on board is doomed to ride the underground darkness for eternity.',
      'รถไฟรุ่น C5 ถูกสร้างขึ้นจริงเพื่อทดสอบระบบ แต่เนื่องจากรูปลักษณ์สีเงินเงาวับไร้สีสันและเสียงวิ่งที่โหยหวนในอุโมงค์ ประกอบกับสถานีคึมลิงเงที่ถูกสร้างแต่ไม่เคยเปิดใช้งาน จึงก่อให้เกิดตำนานเมืองที่โด่งดังที่สุดของสวีเดน',
      'The unpainted C5 aluminum train prototype ran sporadically until 1996. The myth was cemented by the abandoned station of Kymlinge, which locals famously said was ''where only the dead alight.''',
      'ห้ามก้าวขึ้นรถไฟใต้ดินสีเงินที่ไร้ป้ายสถานีหลังเวลาเที่ยงคืน',
      'Never board an unpainted silver train speeding through empty tunnels past midnight.',
      'https://i.ytimg.com/vi/qDxApL8F1fg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/qDxApL8F1fg/hqdefault.jpg","title":"ซิลเวอร์พิเลน รถไฟผีสีเงินแห่งสตอกโฮล์ม"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qDxApL8F1fg","title":"Silverpilen: The Ghost Train That Haunts Stockholm","thumbnail":"https://i.ytimg.com/vi/qDxApL8F1fg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-vyne-ring-silvianus',
      'แหวนแห่งซิลเวียนุส (แหวนต้องคำสาปต้นแบบแห่งเดอะลอร์ดออฟเดอะริงส์)',
      'The Curse of the Ring of Silvianus (The Vyne Ring)',
      'curse',
      'แฮมป์เชอร์',
      'Hampshire',
      'เบซิงสโตค',
      'Basingstoke',
      51.3093,
      -1.0963,
      'whisper',
      'แหวนทองคำโรมันโบราณขนาดใหญ่ที่ขุดพบในไร่ใกล้เมืองซิลเชสเตอร์ สลักอักษรละตินว่า ''เซนิเซียนุส จงมีชีวิตอยู่ในพระเจ้า'' ทว่าในวิหารโรมันที่ลิคนีย์ ได้มีการค้นพบแผ่นตะกั่วจารึกคำสาปของเจ้าของเดิมนามว่า ซิลเวียนุส ระบุว่า: ''ผู้ใดที่ขโมยแหวนไป หรือแม้แต่รู้เห็น อย่าได้มีสุขภาพดีจนกว่าจะนำแหวนกลับมาคืนเทพเจ้าโนเดนส์'' แหวนนี้เป็นแรงบันดาลใจให้ เจ.อาร์.อาร์. โทลคีน ผู้ได้รับการขอร้องให้ช่วยแปลจารึกคำสาป สร้างสรรค์เรื่องราวของ ''แหวนเอกธำมรงค์'' ขึ้นมา',
      'Unearthed in 1785, this massive Roman gold signet ring bears the name Senicianus. Decades later at a Roman temple 80 miles away, archaeologists found a curse tablet inscribed by a Roman named Silvianus: ''Among who bears the name Senicianus to whom no health permit until he brings back the ring to the temple of Nodens.'' In 1929, J.R.R. Tolkien investigated the curse tablet and ring, directly inspiring his creation of The One Ring in The Hobbit and The Lord of the Rings.',
      'แหวนซิลเวียนุสและแผ่นตะกั่วคำสาปโบราณเป็นหลักฐานทางประวัติศาสตร์จริง ปัจจุบันแหวนถูกเก็บรักษาไว้ที่คฤหาสน์เดอะไวน์ (The Vyne) ภายใต้การดูแลของเนชันแนลทรัสต์',
      'The Vyne Ring is considered one of the primary historical and mythological sparks for modern fantasy literature, linking real Roman defixiones (curse tablets) with Tolkien''s masterwork.',
      'ห้ามขโมยหรือเก็บรักษาของที่มีคำสาปจารึกถวายเทพเจ้าโบราณ',
      'Never covet or withhold consecrated relics inscribed with ancient divine curses.',
      'https://i.ytimg.com/vi/Jb_qQCmca1g/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Jb_qQCmca1g/hqdefault.jpg","title":"แหวนแห่งซิลเวียนุส (แหวนต้องคำสาปต้นแบบแห่งเดอะลอร์ดออฟเดอะริงส์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Jb_qQCmca1g","title":"The Cursed Ring that inspired J.R.R. Tolkien | The Ring of Silvianus","thumbnail":"https://i.ytimg.com/vi/Jb_qQCmca1g/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-amber-room-tsarskoye',
      'คำสาปห้องสีอำพันแห่งซาร์สโกเย เซโล',
      'The Curse of the Lost Amber Room',
      'curse',
      'เซนต์ปีเตอร์สเบิร์ก',
      'Saint Petersburg',
      'พุชกิน',
      'Pushkin',
      59.7158,
      30.3957,
      'creepy_wind',
      'ห้องสีอำพันอันวิจิตรตระการตาที่สร้างจากแผงอำพันแท้กว่า 6 ตัน ประดับทองคำเปลวและอัญมณีล้ำค่า ได้รับการยกย่องเป็นสิ่งมหัศจรรย์อันดับ 8 ของโลก ในสงครามโลกครั้งที่ 2 กองทัพนาซีได้รื้อถอนห้องนี้ไปจากพระราชวังแคทเธอรีน และขนย้ายไปยังปราสาทเคอนิกส์แบร์ก ก่อนจะสูญหายไปอย่างไร้ร่องรอย ทว่าผู้ที่เกี่ยวข้องกับการตามหาหรือครอบครองห้องสีอำพันต่างเสียชีวิตอย่างลึกลับ ทั้งถูกสังหาร เป็นโรคประหลาด หรือเครื่องบินตก',
      'The legendary Amber Room, constructed with over six tons of golden amber backed with gold leaf, was gifted to Peter the Great in 1716. Looted by Nazi troops in 1941 and sent to Königsberg Castle, it vanished during the chaos of 1945. A lethal curse reportedly stalked anyone seeking it: curator Alfred Rohde died of a sudden plague, KGB investigator Genrikh Brushtein died under mysterious circumstances, and amber hunter Georg Stein was brutally murdered in a German forest.',
      'ในปี 2003 รัฐบาลรัสเซียได้สร้างห้องสีอำพันจำลองขึ้นใหม่ทั้งหมดในพระราชวังแคทเธอรีน โดยใช้งบประมาณมหาศาลและช่างฝีมือชั้นสูง ในขณะที่ชิ้นส่วนของห้องดั้งเดิมยังคงเป็นปริศนาที่มืดมนที่สุดของสมบัติสงคราม',
      'After decades of fruitless searches and mysterious deaths, artisans reconstructed the Amber Room over 24 years. The original panels remain the Holy Grail of lost wartime treasures.',
      'ห้ามกักตุนหรือครอบครองสมบัติที่ได้มาจากการปล้นสะดมในสงคราม',
      'Never pursue or hoard sacred cultural treasures stolen during wartime carnage.',
      'https://i.ytimg.com/vi/QE0F0o9yuPk/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/QE0F0o9yuPk/hqdefault.jpg","title":"คำสาปห้องสีอำพันแห่งซาร์สโกเย เซโล"},{"type":"youtube","url":"https://www.youtube.com/watch?v=QE0F0o9yuPk","title":"The Mystery Of The Amber Room - A Short Documentary","thumbnail":"https://i.ytimg.com/vi/QE0F0o9yuPk/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-conjured-chest-kentucky',
      'หีบอาถรรพ์สังหาร 16 ศพแห่งเคนทักกี (หีบต้องคำสาป)',
      'The Conjured Chest of Kentucky (16 Fatalities Curse)',
      'curse',
      'เคนทักกี',
      'Kentucky',
      'แฟรงก์ฟอร์ต',
      'Frankfort',
      38.2009,
      -84.8733,
      'creepy_wind',
      'หีบไม้โบราณที่สั่งทำโดย เจค็อบ คูลส์ เจ้าของไร่ในศตวรรษที่ 19 เขาไม่พอใจในฝีมือของทาสผิวดำนามว่า เรมุส จึงโบยตีจนเสียชีวิต เพื่อนทาสคนอื่นๆ จึงร่วมกันร่ายมนต์คำสาปดำใส่หีบใบนี้เพื่อแก้แค้น โดยสาปให้ผู้ใดที่เก็บเสื้อผ้าไว้ในหีบจะต้องสังเวยชีวิต ตลอดระยะเวลากว่า 150 ปี มีสมาชิกในครอบครัวและผู้ครอบครองหีบนี้เสียชีวิตถึง 16 คน รวมถึงทารกที่คลอดออกมาตาย จนกระทั่งหีบถูกส่งมอบให้พิพิธภัณฑ์ประวัติศาสตร์เคนทักกีและประกอบพิธีสะกดคำสาป',
      'Commissioned in the 1830s by plantation owner Jacob Cools, this walnut chest was built by an enslaved craftsman named Remus. Dissatisfied with the work, Cools beat Remus to death. In retaliation, an enslaved conjurer performed an owl curse over the chest. Over the next century, 16 relatives who placed garments inside the chest died prematurely from accidents, mysterious illnesses, and suicides until the curse was ritually broken by an African conjurer in 1976.',
      'หีบใบนี้ได้รับการจัดแสดงที่สมาคมประวัติศาสตร์เคนทักกี (Kentucky Historical Society) โดยมีการบันทึกรายชื่อผู้เสียชีวิตทั้ง 16 รายไว้อย่างชัดเจนในเอกสารทางประวัติศาสตร์ของตระกูล',
      'Now housed in the Kentucky Historical Society in Frankfort, the chest is displayed behind protective barriers, retaining its infamous reputation in Appalachian folklore.',
      'ห้ามนำเสื้อผ้าหรือสิ่งของส่วนตัวไปเก็บไว้ในหีบต้องสาป',
      'Never place clothing or personal belongings inside the conjured chest.',
      'https://i.ytimg.com/vi/lvtfLA9vQ9s/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/lvtfLA9vQ9s/hqdefault.jpg","title":"หีบอาถรรพ์สังหาร 16 ศพแห่งเคนทักกี (หีบต้องคำสาป)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=lvtfLA9vQ9s","title":"The Conjured Chest","thumbnail":"https://i.ytimg.com/vi/lvtfLA9vQ9s/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-blackbeard-treasure-ocracoke',
      'คำสาปขุมทรัพย์โจรสลัดเคราดำแห่งเกาะโอคราโคก',
      'The Curse of Blackbeard''s Lost Treasure (Ocracoke Island)',
      'curse',
      'นอร์ทแคโรไลนา',
      'North Carolina',
      'เกาะโอคราโคก',
      'Ocracoke Island',
      35.1146,
      -75.9813,
      'water_spirit',
      'ก่อนที่โจรสลัดเคราดำ (เอ็ดเวิร์ด ทีช) จะถูกตัดหัวในการรบที่เกาะโอคราโคกในปี 1718 เขาได้กล่าวไว้ว่า ''ไม่มีใครในโลกรู้ว่าขุมทรัพย์ของข้าซ่อนอยู่ที่ใด มีเพียงตัวข้ากับซาตานเท่านั้น และผู้ที่รอดชีวิตจะได้มันไป'' ตำนานเล่าว่าร่างไร้หัวของเคราดำว่ายน้ำวนรอบเรือสามรอบก่อนจมลงสู่ก้นทะเล และผู้ใดก็ตามที่พยายามขุดค้นสมบัติของเขาตามแนวชายหาด จะได้ยินเสียงหัวเราะเยือกเย็นและถูกพายุซัดจนเสียชีวิตอย่างสยดสยอง',
      'Before pirate captain Edward Teach (Blackbeard) was slain and decapitated at Teach''s Hole in 1718, he boasted that his buried hoard was known only to himself and the Devil. Local lore claims his headless body swam three times around Lieutenant Maynard''s sloop before sinking. Those who hunt his gold among the shifting dunes of Ocracoke report eerie ball-lightning, phantom footfalls, and fatal drownings near the inlets.',
      'ซากเรือควีนแอนส์รีเวนจ์ (Queen Anne''s Revenge) ของเคราดำถูกค้นพบในปี 1996 นอกชายฝั่งโบฟอร์ต แต่ทองคำและอัญมณีมหาศาลที่ถูกปล้นมายังคงสูญหายไปในประวัติศาสตร์',
      'Blackbeard''s final battle took place off Ocracoke Island. The legend of his headless swimming ghost and cursed hoard remains a centerpiece of Outer Banks folklore.',
      'ห้ามขุดทรายค้นหาสมบัติในคืนเดือนดับบริเวณทีชส์โฮล (Teach''s Hole)',
      'Never search for pirate plunder at Teach''s Hole during a new moon.',
      'https://i.ytimg.com/vi/W8zsKaj0_k4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/W8zsKaj0_k4/hqdefault.jpg","title":"คำสาปขุมทรัพย์โจรสลัดเคราดำแห่งเกาะโอคราโคก"},{"type":"youtube","url":"https://www.youtube.com/watch?v=W8zsKaj0_k4","title":"Could Blackbeard''s Treasure Lay at the Bottom of the Sea? | History''s Greatest Mysteries (Season 4)","thumbnail":"https://i.ytimg.com/vi/W8zsKaj0_k4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-black-dog-hanging-hills',
      'คำสาปหมาดำแห่งแฮงกิงฮิลส์ (ลางมรณะพบสามครั้งต้องตาย)',
      'The Black Dog of the Hanging Hills Death Curse',
      'curse',
      'คอนเนตทิคัต',
      'Connecticut',
      'เมริเดน',
      'Meriden',
      41.5582,
      -72.8368,
      'creepy_wind',
      'ตำนานสุนัขสีดำตัวเล็กที่ไร้รอยเท้าและไร้เสียงเห่า เดินเพ่นพ่านอยู่บนหน้าผาหินบะซอลต์ของแฮงกิงฮิลส์ คำสาประบุไว้ว่า ''พบครั้งแรกจะนำความสุขมาให้ พบครั้งที่สองจะนำความเศร้าโศก และหากพบเป็นครั้งที่สาม ความตายจะมาเยือนในไม่ช้า'' ในศตวรรษที่ 19 นักธรณีวิทยาผู้ไม่เชื่อเรื่องผีได้ขึ้นเขาและพบสุนัขดำเป็นครั้งที่สาม ไม่กี่นาทีต่อมาเขาพลัดตกจากหน้าผาสูงเสียชีวิตคาที่อย่างน่าสยดสยอง',
      'In the traprock ridges of Meriden''s Hanging Hills wanders a small, silent black dog that leaves no tracks in snow or mud. Appalachian folklore warns: ''If you see the Black Dog once, it shall be for joy; if twice, it shall be for sorrow; and if you see it the third time, it shall bring you death.'' Several recorded hikers and geologists fell to their deaths from the crags moments after witnessing the creature for the third time.',
      'เรื่องเล่านี้ได้รับการตีพิมพ์ครั้งแรกในนิตยสาร The Connecticut Quarterly ในปี 1898 โดย ดับเบิลยู. เอช. ซี. พิช และถือเป็นหนึ่งในตำนานลางมรณะ (Barghest/Grim) ที่สืบทอดมาจากคติชนบริเตน',
      'Written down by geologist W.H.C. Pynchon in 1898, the tale blends British Black Shuck mythology with the rugged basalt geology of New England.',
      'หากพบสุนัขดำบนยอดเขาแฮงกิงฮิลส์ อย่าหันกลับไปมองหรือขึ้นเขาซ้ำเป็นครั้งที่สาม',
      'If you encounter the silent Black Dog, turn back immediately and never return.',
      'https://i.ytimg.com/vi/6j-F5PgJ9QY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/6j-F5PgJ9QY/hqdefault.jpg","title":"คำสาปหมาดำแห่งแฮงกิงฮิลส์ (ลางมรณะพบสามครั้งต้องตาย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=6j-F5PgJ9QY","title":"They Say This Ghost Dog Brings Death – Hanging Hills Mystery | The Grim Tapes |","thumbnail":"https://i.ytimg.com/vi/6j-F5PgJ9QY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-maco-light-signalman',
      'แสงไฟอาถรรพ์แห่งมาโก (วิญญาณคนให้สัญญาณรถไฟไร้หัว)',
      'The Ghostly Maco Light & Joe Baldwin''s Lantern',
      'curse',
      'นอร์ทแคโรไลนา',
      'North Carolina',
      'มาโก',
      'Maco',
      34.2371,
      -78.1008,
      'whisper',
      'ในปี 1867 โจ บอลด์วิน พนักงานให้สัญญาณรถไฟ สละชีวิตด้วยการโบกตะเกียงเตือนภัยเพื่อหยุดขบวนรถไฟที่กำลังพุ่งชนตู้โบกี้ด้านหลัง ทว่ารถไฟหยุดไม่ทันทำให้เขาถูกชนจนศีรษะขาดกระเด็น นับแต่นั้นตลอดแนวทางรถไฟมาโก จะมีดวงไฟสลัวสีเหลืองลอยขึ้นลงเหนือรางรถไฟ คล้ายคนกำลังแกว่งตะเกียงเพื่อตามหาศีรษะของตนเอง แม้แต่ประธานาธิบดี โกรเวอร์ คลีฟแลนด์ ก็เคยมาชมปรากฏการณ์ลึกลับนี้ด้วยตาตนเอง',
      'In 1867, train conductor Joe Baldwin realized his train car had detached and a locomotive was speeding behind him. He stood bravely on the platform swinging his lantern to warn the engineer, but was decapitated in the crash. Soon after, an eerie phantom light was witnessed swinging along the tracks near Maco Station, believed to be Joe''s headless ghost endlessly searching for his severed head.',
      'แสงไฟมาโกเป็นปรากฏการณ์ผีรางรถไฟที่ได้รับการบันทึกมากที่สุดในประวัติศาสตร์สหรัฐฯ มีการส่งเจ้าหน้าที่วิทยาศาสตร์และกองทัพมาพิสูจน์หลายครั้ง จนกระทั่งรางรถไฟถูกรื้อถอนในปี 1977 แสงไฟจึงค่อยๆ จางหายไป',
      'President Grover Cleveland observed the phenomenon in 1889. The Maco Light was documented by train crews and paranormal researchers until the tracks were dismantled in 1977.',
      'ห้ามยืนขวางทางเดินของแสงไฟ หรือพยายามส่องไฟฉายท้าทาย',
      'Never stand in the middle of the old rail bed or flash artificial lights at the entity.',
      'https://i.ytimg.com/vi/52pSJI8V5Kc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/52pSJI8V5Kc/hqdefault.jpg","title":"แสงไฟอาถรรพ์แห่งมาโก (วิญญาณคนให้สัญญาณรถไฟไร้หัว)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=52pSJI8V5Kc","title":"The TRUE Story of the Maco Light...It Will Shock You.(E-7)","thumbnail":"https://i.ytimg.com/vi/52pSJI8V5Kc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-lake-lanier-curse',
      'คำสาปทะเลสาบเลเนียร์ (เมืองจมน้ำและสุสานใต้บาดาล)',
      'The Curse of Lake Lanier (Submerged Towns & Drownings)',
      'curse',
      'จอร์เจีย',
      'Georgia',
      'บิวฟอร์ด',
      'Buford',
      34.2052,
      -84.0628,
      'water_spirit',
      'ทะเลสาบที่มนุษย์สร้างขึ้นในปี 1956 โดยการสร้างเขื่อนทับเมืองเก่า ชุมชนคนผิวดำ และสุสานนับสิบแห่ง มีหลุมศพและซากอาคารนับพันที่จมอยู่ใต้ผืนน้ำสีเขียวคล้ำ ทะเลสาบแห่งนี้มีสถิติคนจมน้ำเสียชีวิตสูงผิดปกติกว่า 700 ราย นักดำน้ำเล่าว่ามักเห็นมือลึกลับพยายามฉุดขาลงสู่ก้นน้ำ และมีวิญญาณหญิงสาวไร้แขนเดินเพ่นพ่านริมท่าเรือ เชื่อกันว่าเป็นแรงอาถรรพ์ของบรรพบุรุษที่โกรธแค้นจากการถูกปล่อยให้จมบาดาล',
      'Created by the Army Corps of Engineers in the 1950s, Lake Lanier flooded entire towns, farmlands, and sacred cemeteries, leaving submerged forests and tombstones beneath murky depths. Over 700 people have mysteriously drowned in its waters. Divers describe feeling cold ghostly hands grabbing at their ankles, while boaters report phantom tugs on hulls and sightings of the ''Lady of the Lake'' wandering the shores.',
      'ประวัติศาสตร์อันดำมืดของการขับไล่ชาวแอฟริกันอเมริกันในเขตฟอร์ไซธ์ปี 1912 และการท่วมทับเมืองออสการ์วิลล์ เป็นรากเหง้าของความเชื่อเรื่องคำสาปแห่งทะเลสาบเลเนียร์',
      'The flooding submerged Oscarville, a historically displaced Black community. The grim drowning rate has solidified Lake Lanier''s standing as one of the most cursed bodies of water in North America.',
      'ห้ามลงเล่นน้ำคนเดียวในเวลากลางคืน หรือดูหมิ่นสุสานที่จมอยู่ใต้น้ำ',
      'Never swim alone at night or disturb submerged cemetery remnants.',
      'https://i.ytimg.com/vi/ZGjDvIK31pA/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/ZGjDvIK31pA/hqdefault.jpg","title":"คำสาปทะเลสาบเลเนียร์ (เมืองจมน้ำและสุสานใต้บาดาล)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=ZGjDvIK31pA","title":"Hidden Truth of Lake Lanier: The Oscarville Documentary","thumbnail":"https://i.ytimg.com/vi/ZGjDvIK31pA/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-devils-tree-bernards',
      'ต้นไม้ปิศาจแห่งเบอร์นาร์ดส์ (ต้นโอ๊กอาถรรพ์ที่ไม่เคยมีหิมะเกาะ)',
      'The Devil''s Tree of Bernards Township',
      'curse',
      'นิวเจอร์ซีย์',
      'New Jersey',
      'เบอร์นาร์ดส์',
      'Bernards',
      40.6626,
      -74.5829,
      'creepy_wind',
      'ต้นโอ๊กโดดเดี่ยวกลางทุ่งกว้างที่มีตำนานเล่าว่า ในอดีตถูกใช้เป็นที่แขวนคอสังหารทาสผิวดำ และเป็นจุดนัดพบของกลุ่มเคเคเค (KKK) เพื่อทำพิธีกรรมสังเวยวิญญาณ ความแปลกประหลาดคือ ในฤดูหนาวที่มีพายุหิมะตกหนัก หิมะจะไม่สามารถเกาะบนกิ่งก้านของต้นไม้นี้ได้เลย และลำต้นจะอุ่นตลอดเวลา ใครก็ตามที่พยายามใช้ขวานตัดต้นไม้ หรือแม้แต่ปัสสาวะรดโคนต้น จะประสบอุบัติเหตุทางรถยนต์ชนต้นไม้ในละแวกนั้นจนเสียชีวิตทันทีที่ขับรถออกไป',
      'Standing lonely in an open Somerset County field, this gnarled oak tree was reportedly used for lynching enslaved people and as a ritual site for the Ku Klux Klan. Local lore asserts the tree is unnaturally warm to the touch, causing falling snow to instantly melt upon its branches. Anyone who insults, defaces, or chops at the bark is said to suffer sudden fatal car crashes on their journey home.',
      'ต้นไม้ปิศาจแห่งนี้ปรากฏในนิตยสาร Weird NJ และกลายเป็นตำนานพื้นบ้านที่ชาวเมืองนิวเจอร์ซีย์รู้จักกันดี รอยฟันและรอยขวานที่ปรากฏบนลำต้นสะท้อนถึงผู้คนที่พยายามทำลายต้นไม้แต่ไม่สำเร็จ',
      'Featured extensively in Weird NJ, the tree bears deep chain-saw scars from townsfolk who attempted to fell it, only to report sudden equipment failures and menacing black phantom trucks chasing them.',
      'ห้ามทำลายเปลือกไม้ ทุบตี หรือลบหลู่ต้นโอ๊กปิศาจเด็ดขาด',
      'Never strike, urinate on, or attempt to cut down the Devil''s Tree.',
      'https://i.ytimg.com/vi/4AltbMZXzBk/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/4AltbMZXzBk/hqdefault.jpg","title":"ต้นไม้ปิศาจแห่งเบอร์นาร์ดส์ (ต้นโอ๊กอาถรรพ์ที่ไม่เคยมีหิมะเกาะ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=4AltbMZXzBk","title":"The Devil Tree","thumbnail":"https://i.ytimg.com/vi/4AltbMZXzBk/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-petrified-forest-bad-luck',
      'คำสาปซากไม้กลายเป็นหินแห่งแอริโซนา (กองหินสำนึกบาป)',
      'The Conscience Piles & Bad Luck Curse of Petrified Forest',
      'curse',
      'แอริโซนา',
      'Arizona',
      'โฮลบรูค',
      'Holbrook',
      35.0654,
      -109.7831,
      'whisper',
      'อุทยานแห่งชาติเพทริฟายด์ฟอเรสต์เต็มไปด้วยท่อนไม้โบราณอายุ 200 ล้านปีที่กลายเป็นอัญมณีหินหลากสีสัน ทว่ามีคำสาปของชนเผ่าพื้นเมืองว่า ''ใครก็ตามที่ขโมยเศษไม้กลายเป็นหินออกไปจากแผ่นดินศักดิ์สิทธิ์นี้ จะต้องเผชิญกับเคราะห์ร้าย แตกแยก ล้มละลาย และความตาย'' ในแต่ละปี เจ้าหน้าที่อุทยานได้รับพัสดุหลายร้อยกล่องจากทั่วโลก บรรจุเศษหินที่ถูกขโมยไปพร้อมจดหมายขอขมาและเล่าถึงโชคร้ายสยองที่เกิดขึ้นจนต้องส่งหินกลับคืน',
      'Spanning painted badlands, the Petrified Forest holds radiant 200-million-year-old fossilized tree trunks. Navajo and Hopi folklore warned that the land is guarded by ancestral spirits. Visitors who pocket even small fragments inevitably suffer catastrophic bad luck: bankruptcies, sudden illnesses, fractured bones, and ruined lives. The park receives hundreds of pounds of returned stone by mail each year, accompanied by desperate apology letters.',
      'จดหมายขอขมาและพัสดุส่งหินคืนถูกจัดเก็บและแสดงไว้ที่ศูนย์บริการนักท่องเที่ยว ซึ่งเจ้าหน้าที่เรียกเศษหินที่ถูกส่งคืนเหล่านี้ว่า ''กองหินแห่งความสำนึกผิด'' (Conscience Piles)',
      'Park rangers compiled these letters into the archive ''Bad Luck, Hot Rocks.'' The sheer volume of returned artifacts makes it one of the world''s most geographically verified curse phenomena.',
      'ห้ามหยิบหรือนำเศษไม้กลายเป็นหินออกจากเขตอุทยานแม้แต่ชิ้นเดียว',
      'Never remove any petrified wood or mineral fragments from the national park.',
      'https://i.ytimg.com/vi/3u2ABgMyGz0/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/3u2ABgMyGz0/hqdefault.jpg","title":"คำสาปซากไม้กลายเป็นหินแห่งแอริโซนา (กองหินสำนึกบาป)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=3u2ABgMyGz0","title":"Letters from ''cursed'' national park visitors | The Conscience Files","thumbnail":"https://i.ytimg.com/vi/3u2ABgMyGz0/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-poltergeist-movie-curse',
      'คำสาปภาพยนตร์โพลเทอร์ไกสท์ (โครงกระดูกจริงในกองถ่าย)',
      'The Hollywood Poltergeist Movie Curse',
      'curse',
      'แคลิฟอร์เนีย',
      'California',
      'ลอสแอนเจลิส',
      'Los Angeles',
      34.0522,
      -118.2437,
      'creepy_wind',
      'หนึ่งในภาพยนตร์สยองขวัญคลาสสิกที่โด่งดังที่สุดในประวัติศาสตร์ฮอลลีวูด แต่กลับถูกปกคลุมด้วยคำสาปมรณะ เนื่องจากทีมงานตัดสินใจใช้ ''โครงกระดูกมนุษย์จริง'' ในฉากสระว่ายน้ำโคลนเพื่อประหยัดต้นทุน หลังจากนั้นนักแสดงนำและทีมงานต้องเผชิญกับความตายอันน่าสะพรึง โดยเฉพาะ โดมินิก ดันน์ ถูกแฟนเก่าบีบคอเสียชีวิตหลังหนังฉายไม่กี่เดือน และนักแสดงเด็ก เฮเทอร์ โอรัวร์ เสียชีวิตอย่างกะทันหันในวัยเพียง 12 ปี',
      'During production of Steven Spielberg and Tobe Hooper''s 1982 classic ''Poltergeist'', real biological human skeletons were used in the muddy swimming pool climax because they were cheaper than plastic replicas. Soon after, a string of tragic deaths claimed the cast: 22-year-old Dominique Dunne was strangled by an ex-boyfriend, and 12-year-old lead star Heather O''Rourke died abruptly of septic shock, fueling the legend of an authentic cinematic hex.',
      'คำสาปโพลเทอร์ไกสท์กลายเป็นหนึ่งในตำนานเมืองของฮอลลีวูดที่ได้รับการพูดถึงมากที่สุด ควบคู่ไปกับภาพยนตร์ The Exorcist และ The Omen โดยได้รับการสืบสวนและสร้างเป็นสารคดีหลายครั้ง',
      'The tragic demise of four principal cast members across the trilogy cemented ''The Poltergeist Curse'' as one of modern cinema''s most spine-chilling real-world legends.',
      'ห้ามนำโครงกระดูกมนุษย์จริงมาใช้ในเชิงบันเทิงหรือลบหลู่ศพคนตาย',
      'Never desecrate or commodify real human remains for entertainment or theater.',
      'https://i.ytimg.com/vi/n02NbIaaaF4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/n02NbIaaaF4/hqdefault.jpg","title":"คำสาปภาพยนตร์โพลเทอร์ไกสท์ (โครงกระดูกจริงในกองถ่าย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=n02NbIaaaF4","title":"The Very Real Deaths Behind this Cursed Movie | Poltergeist","thumbnail":"https://i.ytimg.com/vi/n02NbIaaaF4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-bloody-mary-mirror-hex',
      'คำสาปกระจกบลัดดี้ แมรี่ (พิธีกรรมเรียกวิญญาณในเงามืด)',
      'The Folklore Mirror Curse of Bloody Mary',
      'curse',
      'เพนซิลเวเนีย',
      'Pennsylvania',
      'ซอเมอร์เซต',
      'Somerset',
      40.0084,
      -79.0781,
      'whisper',
      'ตำนานพื้นบ้านที่สืบทอดกันมายาวนานเกี่ยวกับการท่องชื่อ ''บลัดดี้ แมรี่'' สามครั้ง (หรือสิบสามครั้ง) หน้ากระจกในห้องน้ำที่จุดเพียงแสงเทียนเล่มเดียว เชื่อกันว่ากระจกจะกลายเป็นประตูมิติให้วิญญาณของแม่มดหรือสตรีผู้เปื้อนเลือดปรากฏตัวขึ้น หากผู้ทำพิธีดวงตก วิญญาณจะกรีดร้อง ข่วนใบหน้าจนเสียโฉม ควักดวงตา หรือดูดกลืนผู้ท้าทายเข้าไปติดอยู่ในกระจกตลอดกาล',
      'One of the most widespread Western folklore rituals involves chanting ''Bloody Mary'' into a mirror in a dark candlelit room. Folklorists trace the ritual to divination customs where young maidens hoped to see their future husband''s face in glass, but risked seeing a skull indicating death. In modern lore, Mary appears as a mutilated witch or phantom drenched in blood, capable of clawing out eyes and trapping souls behind the mirror.',
      'นักจิตวิทยาอธิบายว่าปรากฏการณ์นี้เกิดจาก ''ภาพลวงตาแคปโกรฟ'' (Caputo effect) เมื่อจ้องมองใบหน้าตัวเองในที่มืดสลัวเป็นเวลานาน สมองจะเริ่มบิดเบือนภาพใบหน้าจนกลายเป็นสิ่งน่ากลัว',
      'Studied extensively by folklorist Janet Langlois in 1978, the legend combines psycho-optical illusions (strange-face illusion) with Victorian scrying and witch-lore.',
      'ห้ามเรียกชื่อบลัดดี้แมรี่หน้ากระจกในความมืดพร้อมเทียนไข',
      'Never chant Bloody Mary''s name into a candlelit mirror at midnight.',
      'https://i.ytimg.com/vi/248J2v0eVZI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/248J2v0eVZI/hqdefault.jpg","title":"คำสาปกระจกบลัดดี้ แมรี่ (พิธีกรรมเรียกวิญญาณในเงามืด)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=248J2v0eVZI","title":"Bloody Mary: Origins of the Urban Legend - Extra Mythology","thumbnail":"https://i.ytimg.com/vi/248J2v0eVZI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-yamashita-treasure-benguet',
      'คำสาปทองคำยามาชิตะและกับดักมรณะ (เทือกเขาเบงเกต)',
      'The Curse of Yamashita''s Gold & Hidden Booby Traps',
      'curse',
      'เบงเกต',
      'Benguet',
      'บาเกียว',
      'Baguio',
      16.4023,
      120.596,
      'jungle_curse',
      'ในช่วงท้ายของสงครามโลกครั้งที่ 2 นายพล โทโมยูกิ ยามาชิตะ แห่งกองทัพจักรวรรดิญี่ปุ่น ได้ซ่อนสมบัติทองคำ พระพุทธรูปทองคำ และอัญมณีที่ปล้นมาจากทั่วเอเชียไว้ในถ้ำและอุโมงค์ลับบนเกาะฟิลิปปินส์ พร้อมทั้งฝังทหารช่างและเชลยศึกทั้งเป็นเพื่อปิดปาก และวางกับดักระเบิด สารพิษ และคำสาปเลือด ใครก็ตามที่พยายามขุดค้นสมบัติมักเผชิญกับเหตุดินถล่ม ก๊าซพิษ และอาถรรพ์วิญญาณทหารญี่ปุ่นที่คอยหลอกหลอนจนเสียสติ',
      'As Allied forces advanced in 1945, Japanese General Tomoyuki Yamashita allegedly stashed billions of dollars in looted Asian gold, bullion, and cultural treasures deep within tunnels in Luzon. The engineers who built the underground vaults were buried alive to safeguard the secrets. Treasure hunters attempting to locate the hoards frequently encounter lethal booby traps, cyanide gas vents, and vengeful ghostly soldiers guarding the chambers.',
      'ตำนานทองคำยามาชิตะได้รับการตอกย้ำด้วยคดีฟ้องร้องระดับโลกของ โรเกลิโอ ร็อกแซส ผู้ค้นพบพระพุทธรูปทองคำตันในปี 1971 ก่อนจะถูกยึดไปโดยประธานาธิบดีเฟอร์ดินานด์ มาร์กอส',
      'The story sparked intense international lawsuits, notably Roxas v. Marcos. Deep in the Cordillera mountains, the treasure remains shrouded in historical intrigue and tragic excavations.',
      'ห้ามขุดค้นอุโมงค์ลับที่มีสัญลักษณ์ตราดอกเบญจมาศหรือโครงกระดูกทหารญี่ปุ่น',
      'Never enter unmarked military tunnels marked with Imperial Japanese seals.',
      'https://i.ytimg.com/vi/zSGSvPSVpOE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/zSGSvPSVpOE/hqdefault.jpg","title":"คำสาปทองคำยามาชิตะและกับดักมรณะ (เทือกเขาเบงเกต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=zSGSvPSVpOE","title":"Yamashita''s Gold: The Hunt For Japan''s Buried WW2 Treasure | Myth Hunters | War Stories","thumbnail":"https://i.ytimg.com/vi/zSGSvPSVpOE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-devils-hole-massacre',
      'คำสาปการสังหารหมู่ที่ถ้ำปิศาจ (เดวิลส์โฮล ไนแอการา)',
      'The Curse of Devil''s Hole Massacre (Niagara Gorge)',
      'curse',
      'นิวยอร์ก',
      'New York',
      'ไนแอการา',
      'Niagara',
      43.1362,
      -79.0436,
      'water_spirit',
      'ช่องแคบหินลึกริมแม่น้ำไนแอการาซึ่งชนเผ่าเซเนกาถือเป็นที่สถิตของ ''วิญญาณแห่งความชั่วร้าย'' ตามตำนานเล่าว่าในปี 1679 นักสำรวจชาวฝรั่งเศสได้เข้าไปท้าทายในถ้ำและถูกเตือนว่าจะพบจุดจบอันเลวร้าย ต่อมาในปี 1763 กองทหารและขบวนเกวียนของอังกฤษถูกนักรบพื้นเมืองซุ่มโจมตีจนพุ่งตกลงไปในหุบเหวตายเกลือบ 80 นาย เลือดไหลย้อมลำธารจนกลายเป็นสีแดง เล่ากันว่าผู้ใดที่เข้าไปในถ้ำปิศาจจะถูกคำสาปความวิบัติในชีวิตและได้ยินเสียงกรีดร้องของทหารที่ตกลงไปตาย',
      'The Devil''s Hole is a deep ravine along the Niagara Gorge revered by the Seneca as the domain of the Great Evil Spirit. In 1763, during Pontiac''s Rebellion, a British supply train was ambushed by Native warriors; dozens of wagons, horses, and soldiers were driven over the sheer cliffs into the chasm below, turning the waters red with blood. The site is said to carry an eternal curse of doomed fortunes for anyone who steps into the cave.',
      'เหตุการณ์ Devil''s Hole Massacre เป็นหนึ่งในโศกนาฏกรรมทางทหารที่ร้ายแรงที่สุดในประวัติศาสตร์ยุคอาณานิคมของนิวยอร์ก ปัจจุบันเป็นส่วนหนึ่งของสวนสาธารณะ Devil''s Hole State Park',
      'The Devil''s Hole State Park retains the grim memory of the 1763 ambush. Local legends claim French explorer La Salle visited the cave and was cursed with the betrayal that caused his eventual murder.',
      'ห้ามเข้าไปหลบพักผ่อนหรือทำพิธีลองของภายในถ้ำปิศาจ',
      'Never enter the mouth of Devil''s Hole cave to challenge its ancient spirits.',
      'https://i.ytimg.com/vi/wmcJuRhtCMA/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/wmcJuRhtCMA/hqdefault.jpg","title":"คำสาปการสังหารหมู่ที่ถ้ำปิศาจ (เดวิลส์โฮล ไนแอการา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=wmcJuRhtCMA","title":"The Devil''s Hole Massacre","thumbnail":"https://i.ytimg.com/vi/wmcJuRhtCMA/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-gouffre-de-padirac-devil',
      'กูฟฟร์ เดอ ปาดิรัก (หลุมยุบแห่งพญามารและคำสาปมรณะ)',
      'Gouffre de Padirac (The Devil''s Chasm & Infernal Curse)',
      'curse',
      'ล็อต',
      'Lot',
      'ปาดิรัก',
      'Padirac',
      44.8584,
      1.7515,
      'water_spirit',
      'หลุมยุบขนาดยักษ์ลึกกว่า 100 เมตรที่ปากถ้ำเปิดกว้างสู่แม่น้ำใต้ดินอันลึกลับ ตำนานพื้นบ้านฝรั่งเศสเล่าว่า หลุมนี้ถูกสร้างขึ้นโดยพญามารลูซิเฟอร์ด้วยการกระทืบส้นเท้าลงบนแผ่นดิน เพื่อท้าทายให้นักบุญมาร์ตินกระโดดข้าม หากกระโดดไม่ผ่าน วิญญาณของคนบาปทั้งหมดจะตกเป็นของซาตาน แม้นักบุญจะกระโดดข้ามได้สำเร็จ แต่ก้นเหวยังคงเป็นประตูสู่นรกที่มีไอเย็นยะเยือกและเสียงกรีดร้องของวิญญาณที่ถูกจองจำลอยขึ้นมาในยามค่ำคืน',
      'Plunging over 330 feet into the earth, the Chasm of Padirac leads to a subterranean river network. French medieval folklore says Lucifer stomped his heel into the limestone plateau, creating this immense pit to challenge Saint Martin: if the saint could not jump across, the souls of condemned sinners would belong to hell. Saint Martin''s mule miraculously cleared the chasm, but the abyss retained an infernal aura of dark curses.',
      'กูฟฟร์ เดอ ปาดิรัก ได้รับการสำรวจทางวิทยาศาสตร์ครั้งแรกในปี 1889 โดย เอดัวร์-อัลเฟรด มาร์แตล ปัจจุบันเป็นหนึ่งในแหล่งท่องเที่ยวทางธรรมชาติใต้พิภพที่งดงามและน่าเกรงขามที่สุดในยุโรป',
      'Explored by speleologist Édouard-Alfred Martel in 1889, the chasm features stunning subterranean boat rides beneath crystalline stalactites, steeped in centuries of demonic folklore.',
      'ห้ามพายเรือออกนอกเส้นทางสำรวจเข้าไปในโพรงถ้ำที่ยังไม่ได้ทำแผนที่',
      'Never navigate off-limit branches of the subterranean river alone in the dark.',
      'https://i.ytimg.com/vi/FUX0ojMLgKU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/FUX0ojMLgKU/hqdefault.jpg","title":"กูฟฟร์ เดอ ปาดิรัก (หลุมยุบแห่งพญามารและคำสาปมรณะ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=FUX0ojMLgKU","title":"Animation 1 : How the Gouffre de Padirac was formed ?","thumbnail":"https://i.ytimg.com/vi/FUX0ojMLgKU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-lake-nyos-wrath',
      'ทะเลสาบแห่งมัจจุราชนิออส (โทสะแห่งวิญญาณน้ำคะเมรูน)',
      'The Wrath of the Lake Nyos Water Spirit',
      'curse',
      'นอร์ทเวสต์',
      'Northwest Region',
      'เมนชูม',
      'Menchum',
      6.4389,
      10.2983,
      'whisper',
      'ทะเลสาบปากปล่องภูเขาไฟบนที่ราบสูงแคเมอรูน ซึ่งในตำนานพื้นบ้านดั้งเดิมถือเป็นที่สถิตของวิญญาณบรรพบุรุษและ ''นางพญาน้ำ'' ผู้ดุร้ายที่ห้ามผู้ใดรบกวน ในคืนวันที่ 21 สิงหาคม 1986 ทะเลสาบเกิดการปะทุปล่อยก๊าซคาร์บอนไดออกไซด์มหาศาลกว่า 100,000 ตันออกมาอย่างไร้เสียง เมฆพิษไหลลงสู่หุบเขาคร่าชีวิตชาวบ้านกว่า 1,746 คน และปศุสัตว์นับพันตัวจนเสียชีวิตในท่านอนหลับ ราวกับคำสาปแห่งความตายที่กวาดล้างทุกสิ่งในพริบตา',
      'High on a volcanic plain in Cameroon lies Lake Nyos. Indigenous folklore long warned that an ancient spirit inhabited the water, demanding reverence and threatening doom to any who broke its sacred taboos. On the fateful night of August 21, 1986, a limnic eruption silently unleashed 100,000 tons of carbon dioxide, rolling a lethal cloud through surrounding valleys that suffocated 1,746 people and 3,500 livestock in their sleep.',
      'ปรากฏการณ์ ''ลิมนิกเอรัปชัน'' (Limnic eruption) เป็นปรากฏการณ์ทางธรณีวิทยาที่หาได้ยากยิ่ง ปัจจุบันนักวิทยาศาสตร์ได้ติดตั้งท่อระบายก๊าซคาร์บอนไดออกไซด์เพื่อป้องกันไม่ให้โศกนาฏกรรมเกิดขึ้นซ้ำรอย',
      'The disaster prompted international geological intervention, leading to degassing pipe installations. Yet tribal elders still remember the catastrophe as the ultimate awakening of the lake''s angry wrath.',
      'ห้ามส่งเสียงอึกทึกหรือสร้างมลพิษในทะเลสาบปากปล่องภูเขาไฟ',
      'Never defile or camp on the shores of Lake Nyos without official authorization.',
      'https://i.ytimg.com/vi/-jZYG0pFLDg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/-jZYG0pFLDg/hqdefault.jpg","title":"ทะเลสาบแห่งมัจจุราชนิออส (โทสะแห่งวิญญาณน้ำคะเมรูน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=-jZYG0pFLDg","title":"The Lake Nyos Disaster: The Silent Death That Killed Hundreds","thumbnail":"https://i.ytimg.com/vi/-jZYG0pFLDg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-curse-prince-of-orange-diamond',
      'คำสาปเพชรแห่งเจ้าชายออเรนจ์ (เพชรบลูฮาร์ปสเตเดนบวร์ก)',
      'The Curse of the Blue Diamond of Brunswick',
      'curse',
      'โลเวอร์แซกโซนี',
      'Lower Saxony',
      'เบราน์ชไวก์',
      'Brunswick',
      52.2689,
      10.5268,
      'whisper',
      'เพชรสีน้ำเงินเข้มล้ำค่าที่สืบทอดในราชสำนักยุโรป มีตำนานเล่าว่าดยุคแห่งบรันสวิก ผู้ครอบครองเพชรเม็ดนี้ ตกอยู่ในความหวาดระแวงอย่างรุนแรงจนต้องนอนในห้องนิรภัยที่เต็มไปด้วยกับดักปืนกลและกระดิ่งเตือนภัย ดยุคถูกขับไล่ออกจากดินแดนของตนเองในการปฏิวัติและเสียชีวิตอย่างโดดเดี่ยวในต่างแดน ผู้ใดก็ตามที่พยายามซื้อขายหรือสวมใส่เพชรสีน้ำเงินเม็ดนี้มักต้องเผชิญกับคดีฉ้อโกง ความพินาศทางการเงิน และโรคร้ายที่ไร้ทางรักษา',
      'The Duke of Brunswick, Charles II, possessed a fabled blue diamond alongside an obsessive fear of assassination. He lived barricaded inside a heavily fortified palace guarded by hidden spring-guns and alarm bells, convinced the diamond carried an ancient curse of betrayal. Driven into exile by his people during an uprising, his fortune crumbled, leaving behind a dark legacy of paranoia surrounding the gem.',
      'เรื่องราวของดยุกแห่งบรันสวิกเป็นหนึ่งในตัวอย่างคลาสสิกของความคลั่งไคล้อัญมณีในยุโรปศตวรรษที่ 19 ซึ่งมักเชื่อมโยงกับความตกต่ำของราชวงศ์และความล่มสลายทางการเงิน',
      'The historic Brunswick jewel collections were auctioned in Geneva in 1874. The blue diamond remains synonymous with aristocratic misfortune and supernatural dread.',
      'ห้ามกักตุนอัญมณีด้วยความโลภจนตัดขาดจากมนุษยธรรม',
      'Never succumb to obsessive greed when handling historic royal gems.',
      'https://i.ytimg.com/vi/XUo5oqK5z6A/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/XUo5oqK5z6A/hqdefault.jpg","title":"คำสาปเพชรแห่งเจ้าชายออเรนจ์ (เพชรบลูฮาร์ปสเตเดนบวร์ก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XUo5oqK5z6A","title":"The Cursed Jewel: Solving the 300-Year Mystery of Louis XIV’s Diamond | Full Documentary","thumbnail":"https://i.ytimg.com/vi/XUo5oqK5z6A/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-wat-samian-nari-sisters',
      'วิญญาณหญิงสาวชุดดำแห่งวัดเสมียนนารี (ทางรถไฟสายมรณะ)',
      'The Two Sisters in Black of Wat Samian Nari',
      'ghost',
      'กรุงเทพมหานคร',
      'Bangkok',
      'จตุจักร',
      'Chatuchak',
      13.8398,
      100.5542,
      'whisper',
      'เรื่องเล่าขานสะเทือนขวัญของคนขับแท็กซี่กะดึกในกรุงเทพฯ ยามค่ำคืนมักจะมีหญิงสาวสองคนสวมชุดสีดำล้วน ท่าทางเศร้าสร้อย เรียกให้ไปส่งที่วัดเสมียนนารี เมื่อรถแล่นมาถึงทางข้ามทางรถไฟหน้าวัด หญิงสาวทั้งสองจะขอลงกลางทาง ทว่าเมื่อคนขับมองกระจกหลังหรือหันไปดู จะพบว่าร่างของพวกเธอถูกรถไฟทับขาดสองท่อน และกำลังคลานด้วยมือสองข้างข้ามรางรถไฟ เลือดไหลนองตามพื้นเพื่อมุ่งหน้าเข้าสู่วัดอย่างน่าสยดสยอง',
      'A spine-chilling urban ghost story of Bangkok''s late-night cab drivers: two solemn young women dressed head-to-toe in black hail a taxi, requesting to be dropped off at Wat Samian Nari. As the cab nears the railway crossing in front of the temple, the sisters vanish from the backseat. Shocked drivers look out onto the train tracks to see two severed torso figures clawing their way across the steel rails in the moonlight.',
      'เรื่องราวนี้อิงจากอุบัติเหตุรถไฟชนคนเสียชีวิตจริงในอดีตบริเวณทางข้ามวัดเสมียนนารี กลายเป็นตำนานผีไทยร่วมสมัยที่ได้รับการเล่าขานในรายการเดอะช็อค (The Shock) และสร้างเป็นภาพยนตร์หลายเรื่อง',
      'Rooted in tragic real-life train accidents along the Northern Railway line at Wat Samian Nari crossing, this urban legend remains one of Thailand''s most famous ghost encounters.',
      'อย่าจ้องมองผู้โดยสารชุดดำผ่านกระจกมองหลังขณะขับผ่านทางรถไฟหน้าวัด',
      'Never stare into the rearview mirror if carrying silent passengers near the railway crossing.',
      'https://i.ytimg.com/vi/pg_LedC3MGI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/pg_LedC3MGI/hqdefault.jpg","title":"วิญญาณหญิงสาวชุดดำแห่งวัดเสมียนนารี (ทางรถไฟสายมรณะ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=pg_LedC3MGI","title":"The Shock ย้อนยุค  เรื่อง สาวชุดดำ | The Shock","thumbnail":"https://i.ytimg.com/vi/pg_LedC3MGI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-krasue-ban-nong-bua',
      'กระสือบ้านหนองบัว (ดวงไฟประหลาดเหนือยอดกล้วย)',
      'The Spectral Krasue Glow of Ban Nong Bua',
      'ghost',
      'สระบุรี',
      'Saraburi',
      'หนองแค',
      'Nong Khae',
      14.3412,
      100.8653,
      'whisper',
      'ในเขตชนบทหนองบัว ชาวบ้านต่างหวาดกลัวดวงไฟสีเขียวอมแดงลอยขึ้นลงเหนือยอดไม้ในยามดึกสงัด พร้อมเสียงลมพัดกระโชกและกลิ่นคาวเลือดคละคลุ้ง เชื่อกันว่าเป็น ''ผีกระสือ'' หรือวิญญาณหญิงแก่ที่ถอดหัวพร้อมไส้เรืองแสงออกหากินของคาวตามเล้าเป็ดไก่และบ้านที่มีหญิงเพิ่งคลอดลูก ในตอนเช้ามักพบเศษมูลสัตว์และคราบเลือดเปรอะเปื้อนอยู่บนผ้าถุงที่ตากทิ้งไว้นอกชานบ้าน',
      'In the rural village of Ban Nong Bua, villagers have long reported an eerie, pulsing green-red light hovering silently above the banana groves. In Siamese folklore, the Krasue is a cursed female spirit whose head detaches from her body at night, dragging glowing intestines through the dark in search of raw meat, blood, and placenta. Villagers hung thorny brambles around their porches to snare her entrails.',
      'ความเชื่อเรื่องผีกระสือเป็นคติชนวิทยาที่แพร่หลายในภูมิภาคเอเชียตะวันออกเฉียงใต้ สะท้อนถึงภูมิปัญญาชาวบ้านในการรักษาความสะอาดและการป้องกันสุขอนามัยของหญิงคลอดบุตรในสมัยโบราณ',
      'The Krasue is one of Southeast Asia''s quintessential spectral entities, sharing roots with the Penanggalan in Malaysia and Leyak in Bali.',
      'ห้ามตากผ้าถุงหรือเสื้อผ้านอกบ้านข้ามคืน เพราะกระสือจะนำไปเช็ดปากเปื้อนเลือด',
      'Never leave clothing hanging on clotheslines overnight, lest the spirit wipe her bloody mouth upon it.',
      'https://i.ytimg.com/vi/pDIYrsjPxKg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/pDIYrsjPxKg/hqdefault.jpg","title":"กระสือบ้านหนองบัว (ดวงไฟประหลาดเหนือยอดกล้วย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=pDIYrsjPxKg","title":"ตำนานกระสือ อมนุษย์ที่มีหัวใจ | หลอนดูดิ EP.38","thumbnail":"https://i.ytimg.com/vi/pDIYrsjPxKg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-mae-ya-som-kui-buri',
      'ศาลแม่ย่าซ่อม กุยบุรี (วิญญาณคุ้มภัยแห่งโค้งอันตราย)',
      'The Legend and Spirit of Mae Ya Som Shrine (Kui Buri)',
      'ghost',
      'ประจวบคีรีขันธ์',
      'Prachuap Khiri Khan',
      'กุยบุรี',
      'Kui Buri',
      12.0831,
      99.9024,
      'whisper',
      'ศาลไม้โบราณริมถนนเพชรเกษมช่วงกุยบุรี ซึ่งในอดีตเป็นทางโค้งอันตรายที่มีอุบัติเหตุรถคว่ำเสียชีวิตบ่อยครั้ง ''แม่ย่าซ่อม'' เป็นวิญญาณหญิงชราผู้เปี่ยมเมตตาที่คอยปรากฏร่างเตือนสติผู้ขับขี่ที่กำลังหลับใน คนขับรถบรรทุกเล่าว่าเมื่อใกล้ถึงโค้งมักเห็นหญิงแก่ยืนโบกมืออยู่ริมทาง หรือสะดุ้งตื่นเพราะมีเสียงกระซิบข้างหู ทำให้รอดพ้นจากอุบัติเหตุได้อย่างปาฏิหาริย์ จนผู้สัญจรต้องบีบแตรแสดงความเคารพทุกครั้งที่ผ่าน',
      'Nestled along Highway 4 in Kui Buri stands the Mae Ya Som shrine, situated on a historically deadly mountain curve. Legend tells of a benevolent spectral grandmother who watches over travelers. Truckers report dozing off only to be awakened by a sharp whisper or the vision of an elderly woman waving from the shoulder of the road, miraculously saving them from plunging into ravines.',
      'การบีบแตรสามครั้งเพื่อคารวะศาลริมทางเป็นธรรมเนียมปฏิบัติของคนขับรถในประเทศไทย ซึ่งผสมผสานระหว่างความเชื่อเรื่องผีคุ้มภัยกับมารยาทการเตือนเพื่อนร่วมทางในทางโค้งอันตราย',
      'A famous roadside ghost veneration tradition in southern Thailand, motorists honk three times when passing to ask for safe travels across the treacherous coastal highway.',
      'ห้ามลบหลู่ศาล หรือขับรถผ่านทางโค้งด้วยความคึกคะนองโดยไม่ระมัดระวัง',
      'Never mock roadside shrines or speed recklessly through sacred mountain curves.',
      'https://i.ytimg.com/vi/oMvGCB8L9ls/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/oMvGCB8L9ls/hqdefault.jpg","title":"ศาลแม่ย่าซ่อม กุยบุรี (วิญญาณคุ้มภัยแห่งโค้งอันตราย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=oMvGCB8L9ls","title":"ปาฏิหาริย์ \"เสด็จแม่ย่าซอม\" นิรมิต แห่งวัดแม่ย่าซอม จ.สระแก้ว : ตามรอยนาคราช Ep.37(ນາກ,နဂါး,龙王)","thumbnail":"https://i.ytimg.com/vi/oMvGCB8L9ls/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-crathes-castle-green-lady',
      'สตรีชุดเขียวแห่งปราสาทคราเธอส (วิญญาณอุ้มทารกแห่งสก็อตแลนด์)',
      'The Green Lady of Crathes Castle',
      'ghost',
      'แอเบอร์ดีนเชียร์',
      'Aberdeenshire',
      'แบนชอรี',
      'Banchory',
      57.0617,
      -2.4402,
      'whisper',
      'ปราสาทสไตล์สก็อตบารอนเนียลในศตวรรษที่ 16 มีตำนานวิญญาณของ ''สตรีชุดเขียว'' ที่เดินเหยียบย่างไปตามห้องนอนและบันไดวนในยามค่ำคืน ร่างของเธอสวมชุดราตรีสีเขียวยาว อุ้มทารกไว้ในอ้อมอก และมักเดินไปหยุดยืนจ้องมองเตาผิงด้วยความโศกเศร้า ในช่วงศตวรรษที่ 19 ระหว่างการบูรณะปราสาท คนงานได้ขุดพบโครงกระดูกของเด็กทารกและหญิงสาวซ่อนอยู่ใต้เตาผิงหิน ยืนยันเรื่องราวโศกนาฏกรรมการฆาตกรรมแม่ลูกในอดีต',
      'Crathes Castle in Aberdeenshire is haunted by the Green Lady, believed to be Bertha, a serving maiden murdered by an aristocratic family. Witnesses describe a silent figure gliding past the bed chambers clad in a flowing green robe, cradling a baby against her chest before fading into the fireplace. In the 1800s, renovation workers unearthed the skeletal remains of an infant buried beneath the stone hearth stones.',
      'สมเด็จพระราชินีนาถวิกตอเรียแห่งสหราชอาณาจักรเคยเสด็จเยือนปราสาทคราเธอส และทรงบันทึกถึงความประทับใจในสถาปัตยกรรมและตำนานความลี้ลับของสตรีชุดเขียวไว้ในบันทึกส่วนพระองค์',
      'Queen Victoria herself recorded an interest in the Crathes specter. The property is managed by the National Trust for Scotland, preserving the fireplace where the tragic remains were found.',
      'ห้ามรบกวนเตาผิงโบราณในห้องนอนสีเขียวของปราสาท',
      'Never disturb the hearthstones of the Green Lady''s chamber.',
      'https://i.ytimg.com/vi/zn_PIM9DiwU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/zn_PIM9DiwU/hqdefault.jpg","title":"สตรีชุดเขียวแห่งปราสาทคราเธอส (วิญญาณอุ้มทารกแห่งสก็อตแลนด์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=zn_PIM9DiwU","title":"The Phantom Mother of Crathes Castle - The Green Lady","thumbnail":"https://i.ytimg.com/vi/zn_PIM9DiwU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-huntingdon-college-red-lady',
      'สตรีชุดแดงแห่งวิทยาลัยฮันติงดัน (วิญญาณแสงสีแดงแห่งหอพัก)',
      'The Red Lady of Huntingdon College',
      'ghost',
      'แอละแบมา',
      'Alabama',
      'มอนต์กอเมอรี',
      'Montgomery',
      32.3512,
      -86.2842,
      'creepy_wind',
      'มาร์ธา นักศึกษาหญิงหน้าใหม่ผู้เงียบขรึมและชื่นชอบสีแดง เธอตัดเย็บผ้าม่านและตกแต่งห้องนอนในหอพักแพรตต์ด้วยผ้าสีแดงทั้งหมด ทว่าความโดดเดี่ยวและการถูกเพื่อนร่วมชั้นกลั่นแกล้งทำให้เธอตรอมใจและกรีดข้อมือเสียชีวิตในห้องพัก นับแต่นั้นในคืนที่อากาศหนาวเย็น นักศึกษาในหอพักมักจะเห็นแสงสีแดงเรืองรองส่องลอดออกมาจากใต้ประตูห้อง หรือเห็นเงาหญิงสาวในชุดเดรสสีแดงลอยผ่านโถงทางเดินอย่างเงียบงัน',
      'Martha, an introverted freshman at Huntingdon College in the early 20th century, draped her entire dormitory room in crimson fabric. Ostracized by fellow students, she succumbed to deep depression and slashed her wrists. Ever since, students in Pratt Hall report seeing an unnatural scarlet glow emanating from empty rooms and encountering a pale maiden in a flowing red gown wandering the corridors.',
      'เรื่องราวของสตรีชุดแดงได้รับการบันทึกเป็นลายลักษณ์อักษรโดย แคธรีน ทักเกอร์ วินด์แฮม นักเขียนนิทานพื้นบ้านชาวแอละแบมา ในหนังสือ ''13 Alabama Ghosts and Jeffrey'' และกลายเป็นตำนานประจำสถาบัน',
      'Immortalized in Kathryn Tucker Windham''s classic Southern folklore collection, the Red Lady remains one of the most famous collegiate ghosts in the United States.',
      'ห้ามท้าทายหรือสวมชุดสีแดงล้วนเข้าไปเคาะประตูห้องพักในตำนาน',
      'Never mock Martha''s solitude or wear solid crimson to summon her spirit.',
      'https://i.ytimg.com/vi/N7ueZJu-olY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/N7ueZJu-olY/hqdefault.jpg","title":"สตรีชุดแดงแห่งวิทยาลัยฮันติงดัน (วิญญาณแสงสีแดงแห่งหอพัก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=N7ueZJu-olY","title":"Haunted Location: The Red Lady of Huntingdon College - Montgomery, Alabama","thumbnail":"https://i.ytimg.com/vi/N7ueZJu-olY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-charles-fort-white-lady',
      'สตรีชุดขาวแห่งป้อมชาร์ลส์ (เจ้าสาวผู้กระโดดหน้าผาคินเซล)',
      'The White Lady of Kinsale at Charles Fort',
      'ghost',
      'คอร์ก',
      'County Cork',
      'คินเซล',
      'Kinsale',
      51.6967,
      -8.4984,
      'creepy_wind',
      'ป้อมปราการรูปดาวริมหน้าผาชายฝั่งไอร์แลนด์ ตำนานเล่าว่า วิลมา บุตรสาวของผู้บัญชาการป้อม ได้แต่งงานกับนายทหารหนุ่ม ทว่าในคืนวันแต่งงาน เจ้าบ่าวต้องไปเข้าเวรเฝ้ายามและเผลอหลับไป บิดาของเธอซึ่งตรวจเวรเห็นทหารหลับจึงยิงเสียชีวิตทันทีโดยไม่รู้ว่าเป็นลูกเขย เมื่อวิลมารู้ความจริง เธอเสียใจจนขาดสติและกระโดดจากเชิงเทินป้อมลงสู่โขดหินเบื้องล่าง วิญญาณของเธอในชุดเจ้าสาวสีขาวเปียกปอนยังคงเดินวนเวียนตามกำแพงป้อมและยิ้มให้ทหารยาม',
      'Charles Fort, an imposing 17th-century star fortress overlooking Kinsale Harbor, is haunted by the ''White Lady''. Daughter of the fort''s commander, she married a young officer. On their wedding night, her husband fell asleep on sentry duty and was shot dead by her own father, who did not recognize him in the dark. In agonizing grief, the bride threw herself off the fortress ramparts onto the rocks below.',
      'ป้อมชาร์ลส์สร้างขึ้นในปี 1677 และถูกใช้งานในสงครามหลายศตวรรษ ปัจจุบันเป็นโบราณสถานแห่งชาติของไอร์แลนด์ ทหารอังกฤษในอดีตได้บันทึกรายงานการพบเห็นวิญญาณหญิงสาวชุดขาวไว้อย่างเป็นทางการ',
      'British garrison records repeatedly cited sentries being confronted by a weeping bride in white along the battlements, making Charles Fort an iconic Irish haunting site.',
      'ห้ามยืนชะโงกหน้าผาริมเชิงเทินของป้อมชาร์ลส์ในเวลาพลบค่ำ',
      'Never lean over the coastal ramparts alone during twilight.',
      'https://i.ytimg.com/vi/OTb_CEMtp8E/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/OTb_CEMtp8E/hqdefault.jpg","title":"สตรีชุดขาวแห่งป้อมชาร์ลส์ (เจ้าสาวผู้กระโดดหน้าผาคินเซล)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=OTb_CEMtp8E","title":"The White Lady of Kinsale","thumbnail":"https://i.ytimg.com/vi/OTb_CEMtp8E/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-drury-lane-man-in-grey',
      'บุรุษชุดเทาแห่งโรงละครดรูรีเลน (วิญญาณนำโชคแห่งลอนดอน)',
      'The Theatre Royal Drury Lane Man in Grey',
      'ghost',
      'ลอนดอน',
      'London',
      'เวสต์มินสเตอร์',
      'Westminster',
      51.513,
      -0.1205,
      'whisper',
      'โรงละครที่เก่าแก่ที่สุดแห่งหนึ่งในลอนดอน มีวิญญาณประจำที่รู้จักกันในนาม ''บุรุษชุดเทา'' เขาจะปรากฏกายในชุดขุนนางศตวรรษที่ 18 สวมหมวกปีกกว้าง เสื้อคลุมสีเทายาว และเหน็บดาบไว้ข้างเอว โดยมักจะเดินข้ามระเบียงที่นั่งชั้นบนแล้วหายตัวเข้าไปในผนังทึบ สิ่งที่น่าแปลกคือ หากนักแสดงคนใดเห็นบุรุษชุดเทาก่อนการแสดง ละครเรื่องนั้นจะประสบความสำเร็จอย่างถล่มทลาย ในปี 1848 มีการทุบผนังและพบโครงกระดูกของชายคนหนึ่งถูกแทงด้วยมีดกริชฝังอยู่ด้านใน',
      'The Theatre Royal Drury Lane, London''s oldest operating theater, is home to the benevolent ''Man in Grey''. Dressed in an 18th-century frock coat, tricorn hat, riding boots, and sword, he materializes in the upper circle and walks silently into the wall. Unlike frightening specters, his appearance is heralded by actors as a sure sign of commercial triumph. In 1848, renovations revealed a skeletal body with a dagger in its ribcage sealed inside that very wall.',
      'วิญญาณบุรุษชุดเทาได้รับการยืนยันโดยนักแสดงชื่อดังมากมายตลอดสองร้อยปี รวมถึงทีมนักแสดงของละครเพลง South Pacific ที่เห็นเขาปรากฏตัวพร้อมกันในระหว่างการซ้อม',
      'Witnessed by entire casts during matinées, the Man in Grey is perhaps the theatrical world''s most famous and cherished benevolent omen.',
      'ห้ามส่งเสียงโห่ร้องรบกวนหากเห็นร่างในชุดเทาเดินผ่านชั้นระเบียง',
      'Never hiss or shout at the Man in Grey during a performance run.',
      'https://i.ytimg.com/vi/8PU9U2tGYac/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/8PU9U2tGYac/hqdefault.jpg","title":"บุรุษชุดเทาแห่งโรงละครดรูรีเลน (วิญญาณนำโชคแห่งลอนดอน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8PU9U2tGYac","title":"Most Haunted - S01E04 ''''Theatre Royal, Drury Lane''''","thumbnail":"https://i.ytimg.com/vi/8PU9U2tGYac/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-octagon-house-dollay',
      'บ้านแปดเหลี่ยมแห่งวอชิงตัน ดี.ซี. (วิญญาณลูกสาวตระกูลเทย์โล)',
      'The Hauntings of the Octagon House',
      'ghost',
      'วอชิงตัน ดี.ซี.',
      'District of Columbia',
      'วอชิงตัน',
      'Washington',
      38.8964,
      -77.0425,
      'creepy_wind',
      'คฤหาสน์แปดเหลี่ยมอันเก่าแก่ที่เคยใช้เป็นทำเนียบขาวชั่วคราวหลังสงครามปี 1812 สร้างขึ้นโดยพันเอก จอห์น เทย์โล ตามประวัติเล่าว่า บุตรสาวสองคนของเขาต่างเสียชีวิตด้วยการพลัดตกจากบันไดวนกลางบ้านลงมาคอหักตาย หลังจากมีปากเสียงกับบิดาเรื่องคนรัก ผู้มาเยือนมักได้ยินเสียงกรีดร้องและเสียงร่างตกลงมากระแทกพื้นอย่างรุนแรง พรมตรงบันไดมักจะขดตัวขึ้นเอง และมีรอยมือปริศนาปรากฏบนราวจับบันได',
      'Built in 1799, the Octagon House served as the temporary White House for President James Madison after the British burned Washington. Tragedy struck the owner, Colonel John Tayloe, when two of his daughters died decades apart by falling down the dramatic circular spiral staircase during arguments about forbidden romances. Echoing thuds, screams, phantom ringing bells, and the smell of lilac perfume plague the stairwell to this day.',
      'บ้านแปดเหลี่ยมปัจจุบันเป็นพิพิธภัณฑ์ของสถาบันสถาปนิกอเมริกัน (AIA) และได้รับการยอมรับว่าเป็นหนึ่งในบ้านที่มีเรื่องเล่าทางประวัติศาสตร์และอาถรรพ์ที่เก่าแก่ที่สุดในเมืองหลวงของสหรัฐฯ',
      'Maintained as a museum by the American Institute of Architects, the building''s architectural acoustics and ghostly lore continue to intrigue historians and paranormal investigators.',
      'ห้ามยืนทะเลาะหรือส่งเสียงเอะอะบริเวณเชิงบันไดวน',
      'Never argue or engage in shouting matches on the central spiral staircase.',
      'https://i.ytimg.com/vi/XYSUAtnpBI4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/XYSUAtnpBI4/hqdefault.jpg","title":"บ้านแปดเหลี่ยมแห่งวอชิงตัน ดี.ซี. (วิญญาณลูกสาวตระกูลเทย์โล)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XYSUAtnpBI4","title":"Octagon House: D.C.''s First & Most Haunted House | DomoNaut","thumbnail":"https://i.ytimg.com/vi/XYSUAtnpBI4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-blickling-hall-anne-boleyn',
      'วิญญาณไร้หัวของแอนน์ โบลีน แห่งบลิคลิงฮอลล์',
      'The Headless Phantom of Anne Boleyn at Blickling Hall',
      'ghost',
      'นอร์ฟอล์ก',
      'Norfolk',
      'อายล์แชม',
      'Aylsham',
      52.8122,
      1.2333,
      'creepy_wind',
      'บลิคลิงฮอลล์ คฤหาสน์เก่าแก่ที่เป็นสถานที่ประสูติของ พระราชินีแอนน์ โบลีน มเหสีองค์ที่สองของพระเจ้าเฮนรีที่ 8 ผู้ถูกสั่งประหารชีวิตด้วยการตัดคอในหอคอยลอนดอนเมื่อวันที่ 19 พฤษภาคม 1536 ทุกๆ คืนครบรอบวันประหาร รถม้าเทียมม้าไร้หัวสี่ตัวจะแล่นนำร่างของแอนน์ โบลีน มายังคฤหาสน์ เธอจะก้าวลงจากรถม้าในชุดสีขาวสง่างาม โดยอุ้มศีรษะของตนเองไว้บนตัก และเดินล่องลอยสำรวจทางเดินในบ้านจนถึงรุ่งสาง',
      'Blickling Hall is the historic birthplace of Queen Anne Boleyn, second wife of King Henry VIII, who was executed by French swordsman at the Tower of London on May 19, 1536. Every year on the anniversary of her death, a phantom coach driven by headless horses and a headless coachman arrives at Blickling. Anne steps out clad in white, carrying her severed crowned head upon her lap, and wanders the grand corridors until dawn.',
      'บลิคลิงฮอลล์ได้รับการโหวตโดยเนชันแนลทรัสต์ (National Trust) ให้เป็นสถานที่ที่มีผีดุที่สุดในอังกฤษเป็นเวลาหลายปีติดต่อกัน',
      'Consistently voted the most haunted property managed by the National Trust, Blickling Hall''s anniversary legend is celebrated as an enduring piece of British royal lore.',
      'ห้ามขวางทางเดินรถม้าโบราณที่แล่นเข้ามายังซุ้มประตูด้านหน้าในคืนวันที่ 19 พฤษภาคม',
      'Never stand in the driveway before Blickling Hall on the night of May 19th.',
      'https://i.ytimg.com/vi/KZBUsVhcX9g/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/KZBUsVhcX9g/hqdefault.jpg","title":"วิญญาณไร้หัวของแอนน์ โบลีน แห่งบลิคลิงฮอลล์"},{"type":"youtube","url":"https://www.youtube.com/watch?v=KZBUsVhcX9g","title":"The Ghost of Anne Boleyn (2024) | Full Documentary","thumbnail":"https://i.ytimg.com/vi/KZBUsVhcX9g/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-rochester-white-lady',
      'สตรีชุดขาวแห่งดูแรนด์ อีสต์แมน พาร์ก (วิญญาณแม่ตามหาลูก)',
      'The White Lady of Durand Eastman Park (Rochester)',
      'ghost',
      'นิวยอร์ก',
      'New York',
      'รอเชสเตอร์',
      'Rochester',
      43.2381,
      -77.5647,
      'water_spirit',
      'ริมชายฝั่งทะเลสาบออนแทรีโอ มีซากปรักหักพังของกำแพงหินโบราณที่เรียกกันว่า ''ปราสาทสตรีชุดขาว'' ตำนานในศตวรรษที่ 19 เล่าถึงหญิงม่ายผู้หวงลูกสาวคนสวยอย่างยิ่ง ทว่าในคืนหนึ่งลูกสาวของเธอหายตัวไปอย่างไร้ร่องรอย บ้างก็ว่าถูกคนรักลักพาตัว บ้างก็ว่าถูกฆาตกรรม ผู้เป็นแม่ตามหาลูกสาวท่ามกลางสายฝนจนหนาวตาย ริมทะเลสาบมักปรากฏร่างโปร่งแสงสีขาวเดินพร้อมสุนัขล่าเนื้อสองตัว คอยจ้องมองรถยนต์ที่เข้ามาจอดเพื่อตามหาลูกสาว',
      'On the shores of Lake Ontario within Durand Eastman Park stand the stone remnants of the ''White Lady''s Castle''. In the 1800s, a fiercely protective mother lost her teenage daughter to a suspected abduction and murder. Mad with grief, the mother searched through marsh and bluffs until she drowned or died of exposure. Her glowing white specter, flanked by two spectral hellhounds, is frequently spotted pacing the foggy lakeshore, searching for her missing child.',
      'ตำนานสตรีชุดขาวแห่งรอเชสเตอร์เป็นหนึ่งในเรื่องเล่าที่โด่งดังที่สุดในแถบเกรตเลกส์ มีการแต่งเพลง นวนิยาย และสารคดีท้องถิ่นมากมายเกี่ยวกับซากปราสาทหินแห่งนี้',
      'A staple of Western New York folklore, local teenagers and ghost hunters visit the stone retaining walls each Halloween to look for the heartbroken maternal spirit.',
      'ห้ามเปิดไฟหน้ารถกะพริบสามครั้งในที่จอดรถริมทะเลสาบเวลาดึกสงัด',
      'Never flash headlights three times at the castle ruins in Durand Eastman Park.',
      'https://i.ytimg.com/vi/BdOmFr_G2c0/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/BdOmFr_G2c0/hqdefault.jpg","title":"สตรีชุดขาวแห่งดูแรนด์ อีสต์แมน พาร์ก (วิญญาณแม่ตามหาลูก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=BdOmFr_G2c0","title":"The White Lady - Flower City Frights","thumbnail":"https://i.ytimg.com/vi/BdOmFr_G2c0/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-pawleys-island-gray-man',
      'ชายชุดเทาแห่งเกาะพอว์ลีย์ (วิญญาณเตือนภัยพายุเฮอริเคน)',
      'The Gray Man of Pawleys Island Hurricane Warning',
      'ghost',
      'เซาท์แคโรไลนา',
      'South Carolina',
      'จอร์จทาวน์',
      'Georgetown County',
      33.431,
      -79.1214,
      'water_spirit',
      'เรื่องเล่าขานของวิญญาณชายผู้มีเมตตาแห่งชายฝั่งเซาท์แคโรไลนา ในปี 1822 ชายหนุ่มกำลังขี่ม้าฝ่าพายุเพื่อไปขอแต่งงานกับคนรัก ทว่าม้าของเขาพลัดตกลงไปในทรายดูดทำให้เขาจมน้ำเสียชีวิต นับแต่นั้นก่อนที่พายุเฮอริเคนระดับรุนแรงจะพัดเข้าถล่มเกาะพอว์ลีย์ ร่างของชายในเสื้อคลุมสีเทาจะปรากฏตัวเดินเตือนภัยริมชายหาด บ้านหลังใดที่พบเห็นเขาและอพยพตามคำเตือน บ้านหลังนั้นจะรอดพ้นจากความเสียหายของพายุได้อย่างอัศจรรย์',
      'Since 1822, residents of Pawleys Island have been protected by the benevolent specter known as the Gray Man. Traveling to propose to his fiancée, a young man was swallowed by quicksand in the marshes during a coastal storm. Before every catastrophic hurricane—including Hazel in 1954 and Hugo in 1989—his gray-clad silhouette walks the dunes, warning islanders to evacuate. Homes whose residents heed his gesture historically survive the storms intact.',
      'การพบเห็นชายชุดเทาได้รับการรายงานอย่างกว้างขวางในสื่อมวลชนกระแสหลักก่อนเกิดพายุเฮอริเคนฮิวโก้ในปี 1989 และกลายเป็นสัญลักษณ์ความหวังและสิ่งศักดิ์สิทธิ์ประจำท้องถิ่น',
      'Unlike malevolent hauntings, the Gray Man is revered as an omen of survival. Coastal residents take his pre-storm sightings seriously as a sacred folklore weather indicator.',
      'หากพบชายชุดเทาโบกมือริมชายหาด ให้อพยพขึ้นที่สูงทันที ห้ามละเลยคำเตือน',
      'Never ignore the warning gesture of the Gray Man; heed his omen and evacuate.',
      'https://i.ytimg.com/vi/IyQ2KFobH7k/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/IyQ2KFobH7k/hqdefault.jpg","title":"ชายชุดเทาแห่งเกาะพอว์ลีย์ (วิญญาณเตือนภัยพายุเฮอริเคน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=IyQ2KFobH7k","title":"The Story of the Gray Man Ghost of Pawleys Island","thumbnail":"https://i.ytimg.com/vi/IyQ2KFobH7k/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-pluckley-haunted-village',
      'หมู่บ้านผีดุที่สุดในอังกฤษ (พลัคลีย์แห่งเคนท์)',
      'The Screaming Woods & Ghosts of Pluckley Village',
      'ghost',
      'เคนท์',
      'Kent',
      'พลัคลีย์',
      'Pluckley',
      51.1852,
      0.7554,
      'creepy_wind',
      'หมู่บ้านในชนบทอังกฤษที่ได้รับการบันทึกลงในกินเนสส์บุ๊กอย่างเป็นทางการว่าเป็น ''หมู่บ้านที่มีผีดุที่สุดในสหราชอาณาจักร'' โดยมีวิญญาณสิงสถิตอยู่ถึง 12-16 ตน เช่น ''หญิงชราขายผักน้ำ'' ที่เผาตัวเองตายด้วยกล้องยาสูบ ''โจรทางหลวง'' ที่ถูกแทงด้วยดาบตรึงติดกับต้นไม้ ''พระครูแขวนคอ'' และป่าเดอริงวูดส์ (Dering Woods) หรือที่รู้จักในชื่อ ''ป่ากรีดร้อง'' ซึ่งมักมีเสียงหวีดร้องโหยหวนของวิญญาณดังก้องออกมาตลอดคืน',
      'Holding the Guinness World Record for the most haunted village in Britain, Pluckley boasts at least 12 distinct ghosts. These include the Red Lady of St. Nicholas Church, the phantom Watercress Woman who accidentally set herself ablaze, a highwayman run through with a sword at Fright Corner, and the phantom schoolmaster found hanged. The nearby Dering Woods are dubbed the ''Screaming Woods'' due to terrifying nighttime shrieks echoing from the thicket.',
      'พลัคลีย์เป็นหมู่บ้านเก่าแก่ที่มีประวัติตั้งแต่สมัยดูมสเดย์บุ๊ก (Domesday Book) ปี 1086 ปัจจุบันดึงดูดนักท่องเที่ยวและทีมล่าผีจากทั่วโลก โดยเฉพาะในช่วงเทศกาลฮาโลวีน',
      'Guinness officially certified Pluckley in 1989. The village preserves centuries of English folklore, surrounded by atmospheric orchards and ancient medieval churches.',
      'ห้ามเดินเข้าไปในป่ากรีดร้อง (Dering Woods) หลังพระอาทิตย์ตกดินเพียงลำพัง',
      'Never enter the Screaming Woods alone after dark without a compass and light.',
      'https://i.ytimg.com/vi/d9S1OjX6F4A/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/d9S1OjX6F4A/hqdefault.jpg","title":"หมู่บ้านผีดุที่สุดในอังกฤษ (พลัคลีย์แห่งเคนท์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=d9S1OjX6F4A","title":"Haunted England | THE SCREAMING WOODS | Exploring Pluckley’s Most Haunted Forest","thumbnail":"https://i.ytimg.com/vi/d9S1OjX6F4A/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-catacombs-philibert-aspart',
      'วิญญาณฟิลิแบร์ อัสแปร์ ในสุสานใต้ดินปารีส (กาตากงบ์)',
      'The Phantom of Philibert Aspart in the Paris Catacombs',
      'ghost',
      'ปารีส',
      'Paris',
      'ปารีส',
      'Paris',
      48.8338,
      2.3324,
      'whisper',
      'สุสานใต้ดินปารีสที่เก็บรักษากระดูกมนุษย์กว่า 6 ล้านคน ในปี 1793 ช่วงปฏิวัติฝรั่งเศส ฟิลิแบร์ อัสแปร์ พนักงานเฝ้าประตูโรงพยาบาล ได้แอบมุดลงไปในเหมืองหินใต้ดินเพื่อขโมยเหล้าและหลงทางอยู่ในเขาวงกตมืดมิดจนเทียนดับ เขาเสียชีวิตอย่างโดดเดี่ยว และร่างของเขาถูกพบกลายเป็นโครงกระดูกหลังจากนั้น 11 ปี โดยจำได้จากกุญแจในกระเป๋า ปัจจุบันผู้ที่ลักลอบลงไปในกาตากงบ์มักพบวิญญาณของเขาถือเทียนไขเลือนรางและได้ยินเสียงกระซิบเตือนไม่ให้หลงทาง',
      'Beneath the City of Light lies a 200-mile maze holding the skeletal remains of six million Parisians. In 1793, hospital doorkeeper Philibert Aspart ventured down into the dark quarries to plunder an underground wine cellar and became hopelessly lost when his candle burned out. His skeleton was found 11 years later, identified by his hospital keys. Urban cataphiles regularly report phantom footsteps, flickering candlelight, and his mournful whisper leading lost souls away from dead ends.',
      'หลุมศพของฟิลิแบร์ อัสแปร์ ยังคงตั้งอยู่ในเครือข่ายใต้ดินลึกใต้ถนนรูดูแบลล์แบล (Rue Dareau) ถือเป็นจุดแสวงบุญและเคารพของกลุ่มนักสำรวจใต้ดินนอกกฎหมาย (Cataphiles)',
      'Philibert''s stone tombstone still stands in the forbidden sections of the catacombs. He remains the unofficial patron ghost and cautionary tale for Parisian urban explorers.',
      'ห้ามลักลอบลงไปในเขตกักกันใต้ดินโดยไม่มีอุปกรณ์นำทางและแสงสว่างเพียงพอ',
      'Never explore uncharted tunnels of the Paris Catacombs without backup torches.',
      'https://i.ytimg.com/vi/rUPhPAv7sqI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/rUPhPAv7sqI/hqdefault.jpg","title":"วิญญาณฟิลิแบร์ อัสแปร์ ในสุสานใต้ดินปารีส (กาตากงบ์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=rUPhPAv7sqI","title":"S236 Philibert Aspairt ghost","thumbnail":"https://i.ytimg.com/vi/rUPhPAv7sqI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-moosham-castle-witches',
      'ปราสาทมูชัม (ปราสาทแม่มดและมนุษย์หมาป่าแห่งออสเตรีย)',
      'Moosham Castle Witch Trials & Werewolf Hauntings',
      'ghost',
      'ซาลซ์บูร์ก',
      'Salzburg',
      'อุนเทิร์นแบร์ก',
      'Unternberg',
      47.1022,
      13.7061,
      'creepy_wind',
      'ปราสาทหินโบราณบนเทือกเขาแอลป์ที่เคยเป็นสถานที่ไต่สวนและประหารชีวิตหญิงสาวข้อหาเป็นแม่มดกว่าหลายร้อยคนในช่วงศตวรรษที่ 17 พวกเธอถูกทรมานในห้องใต้ดินอันมืดมิดและตัดมือเท้าก่อนเผาทั้งเป็น ต่อมาในศตวรรษที่ 18 มีเหตุการณ์ปศุสัตว์ถูกฉีกร่างกัดกินทั่วหุบเขา จนเกิดการล่า ''มนุษย์หมาป่า'' และนำตัวมาขังคุกที่นี่ ปัจจุบันปราสาทเต็มไปด้วยเสียงกรีดร้องสะท้อนจากคุกใต้ดิน รอยข่วนบนผนังหิน และกลิ่นควันไฟที่ลอยมาโดยไร้ที่มา',
      'Perched above the Lungau Valley, Moosham Castle was the epicenter of the gruesome Zaubererjackl witch trials between 1675 and 1690. Hundreds of accused sorcerers, beggars, and children were tortured and decapitated within its walls. In the 18th century, a wave of slaughtered cattle sparked a hysteria of werewolf trials, with suspects imprisoned in the dungeons. Visitors report agonizing screams, phantom fires, and disembodied beast-like growls.',
      'การไต่สวนแม่มดที่มูชัมเป็นหนึ่งในคดีล่าแม่มดที่โหดเหี้ยมที่สุดในยุโรป ปัจจุบันปราสาทเปิดให้นักท่องเที่ยวเข้าชมห้องทรมานและเครื่องมือลงทัณฑ์โบราณที่ยังคงเก็บรักษาไว้ครบถ้วน',
      'Moosham Castle''s dark judicial history has made it a focal point for international paranormal investigators, including TV''s Ghost Hunters International.',
      'ห้ามก้าวเข้าไปในห้องขังทรมานชั้นล่างสุดเพียงลำพังหลังเวลาปิดทำการ',
      'Never linger alone inside the execution torture chamber after closing hours.',
      'https://i.ytimg.com/vi/ixKrerfXt-c/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/ixKrerfXt-c/hqdefault.jpg","title":"ปราสาทมูชัม (ปราสาทแม่มดและมนุษย์หมาป่าแห่งออสเตรีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=ixKrerfXt-c","title":"The Dark History of Austria’s Witch Castle","thumbnail":"https://i.ytimg.com/vi/ixKrerfXt-c/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-banff-springs-bride',
      'เจ้าสาวผีแห่งโรงแรมแบนฟ์สปริงส์ (วิญญาณชุดแต่งงานเพลิงไหม้)',
      'The Ghost Bride of Fairmont Banff Springs Hotel',
      'ghost',
      'แอลเบอร์ตา',
      'Alberta',
      'แบนฟ์',
      'Banff',
      51.1645,
      -115.5622,
      'whisper',
      'โรงแรมสไตล์ปราสาทสกอตติชอันยิ่งใหญ่กลางเทือกเขาร็อกกี ในยุค 1930 หญิงสาวในชุดแต่งงานลูกไม้งดงามกำลังก้าวลงบันไดหินอ่อนเพื่อเข้าสู่ห้องจัดเลี้ยง ทว่าชายกระโปรงของเธอพลาดไปเกี่ยวเข้ากับเชิงเทียนที่จุดไว้ เปลวไฟลุกไหม้ชุดอย่างรวดเร็ว ด้วยความตกใจเธอสะดุดล้มกลิ้งลงมาจากบันไดคอหักเสียชีวิตอย่างอนาถ พนักงานและแขกของโรงแรมมักเห็นร่างของเจ้าสาวเต้นรำโดดเดี่ยวอยู่ในห้องบอลรูม และลอยขึ้นลงตามบันไดหินอ่อนในชุดที่ติดไฟสีฟ้า',
      'The historic Fairmont Banff Springs Hotel in the Canadian Rockies is haunted by the tragic Ghost Bride. On her wedding day in the 1930s, her lace dress caught fire from staircase candle braziers as she descended the grand marble stairs. Panicked, she tripped and broke her neck. Guests frequently witness her veiled figure gliding sadly across the Cascade Ballroom or standing alone on the staircase with ghostly blue flames flickering along the hem of her gown.',
      'เรื่องราวของเจ้าสาวแบนฟ์สปริงส์ได้รับการยกย่องจนโรงกษาปณ์แคนาดา (Royal Canadian Mint) ได้จัดทำเหรียญกษาปณ์และแสตมป์ที่ระลึกเกี่ยวกับตำนานผีตนนี้โดยเฉพาะ',
      'The Royal Canadian Mint commemorated the Ghost Bride on a special collector coin and stamp in 2014, honoring Banff''s most beloved and photographed supernatural legend.',
      'ห้ามนำเทียนไขจริงไปจุดวางบนบันไดหินอ่อนของโรงแรม',
      'Never light live open flame candles on the historic marble grand staircase.',
      'https://i.ytimg.com/vi/D_ZjCZ4X7Jo/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/D_ZjCZ4X7Jo/hqdefault.jpg","title":"เจ้าสาวผีแห่งโรงแรมแบนฟ์สปริงส์ (วิญญาณชุดแต่งงานเพลิงไหม้)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D_ZjCZ4X7Jo","title":"The Hauntings of Banff Springs Hotel - The Bride","thumbnail":"https://i.ytimg.com/vi/D_ZjCZ4X7Jo/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-empress-hotel-architect',
      'สถาปนิกผู้ถูกสังหารแห่งโรงแรมดิเอ็มเพรส (ฟรานซิส รัตเทนบิวรี)',
      'The Ghost of Francis Rattenbury at the Empress Hotel',
      'ghost',
      'บริติชโคลัมเบีย',
      'British Columbia',
      'วิกตอเรีย',
      'Victoria',
      48.4216,
      -123.3676,
      'whisper',
      'โรงแรมหรูระดับตำนานริมอ่าววิกตอเรีย ออกแบบโดย ฟรานซิส รัตเทนบิวรี สถาปนิกชื่อดังชาวอังกฤษ ต่อมาเขาต้องเผชิญกับข่าวฉาวและย้ายกลับอังกฤษ ก่อนจะถูกคนขับรถที่เป็นชู้รักของภรรยาใช้ค้อนทุบศีรษะสังหารอย่างทารุณ วิญญาณของเขายังคงผูกพันกับผลงานชิ้นเอกชิ้นนี้ ผู้คนมักเห็นชายสูงอายุสวมสูทโบราณถือไม้เท้าเดินตรวจตราล็อบบี้และโถงทางเดินชั้นบน บางครั้งก็ปรากฏตัวทักทายแขกที่มาจิบน้ำชายามบ่าย',
      'The Fairmont Empress Hotel overlooking Victoria''s harbor was designed by celebrated architect Francis Rattenbury. In 1935, back in England, Rattenbury was bludgeoned to death with a carpenter''s mallet by his young wife''s teenage chauffeur and lover. Longing for his greatest triumph, Rattenbury''s dapper ghost strolls the halls with a walking cane, inspecting the woodwork and politely tipping his hat to patrons having high tea.',
      'คดีฆาตกรรมรัตเทนบิวรีเป็นหนึ่งในคดีอาชญากรรมที่โด่งดังที่สุดในประวัติศาสตร์อังกฤษยุค 1930 ปัจจุบันโรงแรมเอ็มเพรสยังคงเก็บรักษาภาพถ่ายและมรดกทางสถาปัตยกรรมของเขาไว้',
      'The Rattenbury murder trial captivated the 1930s British press. His restless presence at the Empress remains a hallmark of Victoria''s vibrant ghost tour heritage.',
      'ห้ามเคาะหรือทำลายงานไม้แกะสลักโบราณในห้องชิมชา',
      'Never deface or scratch the original oak millwork in the tea rooms.',
      'https://i.ytimg.com/vi/1cePsb5x1Tc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/1cePsb5x1Tc/hqdefault.jpg","title":"สถาปนิกผู้ถูกสังหารแห่งโรงแรมดิเอ็มเพรส (ฟรานซิส รัตเทนบิวรี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=1cePsb5x1Tc","title":"Francis Mawson Rattenbury","thumbnail":"https://i.ytimg.com/vi/1cePsb5x1Tc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-fountains-abbey-monk',
      'วิญญาณพระสวดมนต์แห่งวิหารฟาวน์เทนส์ (เสียงสวดภาวนาไร้ร่าง)',
      'The Chanting Ghost Monks of Fountains Abbey',
      'ghost',
      'นอร์ท ยอร์กเชียร์',
      'North Yorkshire',
      'ริปอน',
      'Ripon',
      54.1095,
      -1.5815,
      'temple_bell',
      'ซากอารามนักบวชคณะซิสเตอร์เชียนที่ใหญ่ที่สุดและสมบูรณ์ที่สุดแห่งหนึ่งในอังกฤษ ก่อตั้งในปี 1132 ก่อนจะถูกทำลายและสั่งยุบโดยพระเจ้าเฮนรีที่ 8 นักบวชหลายรูปถูกขับไล่และสังหาร ท่ามกลางซากปรักหักพังของเสาหินและเพดานโค้ง ผู้มาเยือนในยามพลบค่ำมักได้ยินเสียงสวดมนต์บทเกรกอเรียน (Gregorian Chant) ก้องกังวานมาจากวิหารที่ไร้หลังคา และเห็นขบวนแถวของนักบวชในชุดคลุมสีดำเดินทะลุผ่านกำแพงหิน',
      'Founded in 1132, Fountains Abbey was one of the wealthiest Cistercian monasteries in Britain until King Henry VIII ordered its brutal dissolution in 1539. Amid the colossal roofless Gothic arches and cloisters, visitors regularly hear disembodied Latin Gregorian chants echoing across the lawns. Spectral monks in hooded robes have been observed processing through the cellarium and fading into the medieval masonry.',
      'วิหารฟาวน์เทนส์และอุทยานสตัดลีย์รอยัลได้รับการขึ้นทะเบียนเป็นมรดกโลกโดยยูเนสโก (UNESCO) เป็นหนึ่งในสถานที่ประวัติศาสตร์ที่งดงามและเปี่ยมมนต์ขลังที่สุดในสหราชอาณาจักร',
      'Now a UNESCO World Heritage Site managed by the National Trust, the abbey''s acoustic anomalies and phantom chants have been reported by centuries of visitors.',
      'ห้ามส่งเสียงตะโกนหรือล้อเลียนเสียงสวดมนต์โบราณในบริเวณแท่นบูชา',
      'Never mock Latin liturgical chants or desecrate the ruined high altar.',
      'https://i.ytimg.com/vi/CY4KBDPUwVA/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/CY4KBDPUwVA/hqdefault.jpg","title":"วิญญาณพระสวดมนต์แห่งวิหารฟาวน์เทนส์ (เสียงสวดภาวนาไร้ร่าง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=CY4KBDPUwVA","title":"The Fate of Fountains Abbey: From Majesty to Ruin","thumbnail":"https://i.ytimg.com/vi/CY4KBDPUwVA/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-corvin-castle-vlad',
      'ปราสาทคอร์วิน (คุกขังแดร็กคูลาและวิญญาณนักโทษตรอมใจ)',
      'The Haunted Dungeons of Corvin Castle (Hunyadi)',
      'ghost',
      'ฮูเนโดอารา',
      'Hunedoara',
      'ฮูเนโดอารา',
      'Hunedoara',
      45.7494,
      22.8883,
      'creepy_wind',
      'หนึ่งในปราสาทโกธิกที่ใหญ่ที่สุดในยุโรปตะวันออก ที่ซึ่ง วลาด จอมเสียบ (แดร็กคูลา) เคยถูกจองจำในคุกใต้ดินนานหลายปี นอกจากนี้ยังมีบ่อน้ำลึกที่นักโทษชาวเติร์กสามคนถูกบังคับให้ขุดหินลึกกว่า 28 เมตรเป็นเวลา 15 ปีเพื่อแลกกับอิสรภาพ ทว่าเมื่อขุดเจอน้ำกลับถูกสั่งประหารชีวิต ก่อนตายพวกเขาได้สลักข้อความไว้บนหินว่า ''เจ้ามีน้ำ แต่เจ้าไร้หัวใจ'' วิญญาณของนักโทษและร่างเงาดำมักปรากฏตัวคุกคามผู้บุกรุกห้องทรมาน',
      'Corvin Castle is a magnificent Transylvanian fortress where Vlad the Impaler was allegedly held captive in dark pits. In the courtyard lies a deep well hand-carved by three Ottoman prisoners over 15 years under the promise of freedom; upon completion, they were executed anyway. An inscription on the wall bitterly warns: ''You have water, but no heart.'' Shadows, cold suffocating drafts, and aggressive apparitions haunt the bear pit and torture towers.',
      'ปราสาทคอร์วินมีชื่อเสียงระดับโลกในฐานะแรงบันดาลใจของปราสาทแดร็กคูลาในนิยาย และเคยใช้เป็นสถานที่ถ่ายทำภาพยนตร์สยองขวัญระดับฮอลลีวูดหลายเรื่อง เช่น The Nun',
      'Renowned for its dramatic Gothic drawbridge and torture towers, Corvin Castle served as the filming location for ''The Nun'' and remains Romania''s premier paranormal hotspot.',
      'ห้ามโยนเหรียญหรือสิ่งปฏิกูลลงในบ่อน้ำโบราณของนักโทษเติร์ก',
      'Never spit or throw litter into the 15th-century Turkish prisoner well.',
      'https://i.ytimg.com/vi/YVGwnroncDY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/YVGwnroncDY/hqdefault.jpg","title":"ปราสาทคอร์วิน (คุกขังแดร็กคูลาและวิญญาณนักโทษตรอมใจ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=YVGwnroncDY","title":"Our Horrifying Night at Haunted DRACULA''S CASTLE (Real Vampire)","thumbnail":"https://i.ytimg.com/vi/YVGwnroncDY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-bodiam-castle-knight',
      'อัศวินผีแห่งปราสาทโบเดียม (วิญญาณเฝ้าคูน้ำแห่งซัสเซกซ์)',
      'The Phantom Knight of Bodiam Castle Moat',
      'ghost',
      'อีสต์ ซัสเซกซ์',
      'East Sussex',
      'โบเดียม',
      'Bodiam',
      51.0023,
      0.5434,
      'water_spirit',
      'ปราสาทคูน้ำในศตวรรษที่ 14 ที่งดงามราวกับภาพวาดในเทพนิยาย สร้างขึ้นเพื่อป้องกันการรุกรานของฝรั่งเศสในสงครามร้อยปี ทว่ามีเรื่องเล่าของอัศวินในชุดเกราะเหล็กโบราณที่ยังคงเดินตรวจตราบนสะพานไม้ข้ามคูน้ำในคืนหมอกลงจัด มีพยานเห็นร่างของอัศวินยืนนิ่งจ้องมองลงไปในน้ำ ก่อนจะกระโดดลงไปในคูน้ำอย่างช้าๆ แต่เมื่อวิ่งไปดูผิวน้ำกลับนิ่งสนิทไร้ระลอกคลื่นและไม่มีใครอยู่ในน้ำเลย',
      'Surrounded by a shimmering spring-fed moat, Bodiam Castle was constructed in 1385 by Sir Edward Dalyngrigge. On foggy autumn evenings, witnesses have spotted a medieval knight clad in plate armor standing sentry upon the drawbridge rampart. The spectral figure gazes down into the dark moat before diving silently into the water, producing not a single splash or ripple.',
      'ปราสาทโบเดียมถูกทำลายภายในช่วงสงครามกลางเมืองอังกฤษ ก่อนจะได้รับการอนุรักษ์โดยลอร์ดเคอร์ซอน และมอบให้เนชันแนลทรัสต์ดูแลในปี 1925',
      'A prime example of 14th-century moated military architecture, Bodiam''s serene exterior conceals centuries of ghost lore recorded by local anglers and park rangers.',
      'ห้ามลงไปว่ายน้ำหรือพายเรือในคูน้ำรอบปราสาทโบเดียม',
      'Never enter or wade into the castle''s protective moat waters.',
      'https://i.ytimg.com/vi/m-A_gvsJwJc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/m-A_gvsJwJc/hqdefault.jpg","title":"อัศวินผีแห่งปราสาทโบเดียม (วิญญาณเฝ้าคูน้ำแห่งซัสเซกซ์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=m-A_gvsJwJc","title":"Bodiam Castle - East Sussex, England","thumbnail":"https://i.ytimg.com/vi/m-A_gvsJwJc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-koh-kham-spirits',
      'อาถรรพ์หาดกระดูกเกาะขามใหญ่ (วิญญาณเชลยศึกสัตหีบ)',
      'The Spectral Beaches of Koh Kham (Sattahip)',
      'ghost',
      'ชลบุรี',
      'Chonburi',
      'สัตหีบ',
      'Sattahip',
      12.5714,
      100.9388,
      'water_spirit',
      'เกาะเล็กๆ นอกชายฝั่งสัตหีบที่มีหาดทรายขาวและปะการังสมบูรณ์ ทว่าในอดีตยุคสงคราม เกาะแห่งนี้เคยถูกใช้เป็นที่คุมขังและฝังศพของเชลยศึกและผู้เสียชีวิตจากโรคระบาด มีเรื่องเล่าของชาวประมงที่จอดเรือหลบลมมรสุมว่า ในยามค่ำคืนมักได้ยินเสียงคนเดินลากโซ่ตรวนบนผืนทราย เสียงร้องขออาหารและน้ำดื่ม และเห็นเงาร่างคนนับสิบยืนมองมาจากชายป่าริมหาด จนไม่มีเรือลำใดกล้าเทียบฝั่งค้างคืน',
      'Koh Kham is a tranquil island sanctuary off Sattahip, administered under marine conservation. In wartime eras, historical accounts tell of quarantine stations and mass graves of prisoners and malaria victims. Local squid fishermen mooring near the island at night report auditory horrors: the clinking of iron chains dragged along the sand, agonizing cries begging for water, and silhouettes standing motionless at the tree line.',
      'ปัจจุบันเกาะขามเป็นอุทยานใต้ทะเลที่เปิดให้นักท่องเที่ยวเดินทางไปเยือนเฉพาะแบบไปเช้า-เย็นกลับ โดยกองทัพเรือไม่อนุญาตให้พักค้างคืนบนเกาะ เพื่ออนุรักษ์ธรรมชาติและหลีกเลี่ยงอันตราย',
      'Managed by the Royal Thai Navy as an eco-tourism park, overnight stays are strictly prohibited, preserving both the delicate coral reefs and its eerie nocturnal solitude.',
      'ห้ามลักลอบตั้งแคมป์หรือค้างคืนบนเกาะขามโดยไม่ได้รับอนุญาต',
      'Never camp overnight on the shores of Koh Kham without naval clearance.',
      'https://i.ytimg.com/vi/LcoKYzFtsvo/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/LcoKYzFtsvo/hqdefault.jpg","title":"อาถรรพ์หาดกระดูกเกาะขามใหญ่ (วิญญาณเชลยศึกสัตหีบ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=LcoKYzFtsvo","title":"เกาะผี (สุสานกลางทะเล) ที่จังหวัดชลบุรี | เล่าเรื่องหลอน EP.3","thumbnail":"https://i.ytimg.com/vi/LcoKYzFtsvo/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-pennhurst-asylum-spirits',
      'วิญญาณแห่งโรงพยาบาลเพนน์เฮิร์สต์ (สถานบำบัดร้างต้องสาป)',
      'The Apparitions of Pennhurst State School & Hospital',
      'ghost',
      'เพนซิลเวเนีย',
      'Pennsylvania',
      'สปริงซิตี',
      'Spring City',
      40.1809,
      -75.5802,
      'whisper',
      'สถานดูแลผู้มีความบกพร่องทางสติปัญญาที่เปิดทำการในปี 1908 และกลายเป็นสถานที่แห่งความทุกข์ทรมานอันดำมืด ผู้ป่วยกว่าหมื่นคนต้องทนทุกข์จากการถูกทอดทิ้ง การผูกมัดกับเตียง และการทำทารุณกรรม จนถูกสั่งปิดอย่างเป็นทางการในปี 1987 หลังถูกแฉในรายงาน ''Suffer the Little Children'' ผู้มาเยือนสถานที่ร้างแห่งนี้มักได้ยินเสียงเด็กร้องไห้กระซิก เสียงเขย่าเตียงเหล็ก และมีรอยข่วนลึกลับปรากฏขึ้นตามร่างกาย',
      'Opened in 1908, Pennhurst became infamous for horrific overcrowding, electro-shock abuse, and brutal neglect of thousands of mentally challenged patients. Exposed in 1968 by investigative reporter Bill Baldini''s ''Suffer the Little Children'', it was shuttered in 1987. Paranormal investigators frequently record child-like EVPs pleading for help, objects hurling across corridors, and sudden painful scratches appearing on visitors'' arms.',
      'คดีฟ้องร้องโรงพยาบาลเพนน์เฮิร์สต์ (Halderman v. Pennhurst) เป็นคดีหมุดหมายสำคัญที่นำไปสู่กฎหมายสิทธิคนพิการในสหรัฐอเมริกา ปัจจุบันอาคารบางส่วนเปิดเป็นบ้านผีสิงและทัวร์ประวัติศาสตร์',
      'A landmark civil rights turning point for individuals with intellectual disabilities, Pennhurst''s tragic past makes it one of America''s most emotionally charged paranormal research sites.',
      'ห้ามรื้อค้นหรือขโมยแฟ้มประวัติการรักษาเก่าของผู้ป่วยในอาคารร้าง',
      'Never tamper with or steal historic patient medical records from the asylum.',
      'https://i.ytimg.com/vi/7gPQ2KGFt3w/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/7gPQ2KGFt3w/hqdefault.jpg","title":"วิญญาณแห่งโรงพยาบาลเพนน์เฮิร์สต์ (สถานบำบัดร้างต้องสาป)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7gPQ2KGFt3w","title":"The Twisted Story Of The Asylum That Inspired Stranger Things: Pennhurst State School","thumbnail":"https://i.ytimg.com/vi/7gPQ2KGFt3w/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-tombstone-bird-cage-theatre',
      'โรงละครเบิร์ดเคจแห่งทูมสโตน (รังดวลปืนและวิญญาณคาวบอย)',
      'The Hauntings of the Bird Cage Theatre (Tombstone)',
      'ghost',
      'แอริโซนา',
      'Arizona',
      'ทูมสโตน',
      'Tombstone',
      31.7126,
      -110.0654,
      'creepy_wind',
      'ซาลูนและโรงละครเริงรมย์ยุคคาวบอยตะวันตกที่เปิดบริการในปี 1881 เปิดตลอด 24 ชั่วโมงต่อเนื่องยาวนานถึง 8 ปี มีการบันทึกว่าเกิดเหตุยิงปืนและฆาตกรรมสังหารชีวิตผู้คนภายในร้านถึง 26 ราย โดยยังมีรูกระสุนปืนกว่า 140 รูฝังอยู่ตามผนังและเพดาน จนถึงปัจจุบันยังคงมีกลิ่นควันซิการ์และวิสกี้ลอยคลุ้ง เสียงเพลงเปียโนบรรเลงเอง และวิญญาณของคาวบอยในหมวกปีกกว้างจ้องมองลงมาจากกล่องที่นั่งชั้นบน',
      'Operating 24 hours a day from 1881 to 1889, the Bird Cage Theatre was described by the New York Times as ''the wildest, wickedest night spot between the Barbary Coast and the Bowery.'' At least 26 people were gunned down inside, leaving over 140 bullet holes in the walls and ceilings. Visitors and caretakers routinely smell fresh phantom cigar smoke, hear saloon piano chords striking in empty rooms, and see ladies of the night peering from the suspended balcony cages.',
      'ของตกแต่งและเครื่องเรือนดั้งเดิมในโรงละครเบิร์ดเคจยังคงถูกเก็บรักษาไว้ในสภาพเดิมนับตั้งแต่ถูกปิดตัวลงในปี 1889 ทำให้เป็น ''แคปซูลกาลเวลา'' ที่สมบูรณ์ที่สุดของยุคคาวบอย',
      'Left virtually untouched since 1889, the Bird Cage Theatre houses authentic poker tables, bullet-scarred paintings, and original Victorian furnishings.',
      'ห้ามล้อเลียนหรือสัมผัสรูกระสุนปืนบนภาพวาดเปลือยของมาร์การิตา',
      'Never touch or desecrate the bullet holes embedded in the historic Margarita canvas.',
      'https://i.ytimg.com/vi/AzTq8zUMaok/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/AzTq8zUMaok/hqdefault.jpg","title":"โรงละครเบิร์ดเคจแห่งทูมสโตน (รังดวลปืนและวิญญาณคาวบอย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=AzTq8zUMaok","title":"The Birdcage Theater in Tombstone Is Haunted As F**k | THE PARANORMAL FILES","thumbnail":"https://i.ytimg.com/vi/AzTq8zUMaok/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-alamo-phantom-defenders',
      'วิญญาณนักรบผู้พิทักษ์แห่งเดอะอลาโม (ศึกสังหาร 1836)',
      'The Phantom Defenders of The Alamo',
      'ghost',
      'เท็กซัส',
      'Texas',
      'แซนแอนโทนีโอ',
      'San Antonio',
      29.426,
      -98.4861,
      'creepy_wind',
      'สมรภูมิรบประวัติศาสตร์ที่นักรบชาวเท็กซัสกว่า 180 คน นำโดย เดวี่ คร็อกเก็ตต์ และ เจมส์ โบวี ยอมสละชีวิตต่อสู้กับกองทัพเม็กซิโกจนตัวตาย หลังชัยชนะ นายพลซานตาแอนนาได้สั่งให้ทหารรื้อทำลายอาสนวิหารอลาโม ทว่าทหารเม็กซิกันต่างวิ่งหนีเตลิดออกมาด้วยความกลัว เมื่อเห็นวิญญาณนักรบถือดาบเพลิงปรากฏขึ้นขวางทางไว้ จนถึงปัจจุบัน เจ้าหน้าที่รักษาความปลอดภัยยังคงได้ยินเสียงยิงปืนคาบศิลาและเห็นเงาทหารลาดตระเวนบนกำแพง',
      'In 1836, nearly 200 Texan defenders made their legendary last stand at the Alamo mission against thousands of Mexican troops under General Santa Anna. Following the massacre, Santa Anna ordered the chapel demolished, but his soldiers fled in terror, claiming fiery spirits with drawn swords materialized from the walls to protect the shrine. Centuries later, phantom bugle calls, rifle shots, and sentry figures continue to guard the courtyard.',
      'เดอะอลาโมเป็นสัญลักษณ์แห่งเสรีภาพของรัฐเท็กซัสและเป็นมรดกโลกยูเนสโก เรื่องเล่าเรื่องวิญญาณผู้พิทักษ์ได้รับการบันทึกในเอกสารทางทหารของกองทัพเม็กซิกันตั้งแต่ปี 1836',
      'Recorded in Mexican army correspondence shortly after the battle, the legend of the Alamo''s supernatural guardians has been passed down as an essential chapter of Texas lore.',
      'ห้ามสวมหมวกและต้องอยู่ในความสงบเมื่อก้าวเข้าสู่อาสนวิหารอลาโม',
      'Remove hats and maintain silence inside the sacred Alamo sanctuary.',
      'https://i.ytimg.com/vi/yyOF8MkN0M0/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/yyOF8MkN0M0/hqdefault.jpg","title":"วิญญาณนักรบผู้พิทักษ์แห่งเดอะอลาโม (ศึกสังหาร 1836)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=yyOF8MkN0M0","title":"The Walls That Would Not Burn: The Ghosts of the Alamo, 1836 | A Pops Audio Documentary","thumbnail":"https://i.ytimg.com/vi/yyOF8MkN0M0/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-trans-allegheny-lunatic-asylum',
      'วิญญาณแห่งโรงพยาบาลบ้าทรานส์-อัลเลเกนี (เวสตัน)',
      'The Phantom Patients of Trans-Allegheny Lunatic Asylum',
      'ghost',
      'เวสต์เวอร์จิเนีย',
      'West Virginia',
      'เวสตัน',
      'Weston',
      39.0383,
      -80.4682,
      'whisper',
      'อาคารหินที่ตัดด้วยมือที่ใหญ่เป็นอันดับสองของโลกรองจากพระราชวังเครมลิน ออกแบบมาเพื่อรองรับผู้ป่วย 250 คน ทว่าในช่วงยุค 1950 กลับมีผู้ป่วยถูกกักขังอย่างแออัดถึง 2,400 คน ความอดอยาก การขังเดี่ยวในกรง และการผ่าตัดสมองส่วนหน้า (Lobotomy) นับพันครั้ง ทำให้มีผู้เสียชีวิตนับไม่ถ้วน วิญญาณของ ''ลิลี่'' เด็กหญิงวัย 9 ขวบที่เกิดและเสียชีวิตในโรงพยาบาล มักจะกลิ้งลูกบอลของเล่นมาชนขาของผู้มาเยือนในความมืด',
      'Constructed between 1858 and 1881, this colossal hand-cut stone asylum was designed for 250 souls but held over 2,400 patients during its peak in horrific, freezing conditions. Thousands underwent experimental lobotomies and electroshock therapy. The most famous resident ghost is ''Lily'', a nine-year-old girl who spent her brief life inside the wards; visitors sitting in her fourth-floor room often feel her phantom hands tugging on their clothes or rolling her antique ball.',
      'โรงพยาบาลถูกสั่งปิดตัวลงในปี 1994 และได้รับการขึ้นทะเบียนเป็นโบราณสถานแห่งชาติของสหรัฐฯ ปัจจุบันเปิดให้เข้าชมทัวร์ประวัติศาสตร์และทัวร์ล่าผีข้ามคืนที่โด่งดังระดับโลก',
      'A National Historic Landmark, the asylum is celebrated for its imposing Gothic Revival architecture and remains a premier destination for paranormal investigators worldwide.',
      'ห้ามหยิบหรือขโมยของเล่นในห้องเด็กหญิงลิลี่ติดมือออกมา',
      'Never take or pocket any vintage toys left in Lily''s fourth-floor room.',
      'https://i.ytimg.com/vi/l9fxh6tlAIQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/l9fxh6tlAIQ/hqdefault.jpg","title":"วิญญาณแห่งโรงพยาบาลบ้าทรานส์-อัลเลเกนี (เวสตัน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=l9fxh6tlAIQ","title":"Intense Investigation At The Trans-Allegheny Lunatic Asylum | Paranormal Lockdown","thumbnail":"https://i.ytimg.com/vi/l9fxh6tlAIQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-ghost-ballygally-castle-lady-isabella',
      'เลดี้อิซาเบลลา ชอว์ แห่งปราสาทบัลลีกัลลี (วิญญาณเคาะประตู)',
      'Lady Isabella Shaw of Ballygally Castle',
      'ghost',
      'แอนทริม',
      'County Antrim',
      'บัลลีกัลลี',
      'Ballygally',
      54.8998,
      -5.8569,
      'whisper',
      'ปราสาทในศตวรรษที่ 17 ริมชายฝั่งทะเลไอริช ลอร์ดเจมส์ ชอว์ ได้ขัง เลดี้อิซาเบลลา ภรรยาของตนไว้ในหอคอยบนสุดของปราสาทหลังจากที่เธอคลอดบุตรชาย เพื่อแย่งชิงทารกไปเลี้ยงดูคนเดียว ด้วยความหิวกระหายและความสิ้นหวังในการหาลูก เธอจึงพยายามปีนหนีออกทางหน้าต่างแต่พลัดตกลงมาเสียชีวิต วิญญาณของเธอยังคงวนเวียนอยู่ในปราสาทซึ่งปัจจุบันเป็นโรงแรม โดยเธอมักจะเคาะประตูห้องพักเบาๆ ในยามดึกเพื่อตามหาลูกชาย',
      'Built in 1625, Ballygally Castle sits on the scenic Antrim coast. Lord James Shaw locked his wife, Lady Isabella, in a freezing tower chamber immediately after she gave birth to an heir. While attempting to escape through the window to reach her infant child, she plunged to her death on the stones below. Now operating as a luxury hotel, guests in the ''Ghost Room'' regularly report gentle knocking on their doors and the scent of sweet vanilla perfume.',
      'ปราสาทบัลลีกัลลีเป็นอาคารที่อยู่อาศัยในศตวรรษที่ 17 เพียงแห่งเดียวในไอร์แลนด์เหนือที่ยังมีผู้ใช้งานอยู่ ทางโรงแรมได้เปิดห้องบนหอคอยให้เป็น ''ห้องผี'' (Ghost Room) เพื่อเป็นเกียรติแก่เลดี้อิซาเบลลา',
      'Known as one of Northern Ireland''s friendliest ghosts, Lady Isabella''s tower chamber remains open to visitors, and hotel staff maintain a dedicated ledger of guest sightings.',
      'ห้ามปิดล็อกประตูหอคอยห้องผี (Ghost Room) ทิ้งไว้',
      'Never padlock or bar the door to Lady Isabella''s tower turret room.',
      'https://i.ytimg.com/vi/ZqkLLdbbHT8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/ZqkLLdbbHT8/hqdefault.jpg","title":"เลดี้อิซาเบลลา ชอว์ แห่งปราสาทบัลลีกัลลี (วิญญาณเคาะประตู)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=ZqkLLdbbHT8","title":"Who Haunts Ballygally Castle in Northern Ireland? The TRUTH Behind the Legend of Lady Isabella Shaw","thumbnail":"https://i.ytimg.com/vi/ZqkLLdbbHT8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-wat-chalermprakiat-lampang',
      'วัดพระพุทธบาทสุทธาวาส (เจดีย์ลอยฟ้าบนยอดเขาหินปูนลำปาง)',
      'Wat Phra Phutthabat Sutthawat (Sky Pagodas of Lampang)',
      'sacred',
      'ลำปาง',
      'Lampang',
      'แจ้ห่ม',
      'Chae Hom',
      18.7369,
      99.5539,
      'temple_bell',
      'วัดเฉลิมพระเกียรติพระจอมเกล้าราชานุสรณ์ หรือวัดพระพุทธบาทสุทธาวาส ตั้งตระหง่านอยู่บนยอดเขาหินปูนสูงเสียดฟ้าในอำเภอแจ้ห่ม โดดเด่นด้วยเจดีย์สีขาวสีทองนับสิบองค์ที่สร้างอยู่บนชะง่อนผาแคบๆ อย่างน่าอัศจรรย์ ด้วยพลังศรัทธาของพระสงฆ์และชาวบ้านที่แบกหิน ปูน และเหล็กขึ้นบันไดหลายพันขั้นด้วยแรงกายเพื่อสร้างเจดีย์ถวายเป็นพุทธบูชา บนยอดเขายังมีรอยพระพุทธบาทประดิษฐานอยู่ ท่ามกลางทะเลหมอกที่พัดผ่านราวกับสวรรค์บนดิน',
      'Perched precariously atop jagged limestone pinnacles in northern Thailand, Wat Phra Phutthabat Sutthawat features white and gold stupas seemingly suspended in the clouds. Built through the sheer devotion of monks and villagers who carried bricks, mortar, and iron by hand up steep mountain trails, the sacred sanctuary houses an ancient Buddha footprint and offers panoramic vistas over misty valleys.',
      'สร้างขึ้นเพื่อเฉลิมพระเกียรติพระบาทสมเด็จพระจอมเกล้าเจ้าอยู่หัว รัชกาลที่ 4 ในโอกาสครบรอบ 200 ปีแห่งวันพระบรมราชสมภพ ปัจจุบันเป็นหนึ่งใน Unseen Thailand ที่มีชื่อเสียงไปทั่วโลก',
      'Constructed to honor the 200th birth anniversary of King Rama IV, this mountain sanctuary is regarded as one of the most sublime Buddhist pilgrimage sites in Southeast Asia.',
      'ห้ามส่งเสียงดัง ปีนป่ายออกนอกระเบียงผา หรือเหยียบบนฐานเจดีย์ศักดิ์สิทธิ์',
      'Never climb outside protective safety railings or step on stupa plinths.',
      'https://i.ytimg.com/vi/7dhkA7dogKs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/7dhkA7dogKs/hqdefault.jpg","title":"วัดพระพุทธบาทสุทธาวาส (เจดีย์ลอยฟ้าบนยอดเขาหินปูนลำปาง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7dhkA7dogKs","title":"เจดีย์ลอยฟ้า บนยอดดอยปู่ยักษ์! วิว 360 องศา วัดเฉลิมพระเกียรติฯ ลำปาง| เที่ยวทั่วไทยไปกับพี่หมู","thumbnail":"https://i.ytimg.com/vi/7dhkA7dogKs/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-phra-that-cho-hae-phrae',
      'วัดพระธาตุช่อแฮ (พระธาตุประจำปีเกิดปีขาลแห่งเมืองแพร่)',
      'Wat Phra That Cho Hae (Sacred Tiger Year Relic of Phrae)',
      'sacred',
      'แพร่',
      'Phrae',
      'เมืองแพร่',
      'Mueang Phrae',
      18.0858,
      100.2036,
      'temple_bell',
      'พระธาตุคู่บ้านคู่เมืองแพร่ เจดีย์ทรงแปดเหลี่ยมศิลปะล้านนาสีทองอร่าม สูง 33 เมตร บรรจุพระเกศาธาตุและพระบรมสารีริกธาตุพระศอกซ้ายขององค์สมเด็จพระสัมมาสัมพุทธเจ้า ตามตำนานเล่าว่าพระพุทธองค์เคยเสด็จมาประทับ ณ ดอยโกสิยธชัคคะบรรพต และประทานพระเกศาธาตุให้แก่ขุนลัวะอ้ายก้อม เชื่อกันว่าผู้ที่เกิดปีขาล (ปีเสือ) หากได้เดินทางมากราบไหว้และห่มผ้าแพรพรรณรอบองค์พระธาตุ จะได้รับพรอันประเสริฐ คุ้มครองให้แคล้วคลาดจากภยันตรายทั้งปวง',
      'Wat Phra That Cho Hae is an ancient Lanna-style octagonal golden chedi standing 33 meters tall. Enshrining the holy hair relic and left elbow relic of Gautama Buddha, ancient chronicles state that the Buddha visited this hill and gifted relics to the Lua chieftain. In Northern Thai Buddhist astrology, it is the sacred pilgrimage temple for people born in the Year of the Tiger, granting protection from misfortune.',
      'สร้างขึ้นในสมัยขุนลัวะอ้ายก้อม และได้รับการบูรณะโดยครูบาศรีวิชัย นักบุญแห่งล้านนา ในปี พ.ศ. 2467 มีประเพณีไหว้พระธาตุช่อแฮเมืองแพร่แห่ผ้าขึ้นธาตุในวันเพ็ญเดือนหกเหนือเป็นประจำทุกปี',
      'Restored in 1924 by the venerable monk Kruba Srivichai, the temple hosts the annual Cho Hae festival where devotees parade vibrant silk fabrics up the Naga stairs.',
      'ห้ามสวมรองเท้าขึ้นสู่ลานประทักษิณรอบองค์พระธาตุ',
      'Remove all footwear before entering the sacred golden circumambulation terrace.',
      'https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg","title":"วัดพระธาตุช่อแฮ (พระธาตุประจำปีเกิดปีขาลแห่งเมืองแพร่)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=KsnE0OGg2tk","title":"ตำนาน “พระธาตุช่อแฮ” พระธาตุปีขาล สิ่งศักดิ์สิทธิ์สำคัญคู่เมืองแพร่ I ร้อยเรื่องเมืองล้านนา","thumbnail":"https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-kailash-parikrama-tibet',
      'เขาไกรลาส (ศูนย์กลางจักรวาลและการแสวงบุญพาริครามา)',
      'Mount Kailash Sacred Parikrama (Axis Mundi of Tibet)',
      'sacred',
      'งารี',
      'Ngari Prefecture',
      'ปูรัง',
      'Burang',
      31.0675,
      81.3119,
      'temple_bell',
      'ยอดเขาปิรามิดหิมะสีดำขาวสูง 6,638 เมตรในเทือกเขาหิมาลัยของทิเบต ได้รับการเคารพเป็น ''ศูนย์กลางจักรวาล'' (Axis Mundi) และที่สถิตของพระศิวะในศาสนาฮินดู รวมถึงเป็นสถานที่ศักดิ์สิทธิ์สูงสุดของศาสนาพุทธมหายาน ไชนะ และบอน ด้วยความศักดิ์สิทธิ์ ยอดเขาไกรลาสจึงไม่เคยมีมนุษย์คนใดปีนขึ้นไปถึงยอด ผู้แสวงบุญจะเดินเท้าวนรอบภูเขาเป็นระยะทาง 52 กิโลเมตร หรือกราบอัษฎางคประดิษฐ์ไปตลอดเส้นทางเพื่อชำระล้างบาปทั้งชีวิต',
      'Rising majestically in western Tibet, Mount Kailash is regarded by Hindus, Buddhists, Jains, and Bonpos as the cosmological Axis Mundi—the physical center of the spiritual universe and throne of Lord Shiva. Because of its profound sanctity, no climber has ever set foot upon its summit. Pilgrims undertake the arduous 52-kilometer Kora trek over high mountain passes (reaching 5,630m at Drolma La), believing a single circumambulation erases a lifetime of sins.',
      'ในตำนานพุทธศาสนาทิเบต เคยมีการประลองฤทธิ์บนยอดเขาไกรลาสระหว่าง มิลาเรปะ นักปราชญ์โยคีผู้ยิ่งใหญ่ กับ นาโร บอนชุง นักบวชศาสนาบอน โดยมิลาเรปะสามารถขี่แสงอาทิตย์ขึ้นสู่ยอดเขาได้ก่อน',
      'Tibetan texts recount the magical duel between Buddhist yogi Milarepa and Bon master Naro Bon-chung atop Kailash. Modern treaties between China and India govern pilgrim access to this revered summit.',
      'ห้ามปีนป่ายขึ้นสู่ยอดเขาไกรลาสโดยเด็ดขาดเพื่อรักษาความบริสุทธิ์ของเทพเจ้า',
      'Never attempt to scale or set foot upon the summit of Mount Kailash.',
      'https://i.ytimg.com/vi/dBOSdDNIf8g/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/dBOSdDNIf8g/hqdefault.jpg","title":"เขาไกรลาส (ศูนย์กลางจักรวาลและการแสวงบุญพาริครามา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=dBOSdDNIf8g","title":"Tibetan mythical mountain nobody dares to climb | SLICE | FULL DOCUMENTARY","thumbnail":"https://i.ytimg.com/vi/dBOSdDNIf8g/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-adam-peak-sri-lanka',
      'ศรีปาทะ หรือ ยอดเขาอาดัม (รอยพระพุทธบาทศักดิ์สิทธิ์ศรีลังกา)',
      'Sri Pada / Adam''s Peak Sacred Footprint (Sri Lanka)',
      'sacred',
      'ซาบารากามุวา',
      'Sabaragamuwa Province',
      'รัตนปุระ',
      'Ratnapura',
      6.8096,
      80.4994,
      'temple_bell',
      'ยอดเขารูปทรงกรวยสูง 2,243 เมตรที่โดดเด่นเหนือป่าดงดิบของศรีลังกา บนยอดเขามีรอยประทับหินศักดิ์สิทธิ์ขนาดยาว 1.8 เมตร ชาวพุทธเคารพว่าเป็นรอยพระพุทธบาทของพระสัมมาสัมพุทธเจ้า ชาวฮินดูเชื่อว่าเป็นรอยเท้าของพระศิวะ ชาวมุสลิมและคริสต์เชื่อว่าเป็นรอยเท้าแรกของอาดัมเมื่อถูกขับออกจากสวรรค์ ผู้แสวงบุญนับหมื่นจะเดินขึ้นบันไดหินกว่า 5,500 ขั้นในยามค่ำคืนเพื่อขึ้นไปตีระฆังตามจำนวนครั้งที่มาเยือนและชมเงาสามเหลี่ยมศักดิ์สิทธิ์ยามรุ่งอรุณ',
      'Sri Pada (Adam''s Peak) is a solitary, pyramid-like peak revered across four major world faiths. Enshrined in a rock sanctuary at its summit is a 5.9-foot rock footprint: revered by Buddhists as the footprint of Gautama Buddha, by Hindus as Lord Shiva''s imprint, and by Muslims and Christians as the first step of Adam upon Earth. Pilgrims climb over 5,500 stone stairs through chilly night mists to ring the sacred brass bell at sunrise.',
      'การแสวงบุญสู่ศรีปาทะมีประวัติศาสตร์ยาวนานกว่าพันปี ได้รับการบันทึกโดย มาร์โค โปโล ในศตวรรษที่ 13 และ อิบนุ บัตตูตา ในศตวรรษที่ 14',
      'Chronicled by Marco Polo and Ibn Battuta, Sri Pada is famous for the ''Shadow of the Peak'', where the mountain casts a perfect optical triangle upon the surrounding clouds at dawn.',
      'ห้ามบ่นเรื่องความเหนื่อยล้า หรือแซงผู้อาวุโสขณะเดินขึ้นบันไดแสวงบุญ',
      'Never complain of physical fatigue during the arduous ascent up Sri Pada.',
      'https://i.ytimg.com/vi/DmGlKVnCuaQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/DmGlKVnCuaQ/hqdefault.jpg","title":"ศรีปาทะ หรือ ยอดเขาอาดัม (รอยพระพุทธบาทศักดิ์สิทธิ์ศรีลังกา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=DmGlKVnCuaQ","title":"Hike Sri Pada, Sri Palabaddala Trail / Ancient Hidden Route to Adam’s Peak, Sri Lanka","thumbnail":"https://i.ytimg.com/vi/DmGlKVnCuaQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-varanasi-dashashwamedh-ghat',
      'ทศอัศวเมธฆาฏ พาราณสี (พิธีคงคาอารตีและไฟศักดิ์สิทธิ์)',
      'Dashashwamedh Ghat & The Sacred Ganga Aarti (Varanasi)',
      'sacred',
      'อุตตรประเทศ',
      'Uttar Pradesh',
      'พาราณสี',
      'Varanasi',
      25.3076,
      83.0107,
      'temple_bell',
      'ท่าน้ำที่สำคัญและศักดิ์สิทธิ์ที่สุดริมฝั่งแม่น้ำคงคาในเมืองพาราณสี นครโบราณที่มีชีวิตต่อเนื่องยาวนานที่สุดแห่งหนึ่งของโลก ตำนานฮินดูเล่าว่า พระพรหมทรงสร้างฆาฏแห่งนี้ขึ้นเพื่อประกอบพิธีบูชายัญม้าสิบตัว (ทศ-อัศวเมธ) ถวายแด่พระศิวะ ในทุกๆ ยามเย็น พราหมณ์หนุ่มจะประกอบพิธีคงคาอารตี จุดตะเกียงไฟทองเหลืองขนาดใหญ่ สั่นกระดิ่ง และเป่าสังข์ เพื่อถวายการบูชาต่อพระแม่คงคา ก่อเกิดภาพเปลวไฟระยิบระยับสะท้อนผืนน้ำอันเปี่ยมมนต์ขลัง',
      'Dashashwamedh Ghat is the pulsating spiritual heart of Varanasi, the ancient city of Lord Shiva. According to Hindu mythology, Lord Brahma created this ghat to welcome Shiva, sacrificing ten horses (dasa-ashwamedha) in sacred yajna. Every twilight, young Brahmin priests clad in silk perform the spectacular Ganga Aarti, lifting massive multi-tiered brass oil lamps amidst the chiming of temple bells and blowing of conch shells to honor the sacred river.',
      'พาราณสีเป็นศูนย์กลางการจาริกแสวงบุญของชาวฮินดูมานานกว่าสามพันปี การอาบน้ำล้างบาปที่ทศอัศวเมธฆาฏเชื่อว่าจะช่วยปลดเปลื้องสังสารวัฏและนำพาดวงวิญญาณสู่การหลุดพ้น (โมกษะ)',
      'Mark Twain famously observed that Varanasi is ''older than history, older than tradition.'' The nightly Ganga Aarti remains one of the world''s most mesmerizing unbroken sacred rituals.',
      'ห้ามสวมรองเท้าลงไปยืนในพื้นที่ทำพิธีของคณะพราหมณ์ริมบันไดฆาฏ',
      'Remove leather shoes and maintain reverence along the ceremonial ghat steps.',
      'https://i.ytimg.com/vi/eNeGm86PgvU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/eNeGm86PgvU/hqdefault.jpg","title":"ทศอัศวเมธฆาฏ พาราณสี (พิธีคงคาอารตีและไฟศักดิ์สิทธิ์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=eNeGm86PgvU","title":"Maa Ganga Aarti By Ganga Seva Nidhi Dashashwamedh Ghat, Varanasi","thumbnail":"https://i.ytimg.com/vi/eNeGm86PgvU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-lourdes-miracle-spring-france',
      'ถ้ำศักดิ์สิทธิ์แห่งลูร์ดส์ (น้ำพุมหัศจรรย์รักษาโรคแห่งฝรั่งเศส)',
      'Sanctuary of Our Lady of Lourdes & Healing Spring',
      'sacred',
      'โอต-ปีเรเน',
      'Hautes-Pyrenees',
      'ลูร์ดส์',
      'Lourdes',
      43.0975,
      -0.0583,
      'water_spirit',
      'ในปี 1858 ณ ถ้ำมาสซาบีแอล แบร์นาเดตต์ ซูบีรูส์ เด็กสาวชาวนาผู้ยากจน ได้พบเห็นนิมิตของสตรีงามในชุดขาวคาดสายรัดเอวสีฟ้า ซึ่งบอกว่าเธอคือ ''การปฏิสนธินิรมล'' (พระแม่มารีย์) พระแม่ได้บอกให้เด็กหญิงขุดดินในถ้ำ ทันใดนั้นมีน้ำพุใสสะอาดพุ่งขึ้นมาจากพื้นดิน น้ำพุแห่งนี้ได้รับการบันทึกว่ารักษาผู้ป่วยอัมพาต ตาบอด และโรคร้ายแรงให้หายได้อย่างปาฏิหาริย์ จนกลายเป็นศูนย์กลางการแสวงบุญของคริสตชนกว่า 6 ล้านคนต่อปี',
      'In 1858 at the Grotto of Massabielle, 14-year-old peasant girl Bernadette Soubirous witnessed 18 apparitions of a luminous lady who revealed herself as the ''Immaculate Conception''. Instructed to dig into the muddy ground, Bernadette uncovered a freshwater spring. Since then, millions of pilgrims—many terminally ill or paralyzed—have bathed in the spring waters, resulting in 70 medically verified miraculous cures officially recognized by the Catholic Church.',
      'สำนักการแพทย์แห่งลูร์ดส์ (Lourdes Medical Bureau) เป็นหน่วยงานอิสระที่ประกอบด้วยแพทย์จากหลากหลายสาขาและศาสนา เพื่อตรวจสอบข้อเท็จจริงทางวิทยาศาสตร์ของปาฏิหาริย์ทุกกรณีอย่างเข้มงวด',
      'The Lourdes Medical Bureau rigorously investigates all reported cures under strict scientific criteria. Saint Bernadette was canonized in 1933, her incorrupt body displayed in Nevers.',
      'ห้ามนำน้ำศักดิ์สิทธิ์ไปจำหน่ายเชิงพาณิชย์ หรือส่งเสียงรบกวนผู้ป่วยในถ้ำ',
      'Water from the spring must never be sold commercially or treated disrespectfully.',
      'https://i.ytimg.com/vi/9wgEyEkclow/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/9wgEyEkclow/hqdefault.jpg","title":"ถ้ำศักดิ์สิทธิ์แห่งลูร์ดส์ (น้ำพุมหัศจรรย์รักษาโรคแห่งฝรั่งเศส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=9wgEyEkclow","title":"First Apparition of Our Lady of Lourdes","thumbnail":"https://i.ytimg.com/vi/9wgEyEkclow/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-carnac-stones-megaliths',
      'หินตั้งคาร์นัคแห่งบริตทานี (แนวหินดึกดำบรรพ์ 3,000 ก้อน)',
      'The Carnac Stones Megalithic Alignments (Brittany)',
      'sacred',
      'มอร์บีฮอง',
      'Morbihan',
      'คาร์นัค',
      'Carnac',
      47.5921,
      -3.0782,
      'creepy_wind',
      'ทุ่งหินตั้งขนาดยักษ์ยุคก่อนประวัติศาสตร์กว่า 3,000 ก้อน เรียงรายเป็นแถวยาวขนานกันกว่า 4 กิโลเมตร สร้างขึ้นตั้งแต่ช่วง 4,500 ปีก่อนคริสตกาล ซึ่งเก่าแก่กว่าสโตนเฮนจ์และพีระมิดอียิปต์ ตำนานพื้นบ้านบริตทานีเล่าว่า กองหินเหล่านี้คือทหารโรมันที่ไล่ล่าสังหารนักบุญคอร์เนลี ทว่านักบุญได้หันกลับมาเสกให้ทหารทั้งกองทัพกลายเป็นหินในพริบตา นักโบราณคดีเชื่อว่าเป็นศูนย์ประกอบพิธีกรรมทางดาราศาสตร์และพลังงานโลกโบราณ',
      'Dating back to 4500 BC, the Carnac alignments form the dense concentration of megalithic standing stones (menhirs) in the world, stretching over four kilometers across the Breton heath. Breton folklore maintains that Saint Cornely, pursued by a pagan Roman army, turned toward the coast and miraculously turned the legionnaires into stone rows. Modern researchers theorize they functioned as ancient astronomical calendars and telluric energy vectors.',
      'คาร์นัคเป็นหลักฐานสำคัญของวัฒนธรรมเมกะลิธิกยุคหินใหม่ในยุโรป หินบางก้อนมีน้ำหนักหลายสิบตัน และถูกจัดวางตามแนวการขึ้นลงของดวงอาทิตย์ในวันครีษมายัน',
      'Predating Stonehenge by over a thousand years, Carnac represents the zenith of Neolithic engineering. The complex includes tumuli, dolmens, and thousands of precisely aligned menhirs.',
      'ห้ามปีนป่าย ขีดเขียน หรือขูดเนื้อหินโบราณ',
      'Never climb, deface, or chip fragments off the prehistoric menhirs.',
      'https://i.ytimg.com/vi/o_i8PBQZBUE/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/o_i8PBQZBUE/hqdefault.jpg","title":"หินตั้งคาร์นัคแห่งบริตทานี (แนวหินดึกดำบรรพ์ 3,000 ก้อน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=o_i8PBQZBUE","title":"The mystery behind the megaliths of France’s Brittany region","thumbnail":"https://i.ytimg.com/vi/o_i8PBQZBUE/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-bear-butte-matopaha-sd',
      'แบร์บัตต์ มาโตปาฮา (ภูเขาทำพิธีวิสัยทัศน์ศักดิ์สิทธิ์ลาโคตา)',
      'Bear Butte (Mato Paha) Sacred Vision Quest Mountain',
      'sacred',
      'เซาท์ดาโคตา',
      'South Dakota',
      'สเตอร์จิส',
      'Sturgis',
      44.4758,
      -103.4283,
      'whisper',
      'ยอดเขาภูเขาไฟโบราณที่ตั้งตระหง่านโดดเดี่ยวเหนือที่ราบเกรตเพลนส์ มีรูปร่างคล้ายหมีตัวใหญ่นอนหมอบ ชนเผ่าพื้นเมืองอเมริกัน ทั้งลาโคตา ไชแอนน์ และอาราพาโฮ ถือว่า ''มาโตปาฮา'' เป็นภูเขาศักดิ์สิทธิ์ที่สุด ที่ซึ่งมหาเทพวาคันตันกาได้ประทานกฎบัญญัติและพิธีกรรมศักดิ์สิทธิ์ให้แก่มนุษย์ นักรบและผู้นำจิตวิญญาณ เช่น เครซีฮอร์ส และ ซิตติงบูลล์ ล้วนเคยขึ้นมาอดอาหารและทำพิธีค้นหานิมิต (Vision Quest) บนยอดเขานี้',
      'Rising abruptly from the South Dakota plains, Bear Butte (Mato Paha) resembles a sleeping bear. For the Lakota, Cheyenne, and other Plains tribes, this laccolith is their most sacred cathedral. Great chiefs including Crazy Horse, Sitting Bull, and Red Cloud climbed its crags to fast, pray, and receive divine visions (Hanblecheya). Thousands of colorful prayer cloths and tobacco bundles (cangleska) hang from pine branches along its trails.',
      'ปัจจุบันเป็นอุทยานแห่งรัฐแบร์บัตต์ แต่ยังคงได้รับการคุ้มครองในฐานะศาสนสถานตามกฎหมายเสรีภาพทางศาสนาของชนเผ่าพื้นเมืองอเมริกัน',
      'Protected under the American Indian Religious Freedom Act, visitors are instructed to respect ongoing ceremonies and never touch or disturb the sacred prayer cloths fluttering in the winds.',
      'ห้ามแตะต้อง แกะ หรือหยิบฉวยผ้าผูกคำอธิษฐานศักดิ์สิทธิ์บนต้นไม้เด็ดขาด',
      'Never touch, untie, or photograph sacred prayer cloths and tobacco offerings.',
      'https://i.ytimg.com/vi/7PLxB9gTd3I/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/7PLxB9gTd3I/hqdefault.jpg","title":"แบร์บัตต์ มาโตปาฮา (ภูเขาทำพิธีวิสัยทัศน์ศักดิ์สิทธิ์ลาโคตา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PLxB9gTd3I","title":"Bear Butte (1998) | From the Archives","thumbnail":"https://i.ytimg.com/vi/7PLxB9gTd3I/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-san-galgano-sword-stone',
      'ดาบในหินแห่งซานกัลกาโน (ดาบศักดิ์สิทธิ์ของจริงแห่งทัสกานี)',
      'The Sword in the Stone at Montesiepi Abbey (San Galgano)',
      'sacred',
      'เซียนา',
      'Siena',
      'คิวสดิโน',
      'Chiusdino',
      43.1539,
      11.1558,
      'temple_bell',
      'ในโบสถ์หินทรงกลมมองเตซีปีกลางแคว้นทัสกานี มีดาบเหล็กโบราณในศตวรรษที่ 12 ปักลึกเข้าไปในก้อนหินธรรมชาติจนโผล่มาเพียงด้ามจับและโคนดาบ ตำนานเล่าว่า กัลกาโน กุยดอตติ อัศวินผู้ดุร้ายได้พบเห็นนิมิตของอัครเทวทูตมีคาเอล เขาจึงกลับใจละทิ้งชีวิตนักรบและประกาศว่าจะสละดาบดั่งการปักดาบลงในหิน ทว่าเมื่อเขาแทงดาบลงไป หินแข็งกลับละลายและกลืนคมดาบเข้าไปทันที ดาบนี้กลายเป็นไม้กางเขนแห่งการภาวนาจนเขาเสียชีวิต',
      'Inside the Montesiepi Rotunda in Tuscany stands a real-life sword embedded deep into solid bedrock. In 1180, Galgano Guidotti, a ruthless knight, renounced war after visions of Archangel Michael. Proclaiming it would be as impossible to give up worldly violence as it would be to thrust a blade through bedrock, he plunged his broadsword into a boulder—and the stone yielded like butter. Metallurgical dating confirmed the iron sword genuinely dates to the 12th century.',
      'นักวิชาการหลายท่านเชื่อว่าตำนานของนักบุญกัลกาโนเป็นต้นกำเนิดดั้งเดิมของตำนาน ''ดาบในหิน'' ของกษัตริย์อาเธอร์ (Excalibur) ในวรรณกรรมอัศวินยุคกลางของยุโรป',
      'University of Pavia scientific testing verified the composition and age of the sword, validating Montesiepi as the probable historical catalyst for the Arthurian sword in the stone romance.',
      'ห้ามพยายามโยก ดึง หรือเคาะกระจกป้องกันดาบในหิน',
      'Never shake or tamper with the protective acrylic dome encasing the sword.',
      'https://i.ytimg.com/vi/0csfnR3V6lY/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/0csfnR3V6lY/hqdefault.jpg","title":"ดาบในหินแห่งซานกัลกาโน (ดาบศักดิ์สิทธิ์ของจริงแห่งทัสกานี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0csfnR3V6lY","title":"The truth behind the legend of the ''sword in the stone'' – BBC REEL","thumbnail":"https://i.ytimg.com/vi/0csfnR3V6lY/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-glastonbury-chalice-well',
      'บ่อน้ำจอกศักดิ์สิทธิ์แห่งกลาสตันเบอรี (น้ำพุสีแดงแห่งอวาลอน)',
      'Chalice Well & The Red Spring of Avalon',
      'sacred',
      'ซอเมอร์เซต',
      'Somerset',
      'กลาสตันเบอรี',
      'Glastonbury',
      51.1444,
      -2.7077,
      'water_spirit',
      'บ่อน้ำพุธรรมชาติโบราณที่ไหลรินไม่เคยเหือดแห้งที่เชิงเขากลาสตันเบอรีทอร์ น้ำในบ่อมีสีแดงเรื่อเนื่องจากอุดมด้วยแร่ธาตุเหล็ก ตำนานคริสเตียนและอาเธอร์เล่าว่า โจเซฟแห่งอาริมาเธีย ได้นำ ''จอกศักดิ์สิทธิ์'' (Holy Grail) ที่ใช้รองรับพระโลหิตของพระเยซูคริสต์มาซ่อนไว้ที่ก้นบ่อน้ำแห่งนี้ ทำให้น้ำมีพลังในการบำบัดรักษาและแฝงไปด้วยความสงบทางจิตวิญญาณ ถือเป็นหนึ่งในสถานที่แสวงบุญที่ศักดิ์สิทธิ์ที่สุดของเกาะอังกฤษ',
      'Nestled at the foot of Glastonbury Tor lies the Chalice Well, an ancient sacred spring that has flowed constantly for over two millennia. Legend recounts that Joseph of Arimathea hid the Holy Grail—the chalice containing drops of Christ''s blood—deep within the spring''s bedrock, giving the iron-rich waters their distinctive reddish hue and restorative healing properties. The site is sheltered within peaceful meditative gardens.',
      'ฝาครอบบ่อน้ำทำจากไม้โอ๊กและเหล็กดัดเป็นลวดลาย ''Vesica Piscis'' (วงกลมซ้อนสองวง) ซึ่งเป็นสัญลักษณ์เรขาคณิตศักดิ์สิทธิ์ของการผสานระหว่างโลกวัตถุและโลกวิญญาณ',
      'Surrounded by legends of King Arthur and Avalon, the well is maintained as a living peace sanctuary by the Chalice Well Trust, welcoming spiritual seekers from around the world.',
      'ห้ามส่งเสียงดังหรือทิ้งสิ่งแปลกปลอมลงในบ่อน้ำศักดิ์สิทธิ์',
      'Maintain silent contemplation and never throw foreign objects into the well.',
      'https://i.ytimg.com/vi/KZyw40sNDlw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/KZyw40sNDlw/hqdefault.jpg","title":"บ่อน้ำจอกศักดิ์สิทธิ์แห่งกลาสตันเบอรี (น้ำพุสีแดงแห่งอวาลอน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=KZyw40sNDlw","title":"Chalice Well: The Red Spring of Ancient Avalon - Megalithomania Tour with Peter Knight","thumbnail":"https://i.ytimg.com/vi/KZyw40sNDlw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-golden-temple-amritsar',
      'วิหารทองคำหริมันทิรสาหิบ (สระน้ำแห่งอมฤตแห่งอัมริตสาร์)',
      'Harmandir Sahib (The Golden Temple & Amrit Sarovar)',
      'sacred',
      'ปัญจาบ',
      'Punjab',
      'อัมริตสาร์',
      'Amritsar',
      31.62,
      74.8765,
      'temple_bell',
      'ศูนย์กลางจิตวิญญาณสูงสุดของชาวซิกข์ทั่วโลก พระวิหารหินอ่อนประดับทองคำแท้ส่องประกายสว่างไสวอยู่กลาง ''อมฤตสโรวร'' หรือสระน้ำศักดิ์สิทธิ์แห่งน้ำทิพย์ วิหารแห่งนี้ออกแบบให้มีทางเข้าทั้งสี่ทิศ เพื่อแสดงถึงการเปิดรับมนุษย์ทุกคนโดยไม่แบ่งแยกวรรณะ ศาสนา หรือเชื้อชาติ ภายในประดิษฐานคัมภีร์คุรุครันถสาหิบ ซึ่งมีนักบวชสวดทำนองเสนาะต่อเนื่องตลอด 24 ชั่วโมง พร้อมทั้งมีโรงครัวทาน (Langar) ที่เลี้ยงอาหารฟรีแก่ผู้มาเยือนนับแสนคนทุกวัน',
      'Harmandir Sahib, known universally as the Golden Temple, is the preeminent spiritual sanctum of Sikhism. Gleaming in real gold leaf in the center of the holy Amrit Sarovar (Pool of Nectar), the temple features four open entrances symbolizing total inclusivity for people of all faiths, castes, and origins. Inside, the Guru Granth Sahib is chanted continuously, while the temple''s langar serves free, nutritious vegetarian meals to over 100,000 visitors daily.',
      'สร้างขึ้นโดยคุรุอรชุน คุรุองค์ที่ 5 ในปี 1588 และได้รับการบูรณะหุ้มทองคำโดยมหาราชา รณชิต สิงห์ ในต้นศตวรรษที่ 19',
      'The Golden Temple represents one of humanity''s greatest monuments to selfless service, equality, and divine devotion, drawing more visitors than the Taj Mahal.',
      'ทุกคนต้องคลุมศีรษะ ถอดรองเท้า ล้างเท้า และห้ามพกพาเนื้อสัตว์ สุรา หรือบุหรี่',
      'Cover your head, remove shoes, wash feet, and abstain from alcohol or tobacco completely.',
      'https://i.ytimg.com/vi/MmRmqGIymWI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/MmRmqGIymWI/hqdefault.jpg","title":"วิหารทองคำหริมันทิรสาหิบ (สระน้ำแห่งอมฤตแห่งอัมริตสาร์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=MmRmqGIymWI","title":"The Golden Temple - Harmamdir Darbar Sahib Amritsar India - Documentary - by roothmens","thumbnail":"https://i.ytimg.com/vi/MmRmqGIymWI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-dambulla-cave-temple',
      'วัดถ้ำดัมบูลลา (วิหารพระพุทธรูปใต้เพดานทองคำศรีลังกา)',
      'Golden Temple of Dambulla Cave Monasteries',
      'sacred',
      'เซ็นทรัล',
      'Central Province',
      'ดัมบูลลา',
      'Dambulla',
      7.8567,
      80.6483,
      'temple_bell',
      'หมู่วัดถ้ำหินโบราณที่ใหญ่ที่สุดและได้รับการอนุรักษ์ไว้อย่างสมบูรณ์ที่สุดในศรีลังกา สร้างขึ้นตั้งแต่ศตวรรษที่ 1 ก่อนคริสตกาล ภายในถ้ำธรรมชาติทั้ง 5 ถ้ำ มีภาพจิตรกรรมฝาผนังพุทธประวัติและภาพสีทองครอบคลุมพื้นที่กว่า 2,100 ตารางเมตร ประดิษฐานพระพุทธรูปหินแกะสลักกว่า 157 องค์ รวมถึงพระพุทธรูปปางปรินิพพานขนาดยักษ์ยาว 14 เมตร ที่สลักจากหินผาก้อนเดียว บรรยากาศภายในถ้ำเงียบสงบและมีน้ำหยดศักดิ์สิทธิ์ที่ผุดขึ้นจากเพดานถ้ำตลอดปี',
      'Rising 160 meters above the plains, the Dambulla Cave Temple complex comprises five sanctuaries carved under a colossal overhanging granite rock. Dating back to the 1st century BC when King Valagamba sought refuge here, the caves contain over 2,100 square meters of breathtaking Buddhist frescoes and 157 exquisite statues, including a magnificent 14-meter reclining Buddha carved directly out of the living mountain rock.',
      'ได้รับการขึ้นทะเบียนเป็นมรดกโลกโดยยูเนสโกในปี 1991 ถือเป็นยอดผลงานชิ้นเอกของศิลปะและสถาปัตยกรรมทางพุทธศาสนาแบบสิงหลโบราณ',
      'A UNESCO World Heritage Site since 1991, Dambulla has served as an active Buddhist monastery for over 22 centuries without interruption.',
      'ห้ามยืนหันหลังให้พระพุทธรูปเพื่อถ่ายรูปเซลฟี่เด็ดขาด',
      'Never turn your back directly on Buddha statues when posing for photographs.',
      'https://i.ytimg.com/vi/hcQSafppXAM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/hcQSafppXAM/hqdefault.jpg","title":"วัดถ้ำดัมบูลลา (วิหารพระพุทธรูปใต้เพดานทองคำศรีลังกา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=hcQSafppXAM","title":"Dambulle Cave temple |Documentary|Sri Lanka | EP 01","thumbnail":"https://i.ytimg.com/vi/hcQSafppXAM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-wat-phra-that-doi-leng-phrae',
      'วัดพระธาตุดอยเล็ง (พระธาตุยอดดอยสูงสุดแห่งเมืองแพร่)',
      'Wat Phra That Doi Leng High Mountain Stupa (Phrae)',
      'sacred',
      'แพร่',
      'Phrae',
      'เมืองแพร่',
      'Mueang Phrae',
      18.0931,
      100.2244,
      'temple_bell',
      'พระธาตุศักดิ์สิทธิ์ที่ตั้งอยู่บนยอดดอยสูงที่สุดในแนวเทือกเขาฝั่งตะวันออกของเมืองแพร่ ตำนานเล่าว่าเมื่อองค์สมเด็จพระสัมมาสัมพุทธเจ้าเสด็จมาประทับที่ดอยโกสิยธชัคคะ ได้เสด็จขึ้นมาบนยอดดอยแห่งนี้เพื่อทอดพระเนตร (เล็ง) ทัศนียภาพของผืนแผ่นดินเมืองแพร่ จึงได้ชื่อว่า ''ดอยเล็ง'' พระธาตุสีขาวบริสุทธิ์ยอดฉัตรทองคำตั้งตระหง่านอยู่บนจุดสูงสุด เป็นจุดที่ผู้แสวงบุญสามารถมองเห็นทิวทัศน์เมืองแพร่และวัดพระธาตุช่อแฮได้พร้อมกัน',
      'Perched upon the highest mountain crest in the eastern range of Phrae, Wat Phra That Doi Leng shares ancient ties with Wat Phra That Cho Hae. According to local lore, when the Buddha visited the region, he climbed to this summit to gaze out (''Leng'') over the fertile valley and bless its future inhabitants. Devotees climb the winding mountain road to pay homage to the white stupa and meditate over panoramic views.',
      'เป็นหนึ่งในสามพระธาตุสำคัญในตำนานพระพุทธเจ้าเล็งเมืองของจังหวัดแพร่ ประกอบด้วย พระธาตุช่อแฮ พระธาตุจอมแจ้ง และพระธาตุดอยเล็ง',
      'Part of the legendary sacred triad of Phrae pagodas, Doi Leng offers quiet contemplation away from bustling city centers, deep in forested mountain tranquility.',
      'ห้ามทิ้งขยะหรือสร้างความเสื่อมเสียบนลานชมทัศนียภาพยอดดอย',
      'Preserve the mountain purity and avoid littering along the meditation ridge.',
      'https://i.ytimg.com/vi/A8UshEInSPc/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/A8UshEInSPc/hqdefault.jpg","title":"วัดพระธาตุดอยเล็ง (พระธาตุยอดดอยสูงสุดแห่งเมืองแพร่)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=A8UshEInSPc","title":"ยักษ์สื่อวิญญาณ Ep.52 Unseen พระธาตุดอยเล็ง","thumbnail":"https://i.ytimg.com/vi/A8UshEInSPc/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-borobudur-stupa-mandala',
      'บุโรพุทโธ (มหาพุทธมณฑลหินภูเขาไฟแห่งชวา)',
      'Borobudur Temple & The Great Stone Mandala (Java)',
      'sacred',
      'ชวากลาง',
      'Central Java',
      'มาเกอลัง',
      'Magelang',
      -7.6079,
      110.2038,
      'temple_bell',
      'พุทธศาสนสถานมหายานที่ใหญ่ที่สุดในโลก สร้างขึ้นในศตวรรษที่ 9 จากบล็อกหินแอนดีไซต์ภูเขาไฟกว่า 2 ล้านก้อน ออกแบบเป็นมณฑลจักรวาล (Mandala) 9 ชั้น ชั้นล่างแสดงภาพแกะสลักเรื่องกามภูมิ (กิเลสและบาป) ชั้นกลางแสดงรูปภูมิ (ชาดกและพุทธประวัติ) และสามชั้นบนสุดเป็นลานวงกลมที่มีสถูปเจาะโปร่ง 72 องค์ ประดิษฐานพระพุทธรูปอยู่ภายใน มุ่งสู่สถูปประธานสูงสุดอันว่างเปล่า สื่อถึงนิพพานอันหลุดพ้นจากสังสารวัฏ',
      'Borobudur is the largest Buddhist monument in the world, erected in the 9th century during the Sailendra Dynasty. Crafted from two million volcanic andesite stone blocks without mortar, its architecture forms a massive step-pyramid three-dimensional mandala. Pilgrims walk circumambulatory paths past 2,672 bas-relief panels and 504 Buddha statues, climbing through realms of desire and form toward the summit stupa representing Nirvana.',
      'บุโรพุทโธถูกทิ้งร้างและจมอยู่ใต้เถ้าถ่านภูเขาไฟเมราปีและป่าดงดิบนานหลายศตวรรษ ก่อนจะถูกค้นพบใหม่โดย เซอร์ โทมัส สแตมฟอร์ด แรฟเฟิลส์ ในปี 1814',
      'Buried for centuries beneath volcanic ash until its rediscovery in 1814, Borobudur is now a UNESCO World Heritage Site and the focal center for Vesak celebrations in Indonesia.',
      'ห้ามปีนป่ายหรือนั่งทับบนเจดีย์ระฆังโปร่ง (Stupas)',
      'Never climb, sit upon, or lean over the perforated bell-shaped stupas.',
      'https://i.ytimg.com/vi/AFp627-DYEI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/AFp627-DYEI/hqdefault.jpg","title":"บุโรพุทโธ (มหาพุทธมณฑลหินภูเขาไฟแห่งชวา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=AFp627-DYEI","title":"BOROBUDUR: The Lost Buddhist Kingdom of Java | World’s Largest Temple Explained","thumbnail":"https://i.ytimg.com/vi/AFp627-DYEI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-meteora-monasteries-greece',
      'อารามลอยฟ้าแห่งเมเตโอรา (อารามนักพรตบนยอดเสาหินกรีซ)',
      'The Monasteries of Meteora Suspended in the Air',
      'sacred',
      'เทสซาลี',
      'Thessaly',
      'คาลาบากา',
      'Kalabaka',
      39.7217,
      21.6306,
      'temple_bell',
      'กลุ่มเสาหินทรายธรรมชาติขนาดยักษ์สูงชันกว่า 400 เมตรที่พุ่งเสียดฟ้าขึ้นจากที่ราบเทสซาลี ในศตวรรษที่ 14 นักบวชคริสต์นิกายอีสเทิร์นออร์โธด็อกซ์ได้ขึ้นไปสร้างอารามบนยอดเสาหินที่ตัดขาดจากโลกภายนอก โดยในอดีตต้องใช้บันไดเชือกและตาข่ายรอกชักลากขึ้นไปเท่านั้น เพื่อแสวงหาความสงบและการภาวนาอย่างใกล้ชิดกับพระเจ้า อารามทั้ง 6 แห่งที่ยังคงเปิดใช้งานเก็บรักษาภาพจิตรกรรมฝาผนังไบแซนไทน์และพระคัมภีร์ล้ำค่า',
      'Meteora, meaning ''suspended in the air'' in Greek, is a complex of Eastern Orthodox monasteries built atop soaring natural sandstone monoliths. Beginning in the 14th century, hermit monks fled invading Ottoman forces, scaling dizzying vertical cliffs to construct cloisters reachable only by collapsible rope ladders and net pulleys. Today, six active monasteries preserve centuries of Byzantine iconography and silent prayer above the mist.',
      'เมเตโอราได้รับการขึ้นทะเบียนเป็นมรดกโลกทั้งทางธรรมชาติและวัฒนธรรมโดยยูเนสโก และเคยปรากฏในภาพยนตร์เจมส์ บอนด์ ตอน For Your Eyes Only',
      'A dual UNESCO site for both cultural and geological significance, Meteora remains one of the Eastern Orthodox world''s most dramatic testaments to ascetic faith.',
      'ผู้หญิงต้องสวมกระโปรงยาวคลุมเข่า และผู้ชายต้องสวมกางเกงขายาวเรียบร้อย',
      'Strict modesty dress code is enforced: women must wear long skirts and men long trousers.',
      'https://i.ytimg.com/vi/UEGmCPPZNMw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/UEGmCPPZNMw/hqdefault.jpg","title":"อารามลอยฟ้าแห่งเมเตโอรา (อารามนักพรตบนยอดเสาหินกรีซ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=UEGmCPPZNMw","title":"Meteora: Monasteries Suspended in the Sky | Greece","thumbnail":"https://i.ytimg.com/vi/UEGmCPPZNMw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-mount-athos-holy-mountain',
      'ภูเขาศักดิ์สิทธิ์อะโธส (ดินแดนสาธารณรัฐนักบวชพันปี)',
      'Mount Athos Holy Mountain & Monastic Republic',
      'sacred',
      'คัลคิดิกี',
      'Chalkidiki',
      'อะโธส',
      'Mount Athos',
      40.1574,
      24.3289,
      'temple_bell',
      'คาบสมุทรภูเขาศักดิ์สิทธิ์ที่ปกครองตนเองในฐานะสาธารณรัฐนักบวชออร์โธด็อกซ์ มีอารามป้อมปราการโบราณ 20 แห่งสืบทอดชีวิตทางจิตวิญญาณมานานกว่า 1,000 ปี ดินแดนแห่งนี้ถือเป็น ''สวนของพระแม่มารีย์'' โดยมีกฎเหล็กโบราณ ''อาวาตอน'' (Avaton) บังคับใช้มาตั้งแต่ปี 1046 ห้ามสตรีและสัตว์เพศเมียก้าวล่วงเข้าสู่แผ่นดินนี้โดยเด็ดขาด นักบวชที่นี่ดำเนินชีวิตด้วยการสวดภาวนา ทำงานหัตถกรรม และปฏิเสธเทคโนโลยีสมัยใหม่',
      'Mount Athos is an autonomous monastic state occupying an eastern peninsula of Chalkidiki, home to 20 historic Eastern Orthodox monasteries. Revered as the ''Garden of the Virgin Mary'', Athos has strictly enforced the ancient law of ''Avaton'' since 1046 AD, barring women and female domestic animals to preserve absolute monastic celibacy and spiritual devotion. Monks adhere to the Byzantine clock and Julian calendar in unbroken ascetic worship.',
      'ภูเขาอะโธสเป็นมรดกโลกยูเนสโก การเดินทางเข้าสู่พื้นที่ต้องได้รับใบอนุญาตพิเศษ (Diamonitirion) และจำกัดจำนวนผู้แสวงบุญชายเพียงวันละไม่กี่คนเท่านั้น',
      'Athos preserves the world''s most pristine living archive of Byzantine culture, manuscripts, and spiritual hesychasm meditation techniques.',
      'ห้ามสตรีเดินทางเข้าสู่เขตภูเขาอะโธสโดยเด็ดขาดตามกฎอาวาตอน',
      'Women are strictly prohibited from entering Mount Athos territory under the Avaton law.',
      'https://i.ytimg.com/vi/gR78swqMz6Y/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/gR78swqMz6Y/hqdefault.jpg","title":"ภูเขาศักดิ์สิทธิ์อะโธส (ดินแดนสาธารณรัฐนักบวชพันปี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=gR78swqMz6Y","title":"Mount Athos | 60 Minutes Archive","thumbnail":"https://i.ytimg.com/vi/gR78swqMz6Y/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-phra-dhammakaya-stupa',
      'มหาธรรมกายเจดีย์ (เจดีย์พระพุทธเจ้าล้านพระองค์ปทุมธานี)',
      'Dhammakaya Cetiya & Million Golden Buddha Dome',
      'sacred',
      'ปทุมธานี',
      'Pathum Thani',
      'คลองหลวง',
      'Khlong Luang',
      14.0708,
      100.6508,
      'temple_bell',
      'มหาเจดีย์ทรงโดมกลมครึ่งวงกลมขนาดมหึมา ออกแบบตามหลักสถาปัตยกรรมสถูปสาญจีโบราณ บนโดมภายนอกประดิษฐานพระพุทธรูปทองคำแท้ขนาดหน้าตัก 1 ศอก จำนวน 300,000 องค์ และภายในบรรจุพระพุทธรูปอีก 700,000 องค์ รวมเป็นหนึ่งล้านพระองค์ ลานธรรมโดยรอบสามารถรองรับผู้มาปฏิบัติธรรมได้กว่า 1 ล้านคน ในวันสำคัญทางพุทธศาสนาจะมีการจุดประทีปโคมเอกหลายแสนดวงสว่างไสวเต็มลานบุญดั่งทะเลดาวเพื่อแผ่เมตตาจิตสู่สันติภาพโลก',
      'Dhammakaya Cetiya is a colossal hemispherical stupa inspired by ancient Sanchi architecture. The dome is clad with 300,000 silicon-bronze Buddha statues coated in pure gold on its exterior, with another 700,000 enshrined within its inner chamber. Surrounded by a meditation amphitheater capable of seating one million pilgrims, the shrine becomes a radiant ocean of light during holy day ceremonies when hundreds of thousands of lanterns are lit in unison for world peace.',
      'สร้างขึ้นด้วยคอนกรีตเสริมเหล็กพิเศษที่ออกแบบให้อายุการใช้งานยาวนานนับพันปี เป็นศูนย์กลางของขบวนการปฏิบัติสมาธิวิชชาธรรมกาย',
      'Constructed with advanced materials engineered to endure for a millennium, the cetiya serves as the global nerve center for the Dhammakaya meditation movement.',
      'ผู้เข้าร่วมต้องแต่งกายด้วยชุดสีขาวสุภาพเรียบร้อยและสำรวมกายวาจา',
      'Wear modest all-white attire and maintain meditative decorum within the plaza.',
      'https://i.ytimg.com/vi/kd_nUuH5Hpo/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/kd_nUuH5Hpo/hqdefault.jpg","title":"มหาธรรมกายเจดีย์ (เจดีย์พระพุทธเจ้าล้านพระองค์ปทุมธานี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=kd_nUuH5Hpo","title":"จุดประทีปแปรอักษร ที่ใหญ่ที่สุดในโลก วันคุ้มครองโลก วัดพระธรรมกาย","thumbnail":"https://i.ytimg.com/vi/kd_nUuH5Hpo/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-wat-tham-pha-daen-sakon-nakhon',
      'วัดถ้ำผาแด่น (พุทธสถานหินทรายแกะสลักเทือกเขาภูพาน)',
      'Wat Tham Pha Daen Sacred Mountain Sanctuaries',
      'sacred',
      'สกลนคร',
      'Sakon Nakhon',
      'เมืองสกลนคร',
      'Mueang Sakon Nakhon',
      17.0624,
      104.1481,
      'temple_bell',
      'วัดโบราณเก่าแก่กว่า 100 ปี ซ่อนตัวอยู่บนเทือกเขาภูพาน ในอดีตเคยเป็นสถานที่ปฏิบัติธรรมวิปัสสนาของพระเกจิอาจารย์สายหลวงปู่มั่น ภูริทัตโต โดดเด่นด้วยงานประติมากรรมแกะสลักหินทรายธรรมชาติขนาดยักษ์ เช่น ภาพพระพุทธชัยมงคลมหาชนก ภาพพุทธประวัติ รอยพระพุทธบาทจำลอง และภาพพญาอนันตนาคราชเลื้อยโอบล้อมหน้าผาหิน ท่ามกลางสวนไม้ดอกเมืองหนาวและทัศนียภาพกว้างไกลของทะเลสาบหนองหาร',
      'Nestled high in the Phu Phan mountains of Sakon Nakhon, Wat Tham Pha Daen was once a remote forest hermitage where revered meditation masters like Luang Pu Man Phuritatto practiced austerities. The temple is celebrated for its massive sandstone cliff sculptures, including monumental depictions of Buddha''s life, sacred footprints, and a breathtaking serpent dragon (Naga) wrapping around towering granite boulders amidst flowering botanical gardens.',
      'เดิมเป็นวัดร้างกลางป่าลึก ก่อนจะได้รับการบูรณะและพัฒนาภูมิทัศน์ให้กลายเป็นพุทธศิลป์หินทรายที่วิจิตรตระการตาและเป็นจุดแสวงบุญสำคัญของภาคอีสาน',
      'Transforming natural geological stone formations into devotional artwork, the temple provides pilgrims with meditative panoramic vistas overlooking the vast Nong Han Lake basin.',
      'ห้ามปีนป่ายหรือสัมผัสรอยแกะสลักบนประติมากรรมหินทราย',
      'Never climb or deface the hand-carved cliffside rock sculptures.',
      'https://i.ytimg.com/vi/HCSaXHwHhG4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/HCSaXHwHhG4/hqdefault.jpg","title":"วัดถ้ำผาแด่น (พุทธสถานหินทรายแกะสลักเทือกเขาภูพาน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=HCSaXHwHhG4","title":"วัดถ้ำผาแด่น อลังการงานพุทธศิลป์ถิ่นภูพาน | สัมผัสความงามจากศรัทธาอันน่ามหัศจรรย์แห่งสกลนคร","thumbnail":"https://i.ytimg.com/vi/HCSaXHwHhG4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-san-ctuario-las-lajas-colombia',
      'วิหารลาสลาฮาส (มหาวิหารศักดิ์สิทธิ์บนสะพานข้ามหุบเหวโคลอมเบีย)',
      'Las Lajas Sanctuary Church on the Canyon Bridge',
      'sacred',
      'นาริญโญ',
      'Narino',
      'อิเปียเลส',
      'Ipiales',
      0.8053,
      -77.5861,
      'temple_bell',
      'มหาวิหารสไตล์นีโอโกธิกอันน่าตระการตา สร้างขึ้นคร่อมข้ามหุบเหวลึก 100 เมตรเหนือแม่น้ำกวยตารา ในปี 1754 หญิงชาวพื้นเมืองและบุตรสาวที่เป็นใบ้ได้หลบพายุในถ้ำผา ทันใดนั้นลูกสาวได้มองเห็นภาพพระแม่มารีย์บนผนังหินและพูดออกมาเป็นครั้งแรกในชีวิต หลังจากนั้นมีผู้แสวงบุญได้รับการรักษาโรคจนหายมากมาย แท่นบูชาของโบสถ์สร้างแนบสนิทกับหน้าผาหินธรรมชาติ ซึ่งภาพพระแม่มารีย์ยังคงปรากฏอยู่บนเนื้อหินโดยไม่มีใครวาด',
      'Built directly across a dramatic 330-foot-deep gorge over the Guáitara River, the Sanctuary of Las Lajas is an architectural marvel. In 1754, an indigenous mother and her deaf-mute daughter were caught in a violent storm when the child miraculously saw an apparition of the Virgin Mary on the canyon rocks and spoke for the first time. The Neo-Gothic cathedral was engineered so the natural rock face bearing the mysterious Marian image serves as the church''s high altar.',
      'ธรณีวิทยาพิสูจน์แล้วว่าภาพพระแม่บนผนังหินลึกเข้าไปในเนื้อหินจริงโดยไม่มีสีสังเคราะห์ วิหารได้รับการยกย่องจาก The Daily Telegraph ให้เป็นโบสถ์ที่งดงามที่สุดในโลก',
      'Geological examinations showed the pigment is part of the rock itself rather than painted on the surface. It is Colombia''s most famous and visited Roman Catholic pilgrimage destination.',
      'ห้ามขีดเขียนชื่อลงบนสะพานหินหรือผนังถ้ำศักดิ์สิทธิ์',
      'Never carve names or deface the canyon stone bridge ramparts.',
      'https://i.ytimg.com/vi/uxe_zEAlIZA/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/uxe_zEAlIZA/hqdefault.jpg","title":"วิหารลาสลาฮาส (มหาวิหารศักดิ์สิทธิ์บนสะพานข้ามหุบเหวโคลอมเบีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=uxe_zEAlIZA","title":"Scientists Can''t Explain This Miracle in the Americas","thumbnail":"https://i.ytimg.com/vi/uxe_zEAlIZA/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-sacred-roque-bentayga-guanche',
      'โรเก เบนไตกา (แท่นบูชาสุริยเทพชาวกวนเชแห่งแกรนคานาเรีย)',
      'Roque Bentayga Sacred Guanche Altar (Gran Canaria)',
      'sacred',
      'ลัสปัลมัส',
      'Las Palmas',
      'เตเฆดา',
      'Tejeda',
      27.9501,
      -15.6268,
      'creepy_wind',
      'แท่งหินบะซอลต์ภูเขาไฟรูปทรงแปลกตาที่ตั้งตระหง่านอยู่ใจกลางปล่องภูเขาไฟโบราณเตเฆดา ชนเผ่ากวนเช (Guanche) ชนพื้นเมืองดั้งเดิมของหมู่เกาะคานารี ถือว่ายอดหินนี้เป็น ''อัลโมกอเรน'' (Almogarén) หรือแท่นบูชาศักดิ์สิทธิ์กลางแจ้ง บนยอดหินมีการสลักแอ่งหินและร่องทางน้ำเพื่อประกอบพิธีกรรมสังเวยนมและเนยแด่สุริยเทพ เมื่อถึงวันศารทวิษุวัตและวสันตวิษุวัต เงาของร่องหินจะชี้ไปยังตำแหน่งพระอาทิตย์ขึ้นอย่างแม่นยำ',
      'Roque Bentayga is a dramatic volcanic monolith rising 1,414 meters in the heart of Gran Canaria''s volcanic caldera. For the pre-Hispanic Guanche people, it was their primary ''almogarén''—a sacred celestial mountaintop sanctuary. Guanche priests carved ritual basins, channels, and circular enclosures into the rock to offer libations of milk and butter to their supreme deity, Magec. The complex aligns precisely with equinox sunrises.',
      'โรเก เบนไตกา เป็นปราการธรรมชาติแห่งสุดท้ายที่นักรบชาวกวนเชใช้ต่อสู้กับกองทัพสเปนในปี 1483 ปัจจุบันเป็นส่วนหนึ่งของพื้นที่มรดกโลกยูเนสโก ''Risco Caído and the Sacred Mountains of Gran Canaria''',
      'The fortress witnessed the heroic last stand of the indigenous Canarians during the Spanish conquest. It was inscribed as a UNESCO World Heritage Site in 2019.',
      'ห้ามเคลื่อนย้ายหินหรือเหยียบย่ำลงในแอ่งบูชายัญโบราณบนยอดเขา',
      'Never walk inside the ancient circular ritual libation basins.',
      'https://i.ytimg.com/vi/t8SpjVxzfUw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/t8SpjVxzfUw/hqdefault.jpg","title":"โรเก เบนไตกา (แท่นบูชาสุริยเทพชาวกวนเชแห่งแกรนคานาเรีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=t8SpjVxzfUw","title":"The most sacred site in Gran Canaria - Roque Bentayga!","thumbnail":"https://i.ytimg.com/vi/t8SpjVxzfUw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-kinnaree-manorah-krairat',
      'ตำนานกินรีมโนราห์แห่งสระอโนดาต (ป่าหิมพานต์แดนใต้)',
      'Kinnaree Manorah & The Sacred Krairat Forest',
      'legend',
      'สุราษฎร์ธานี',
      'Surat Thani',
      'พนม',
      'Phanom',
      8.8775,
      98.8105,
      'water_spirit',
      'มหากาพย์วรรณกรรมและนาฏศิลป์พื้นบ้านภาคใต้ของไทย เล่าถึงพระธิดากินรีทั้งเจ็ดตนแห่งเขาไกรลาส ผู้มีร่างท่อนบนเป็นมนุษย์และท่อนล่างเป็นนก บินลงมาเล่นน้ำ ณ สระโบกขรณีในป่าหิมพานต์ พรานบุญได้ใช้บ่วงนาคบาศจับนางมโนราห์ ธิดาองค์สุดท้อง ไปถวายแด่พระสุธน จนเกิดเป็นเรื่องราวความรัก การพลัดพราก และการร่ายรำบูชายัญหนีเพลิงไฟเพื่อบินกลับคืนสู่บ้านเกิด กลายเป็นต้นกำเนิดของศิลปะการร่ายรำโนราอันศักดิ์สิทธิ์ของชาวใต้',
      'One of Thailand''s most beloved mythic romances, the epic of Manorah tells of the seven Kinnaree princesses—half-human, half-swan celestial maidens who fly down from Mount Krairat to bathe in the mythical lotus lake of the Himavanta forest. Captured with a magical serpent noose by the hunter Bun, Manorah marries Prince Suthon but is sentenced to be sacrificed in fire by an evil minister, escaping into the clouds through her enchanted swan dance.',
      'มโนราห์หรือ ''โนรา'' ได้รับการขึ้นทะเบียนเป็นมรดกภูมิปัญญาทางวัฒนธรรมที่จับต้องไม่ได้ของมนุษยชาติโดยยูเนสโก (UNESCO) ในปี 2021 ถือเป็นมรดกทางศิลปวัฒนธรรมที่มีชีวิตของภาคใต้',
      'Inscribed on UNESCO''s Intangible Cultural Heritage list in 2021, the Nora dance drama embodies ancient spiritual animism, ancestral veneration, and classical Southeast Asian theatrical performance.',
      'ห้ามข้ามชุดเทริดมโนราห์ หรือแสดงกิริยาลบหลู่ต่อครูหมอโนรา',
      'Never step over or disrespect the sacred Nora headdress (Therd) and ancestral altars.',
      'https://i.ytimg.com/vi/NJr6FwRXr5E/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/NJr6FwRXr5E/hqdefault.jpg","title":"ตำนานกินรีมโนราห์แห่งสระอโนดาต (ป่าหิมพานต์แดนใต้)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=NJr6FwRXr5E","title":"เล่าเรื่อง พระสุธน มโนราห์ | Point of View Kids","thumbnail":"https://i.ytimg.com/vi/NJr6FwRXr5E/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-tham-luang-nang-non-chiang-rai',
      'ตำนานเจ้าหญิงนิทราแห่งถ้ำหลวงนางนอน (เชียงราย)',
      'The Legend of the Sleeping Lady of Tham Luang Nang Non',
      'legend',
      'เชียงราย',
      'Chiang Rai',
      'แม่สาย',
      'Mae Sai',
      20.3842,
      99.8672,
      'jungle_curse',
      'เทือกเขาดอยนางนอนที่มีรูปร่างคล้ายหญิงสาวนอนสยายผมอย่างสงบ มีตำนานเล่าถึงเจ้าหญิงแห่งเมืองเชียงรุ้งผู้ตกหลุมรักชายเลี้ยงม้าต่ำศักดิ์ ทั้งสองพากันหนีตามมาจนถึงเทือกเขาแห่งนี้ ขณะที่ชายคนรักออกไปหาอาหาร ทหารของพระราชบิดาได้ตามมาสังหารเขา เมื่อเจ้าหญิงทราบข่าว จึงใช้ปิ่นปักผมแทงพระศอปลงพระชนม์ชีพตามคนรัก เลือดของพระองค์กลายเป็นลำน้ำแม่สาย และเรือนร่างกลายเป็นเทือกเขานางนอน โดยมีถ้ำหลวงเป็นส่วนหนึ่งของสรีระ',
      'Doi Nang Non is a dramatic limestone mountain range resembling a reclining maiden with long flowing hair. Northern Thai folklore recounts the tragic romance of a Chiang Rung princess who eloped with a humble stablehand. When royal guards tracked down and executed her lover, the pregnant princess took her own life with her hairpin. Her body turned into the mountain range, her blood formed the Mae Sai River, and Tham Luang cave represents her womb.',
      'ถ้ำหลวง-ขุนน้ำนางนอนมีชื่อเสียงไปทั่วโลกจากปฏิบัติการกู้ภัยครั้งประวัติศาสตร์ช่วยเหลือนักฟุตบอลเยาวชนทีมหมูป่าอะคาเดมี 13 ชีวิตในปี 2018 ปัจจุบันได้รับการพัฒนาเป็นอุทยานแห่งชาติ',
      'Globally renowned for the miraculous 2018 Tham Luang cave rescue operation, local residents retain a deep spiritual reverence for Jao Mae Nang Non, making offerings before entering the caves.',
      'ห้ามเข้าถ้ำหลวงในฤดูน้ำหลาก และห้ามส่งเสียงก่นด่าหรือลบหลู่เจ้าแม่นางนอน',
      'Never enter Tham Luang during monsoon season or utter disrespectful profanities within the cavern.',
      'https://i.ytimg.com/vi/UYANfe7O1ZM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/UYANfe7O1ZM/hqdefault.jpg","title":"ตำนานเจ้าหญิงนิทราแห่งถ้ำหลวงนางนอน (เชียงราย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=UYANfe7O1ZM","title":"ความลับใต้ดอยนางนอน! เจาะลึกถ้ำหลวง 300 ล้านปี และห้องโถงลับใต้ภูเขาที่ไม่มีในแผนที่","thumbnail":"https://i.ytimg.com/vi/UYANfe7O1ZM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-phra-luang-pho-sothon-floating',
      'หลวงพ่อโสธรลอยน้ำ (ตำนานพระพุทธรูปลอยทวนกระแสน้ำแปดริ้ว)',
      'The Three Floating Brothers Buddha Legend (Chachoengsao)',
      'legend',
      'ฉะเชิงเทรา',
      'Chachoengsao',
      'เมืองฉะเชิงเทรา',
      'Mueang Chachoengsao',
      13.6738,
      101.0671,
      'temple_bell',
      'ตำนานมหัศจรรย์ของพระพุทธรูปพี่น้องสามองค์ (หลวงพ่อบ้านแหลม หลวงพ่อโตบางพลี และหลวงพ่อโสธร) ที่ลอยล่องทวนกระแสน้ำในแม่น้ำบางปะกงมาจนถึงท่าน้ำวัดหงษ์ (วัดโสธรวรารามวรวิหาร) ชาวบ้านนับร้อยคนพยายามช่วยกันใช้เชือกผูกชักลากขึ้นฝั่งแต่ไม่สำเร็จ จนกระทั่งมีพราหมณ์ผู้รู้มาตั้งศาลเพียงตาและใช้ด้ายสายสิญจน์ผูกคล้องพระหัตถ์ อัญเชิญขึ้นมาประดิษฐานได้อย่างง่ายดาย เชื่อกันว่าเป็นพระพุทธรูปศักดิ์สิทธิ์ที่ประทานพรให้ค้าขายร่ำรวยและรักษาโรค',
      'One of Thailand''s most celebrated sacred legends tells of three bronze Buddha statues miraculously floating upstream along the Bang Pakong River. While hundreds of villagers failed to pull the heavy statues ashore with thick ropes, a pious elder set up a small ritual altar and cast a single blessed cotton thread around the Buddha''s wrist, lifting the magnificent icon effortlessly onto the bank of Wat Sothon.',
      'วัดโสธรวรารามวรวิหารเป็นพระอารามหลวงชั้นตรี พระอุโบสถหินอ่อนหลังใหม่ที่สร้างขึ้นเป็นหนึ่งในโบสถ์ที่มีขนาดใหญ่และวิจิตรอลังการที่สุดในเอเชียตะวันออกเฉียงใต้',
      'Wat Sothon is one of the most visited pilgrimage sites in Thailand, drawing millions seeking blessings for prosperity, fertility, and protection, famously offering boiled eggs in thanksgiving.',
      'ห้ามบนบานขอไม่ให้ต้องไปเป็นทหารเกณฑ์กับหลวงพ่อโสธร (เชื่อว่าจะได้เป็นทันที)',
      'According to tradition, never pray to Luang Pho Sothon to avoid military conscription.',
      'https://i.ytimg.com/vi/SAkYXz9MgJs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/SAkYXz9MgJs/hqdefault.jpg","title":"หลวงพ่อโสธรลอยน้ำ (ตำนานพระพุทธรูปลอยทวนกระแสน้ำแปดริ้ว)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=SAkYXz9MgJs","title":"ตำนานความอัศจรรย์ พระพุทธรูปลอยน้ำ 5 พี่น้อง | ร้อยเรื่องราว","thumbnail":"https://i.ytimg.com/vi/SAkYXz9MgJs/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-bannerman-castle-hudson',
      'ปราสาทคลังอาวุธแบนเนอร์แมนแห่งเกาะโพลเลเปล',
      'The Arsenal Fortress of Bannerman Castle on Pollepel Island',
      'legend',
      'นิวยอร์ก',
      'New York',
      'ฟิชคิลล์',
      'Fishkill',
      41.4539,
      -73.9882,
      'creepy_wind',
      'ปราสาทสไตล์สกอตบารอนเนียลที่ตั้งตระหง่านอยู่บนเกาะกลางแม่น้ำฮัดสัน สร้างโดย แฟรงซิส แบนเนอร์แมน พ่อค้าสรรพาวุธสงครามชาวสก็อต เพื่อใช้เป็นคลังเก็บดินปืน ปืนใหญ่ และอาวุธทหารที่ซื้อมาจากสงครามกลางเมืองสหรัฐฯ และสงครามสเปน-อเมริกา ทว่าชนเผ่าพื้นเมืองเล่าว่าเกาะแห่งนี้เป็นแดนต้องห้ามของวิญญาณ ในปี 1920 คลังดินปืนเกิดระเบิดอย่างรุนแรงจนสะเทือนไปทั่วแม่น้ำ ตามด้วยเหตุเพลิงไหม้ครั้งใหญ่ในปี 1969 จนปราสาทกลายเป็นซากปรักหักพังอันน่าขนลุก',
      'Rising from a rocky islet in the Hudson River, Bannerman Castle was constructed in 1901 by Scottish military surplus dealer Francis Bannerman VI as a colossal mock-castle warehouse for artillery, ammunition, and captured weaponry. Local Native American lore considered Pollepel Island possessed by mischievous spirits. Tragedy struck in 1920 when 200 pounds of powder exploded, followed by a ruinous 1969 fire that left the castle a haunting Gothic husk.',
      'ปัจจุบันเกาะโพลเลเปลได้รับการดูแลโดยมูลนิธิ Bannerman Castle Trust ซึ่งจัดทัวร์ทางเรือเพื่อการอนุรักษ์ประวัติศาสตร์และสถาปัตยกรรมกลางแม่น้ำฮัดสัน',
      'The dramatic stone ruins remain one of the Hudson River''s most striking landmarks, featured in historical mysteries and haunted waterway tours.',
      'ห้ามขึ้นเกาะโพลเลเปลโดยไม่ได้รับอนุญาตเนื่องจากความไม่ปลอดภัยของโครงสร้างหิน',
      'Never dock private boats or climb the unstable ruined ramparts without guided authorization.',
      'https://i.ytimg.com/vi/zetJILSLJDI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/zetJILSLJDI/hqdefault.jpg","title":"ปราสาทคลังอาวุธแบนเนอร์แมนแห่งเกาะโพลเลเปล"},{"type":"youtube","url":"https://www.youtube.com/watch?v=zetJILSLJDI","title":"American Ruins: Bannerman''s Castle","thumbnail":"https://i.ytimg.com/vi/zetJILSLJDI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-lake-baikal-shamanka-burkhan',
      'หินชามานกาแห่งทะเลสาบไบคาล (ที่สถิตของบูร์คาน)',
      'Shamanka Rock & Cape Burkhan Spirit of Lake Baikal',
      'legend',
      'อีร์คุตสค์',
      'Irkutsk Oblast',
      'ออลคอน',
      'Olkhon Island',
      53.2039,
      107.3386,
      'creepy_wind',
      'โขดหินอ่อนสีขาวและหินแกรนิตสองยอดที่ยื่นออกไปในทะเลสาบไบคาล ทะเลสาบน้ำจืดที่ลึกและเก่าแก่ที่สุดในโลก แหลมบูร์คานและหินชามานกาเป็นสถานที่ศักดิ์สิทธิ์ที่สุดของลัทธิชาแมนชาวบูร์ยัตและเอเวนกิ เชื่อกันว่าเป็นที่ประทับของ ''ออยคอน เอฮิน'' ราชาแห่งวิญญาณทั้งปวง ภายในถ้ำหินมีแท่นบูชาชาแมนโบราณที่มีกฎเข้มงวดห้ามสตรีและเด็กเข้าใกล้ เสาไม้ศักดิ์สิทธิ์ 13 ต้น (Serge) เรียงรายบนหน้าผา ผูกด้วยผ้าแพรหลากสีที่โบกสะบัดเพื่อส่งคำอธิษฐานสู่สรวงสวรรค์',
      'Shamanka Rock (Cape Burkhan) on Olkhon Island is the spiritual epicenter of Lake Baikal, the deepest and oldest freshwater lake on Earth. For Siberian Buryat shamans, this marble crag is the terrestrial residence of Burkhan, the supreme spirit lord of Baikal. Shamanic altars inside its sacred cave were strictly taboo to outsiders for centuries. Today, thirteen carved prayer poles (Serge) stand above the cliffs, adorned with colorful wind-blown ribbons.',
      'หินชามานกาเป็นหนึ่งใน 9 สถานที่ศักดิ์สิทธิ์ที่สุดในเอเชียตามคติชนวิทยาของเอเชียเหนือ ในอดีตผู้ขี่ม้าผ่านแหลมนี้จะต้องผูกผ้านวมไว้ใต้กีบเท้าม้าเพื่อไม่ให้เสียงฝีเท้าไปรบกวนวิญญาณเทพเจ้า',
      'Inscribed in Siberian sacred geography, Shamanka Rock hosts the annual international gathering of Eurasian shamans, honoring ancestral Tengrism traditions.',
      'ห้ามส่งเสียงดัง ดื่มสุรา หรือผูกขยะลงบนเสาเซียร์เก (Serge) ศักดิ์สิทธิ์',
      'Never litter or treat the 13 sacred shamanic Serge poles with disrespect.',
      'https://i.ytimg.com/vi/mn4oanrNQV0/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/mn4oanrNQV0/hqdefault.jpg","title":"หินชามานกาแห่งทะเลสาบไบคาล (ที่สถิตของบูร์คาน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=mn4oanrNQV0","title":"A Siberian skater’s 80 years on the ice | DW Documentary","thumbnail":"https://i.ytimg.com/vi/mn4oanrNQV0/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-avalon-king-arthur-tomb',
      'เนินเขากลาสตันเบอรีทอร์ (เกาะอวาลอนและสุสานกษัตริย์อาเธอร์)',
      'The Isle of Avalon & King Arthur''s Tomb at Glastonbury Tor',
      'legend',
      'ซอเมอร์เซต',
      'Somerset',
      'กลาสตันเบอรี',
      'Glastonbury',
      51.1447,
      -2.6986,
      'whisper',
      'เนินเขารูปทรงเจดีย์ธรรมชาติที่ตั้งตระหง่านอยู่เหนือทุ่งราบบึงมักปกคลุมด้วยม่านหมอกหนาทึบจนดูคล้ายเกาะลอยน้ำ ในตำนานเคลติกและอัศวินโต๊ะกลม เชื่อกันว่ากลาสตันเบอรีทอร์คือ ''เกาะอวาลอน'' (Isle of Avalon) ดินแดนลี้ลับที่กษัตริย์อาเธอร์ถูกนำตัวมารักษาบาดแผลจากการรบและบรรทมชั่วกัลปาวสาน ในปี 1191 พระสงฆ์ในอารามกลาสตันเบอรีได้ขุดพบโลงไม้โอ๊กโบราณพร้อมไม้กางเขนตะกั่วสลักว่า ''ณ ที่นี้ กษัตริย์อาเธอร์ได้พักผ่อนอย่างสงบกับกวินิเวียร์ พระมเหสี''',
      'Rising dramatically above the misty Somerset Levels, Glastonbury Tor is crowned by the roofless 14th-century St. Michael''s Tower. Steeped in Celtic mythology as the entrance to Annwn (the fairy underworld ruled by Gwyn ap Nudd), it is famously identified as the enchanted Isle of Avalon. In 1191, monks at Glastonbury Abbey unearthed an ancient hollowed oak trunk containing the bones of a towering man and a cross inscribed with King Arthur''s epitaph.',
      'กลาสตันเบอรีทอร์มีร่องลานดินขั้นบันไดลึกลับ 7 ชั้นรอบเนินเขา ซึ่งยังเป็นข้อถกเถียงของนักโบราณคดีว่าเป็นทางเดินเขาวงกตยุคหินใหม่หรือระเบียงทำกสิกรรมโบราณ',
      'Maintained by the National Trust, the Tor is celebrated as a major Ley Line convergence point and remains the preeminent center of Arthurian folklore in Britain.',
      'ห้ามขุดค้นหรือเคลื่อนย้ายก้อนหินโบราณบนยอดเขากลาสตันเบอรี',
      'Never disturb the ancient terraced earthworks surrounding Glastonbury Tor.',
      'https://i.ytimg.com/vi/-2e1KOX0u2o/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/-2e1KOX0u2o/hqdefault.jpg","title":"เนินเขากลาสตันเบอรีทอร์ (เกาะอวาลอนและสุสานกษัตริย์อาเธอร์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=-2e1KOX0u2o","title":"Glastonbury: Isle of Avalon Revealed ⚔️ Full Documentary | The Untold Story of Power and Mystery","thumbnail":"https://i.ytimg.com/vi/-2e1KOX0u2o/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-carlsbad-caverns-bat-flight',
      'ถ้ำคาร์ลสแบดและตำนานมหาวิหารค้างคาวใต้พิภพ',
      'Carlsbad Caverns Bottomless Pit & Great Bat Flights',
      'legend',
      'นิวเม็กซิโก',
      'New Mexico',
      'เอ็ดดี',
      'Eddy County',
      32.1753,
      -104.4439,
      'water_spirit',
      'ระบบถ้ำหินปูนใต้ดินขนาดมหึมาที่ถูกกัดเซาะด้วยกรดซัลฟูริกในเทือกเขากัวดาลูเป โดดเด่นด้วยห้อง ''บิ๊กรู้ม'' (The Big Room) ห้องโถงธรรมชาติที่ใหญ่เป็นอันดับต้นๆ ของโลก มีตำนานของชนเผ่าอะปาเชและนักคาวบอย จิม ไวท์ ผู้ค้นพบถ้ำในปี 1898 หลังจากเห็นควันสีดำพวยพุ่งขึ้นมาจากพื้นดิน ซึ่งแท้จริงคือฝูงค้างคาวหางหนูนับล้านตัวที่บินออกจากปากถ้ำ ลึกเข้าไปในถ้ำมี ''หลุมไร้ก้น'' (Bottomless Pit) ที่มีเรื่องเล่าของเสียงกระซิบจากใจกลางโลกที่คอยล่อลวงผู้สำรวจให้ตกลงไป',
      'Deep beneath the Chihuahuan Desert lies Carlsbad Caverns, sculpted by ancient sulfuric acid eating through Permian reef limestone. In 1898, teenager Jim White noticed a massive black funnel cloud swirling into the desert sky; approaching, he realized it was millions of Mexican free-tailed bats erupting from a subterranean maw. Within its immense chambers lies the ''Bottomless Pit'', surrounded by Apache folklore of spirit winds dwelling in the abyss.',
      'ได้รับการประกาศเป็นอุทยานแห่งชาติในปี 1930 และมรดกโลกยูเนสโกในปี 1995 บิ๊กรู้มมีความยาวกว่า 1,200 เมตร และสูงกว่า 78 เมตร สามารถบรรจุอาคารรัฐสภาสหรัฐฯ ได้ทั้งหลัง',
      'Carlsbad Caverns is recognized worldwide for its colossal speleothems and evening bat flight spectacles, steeped in southwestern frontier exploration legends.',
      'ห้ามใช้แฟลชถ่ายรูปหรือส่งเสียงดังรบกวนฝูงค้างคาวขณะบินออกจากปากถ้ำ',
      'Never use flash photography or loud noises during the evening bat exodus.',
      'https://i.ytimg.com/vi/qU9ljdAh-gQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/qU9ljdAh-gQ/hqdefault.jpg","title":"ถ้ำคาร์ลสแบดและตำนานมหาวิหารค้างคาวใต้พิภพ"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qU9ljdAh-gQ","title":"Carlsbad Caverns National Park in New Mexico: Exploring the Big Room & Natural Entrance","thumbnail":"https://i.ytimg.com/vi/qU9ljdAh-gQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-giant-causeway-finn-maccool',
      'ทางเดินยักษ์แห่งไอร์แลนด์ (ตำนานฟินน์ แมคคูล และเสาหินบะซอลต์)',
      'The Legend of Finn MacCool & The Giant''s Causeway',
      'legend',
      'แอนทริม',
      'County Antrim',
      'บุชมิลส์',
      'Bushmills',
      55.2408,
      -6.5116,
      'water_spirit',
      'ชายฝั่งมหัศจรรย์ที่มีเสาหินบะซอลต์ทรงหกเหลี่ยมกว่า 40,000 ต้น เรียงต่อกันเป็นแนวยื่นลงสู่ทะเลไอริชราวกับฝีมือมนุษย์ ตำนานเกลิกเล่าว่า ฟินน์ แมคคูล ยักษ์นักรบชาวไอริช ได้สร้างทางเดินหินนี้ข้ามทะเลไปยังสก็อตแลนด์เพื่อท้าสู้กับยักษ์เบนานดอนเนอร์ ทว่าเมื่อเห็นขนาดตัวอันมหึมาของคู่ต่อสู้ ภรรยาของฟินน์จึงออกอุบายจับฟินน์แต่งตัวเป็นทารกนอนในเปล เมื่อยักษ์สก็อตแลนด์เห็น ''ทารก'' ตัวใหญ่ขนาดนี้ จึงตกใจกลัวว่าพ่อของเด็กจะตัวใหญ่ขนาดไหน จึงรีบวิ่งหนีกลับสก็อตแลนด์และทำลายสะพานหินทิ้ง',
      'Formed of 40,000 interlocking polygonal basalt columns stepping into the stormy Irish Sea, the Giant''s Causeway is Ireland''s most famous natural wonder. Celtic myth tells that Irish giant Finn MacCool built the bridge to cross to Scotland and fight giant Benandonner. Seeing Benandonner''s terrifying size, Finn''s wife Oonagh disguised Finn as a sleeping infant. Terrified by the monstrous size of the ''baby'', the Scottish giant fled home, smashing the causeway behind him.',
      'ในทางธรณีวิทยา เสาหินเกิดจากการเย็นตัวอย่างรวดเร็วของลาวาภูเขาไฟเมื่อ 60 ล้านปีก่อน ได้รับการขึ้นทะเบียนเป็นมรดกโลกยูเนสโกแห่งแรกของไอร์แลนด์เหนือในปี 1986',
      'A UNESCO World Heritage Site managed by the National Trust, the site blends fascinating Tertiary volcanic geology with iconic Irish mythology.',
      'ห้ามขูด ขีดเขียน หรือกระเทาะชิ้นส่วนเสาหินบะซอลต์ติดมือกลับไป',
      'Never chip away basalt fragments or remove hexagonal stones from the shoreline.',
      'https://i.ytimg.com/vi/w3mKbkvjh1Q/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/w3mKbkvjh1Q/hqdefault.jpg","title":"ทางเดินยักษ์แห่งไอร์แลนด์ (ตำนานฟินน์ แมคคูล และเสาหินบะซอลต์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=w3mKbkvjh1Q","title":"THE GIANT''S CAUSEWAY and The Legend of Finn MacCool","thumbnail":"https://i.ytimg.com/vi/w3mKbkvjh1Q/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-superstition-mountains-thunderbird',
      'เทือกเขาซูเปอร์สติชัน (ตำนานวิหคสายฟ้าและประตูมิติอาปาเช)',
      'Superstition Mountains & The Apache Thunderbird Lore',
      'legend',
      'แอริโซนา',
      'Arizona',
      'พินัล',
      'Pinal County',
      33.4273,
      -111.3962,
      'jungle_curse',
      'เทือกเขาหินผาสีแดงอันขรึมขลังในทะเลทรายโซโนรา ชนเผ่าอาปาเชเคารพว่ายอดเขา ''วีเควพลา'' (Weavers Needle) เป็นประตูสู่โลกใต้พิภพและเป็นรังของ ''วิหคสายฟ้า'' (Thunderbird) สิ่งมีชีวิตศักดิ์สิทธิ์ที่กะพริบตาเป็นฟ้าแลบและกระพือปีกเป็นเสียงฟ้าร้อง เมื่อคนผิวขาวพยายามขึ้นไปค้นหาขุมทองคำลอสต์ดัตช์แมน มักเกิดพายุฟ้าผ่ากระทันหัน หมอกทึบบดบังทิศทาง และมีผู้สูญหายหรือถูกสังหารตัดหัวทิ้งไว้ตามซอกผาอย่างลึกลับ',
      'Jutting abruptly from the Sonoran Desert, the jagged Superstition Mountains are revered by the Western Apache as sacred ground housing the spirits of the wind and the mighty Thunderbird. The needle-like spire of Weaver''s Needle is considered a doorway to the underworld. Countless prospectors hunting the fabled Lost Dutchman Gold Mine over the last century vanished or were found decapitated, reinforcing legends of supernatural mountain guardians.',
      'เทือกเขาซูเปอร์สติชันเป็นหนึ่งในพื้นที่ธรรมชาติที่มีคดีการเสียชีวิตและการสูญหายของนักปีนเขามากที่สุดในอเมริกา ปัจจุบันเป็นส่วนหนึ่งของเขตสงวนป่าไม้ Superstition Wilderness',
      'Documented in American frontier history and outdoor survivals, the treacherous canyons and extreme desert heat make this mountain range as perilous as it is legendary.',
      'ห้ามบุกรุกเข้าไปในซอกผาศักดิ์สิทธิ์ของชาวอาปาเชโดยไม่มีผู้ชำนาญทาง',
      'Never hike uncharted desert canyons alone during thunderstorm season.',
      'https://i.ytimg.com/vi/btDeWxLD14E/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/btDeWxLD14E/hqdefault.jpg","title":"เทือกเขาซูเปอร์สติชัน (ตำนานวิหคสายฟ้าและประตูมิติอาปาเช)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=btDeWxLD14E","title":"\"I WILL NOT Go Into These Mountains ALONE\" (The Story of The MOST HAUNTED Mountain Range in America)","thumbnail":"https://i.ytimg.com/vi/btDeWxLD14E/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-castle-of-good-hope-drakestein',
      'ปราสาทกู๊ดโฮป (ป้อมปราการห้าแฉกและคำสาปผู้ว่าการดราเกนสไตน์)',
      'The Dark Legend of the Castle of Good Hope',
      'legend',
      'เวสเทิร์นเคป',
      'Western Cape',
      'เคปทาวน์',
      'Cape Town',
      -33.9261,
      18.4281,
      'creepy_wind',
      'ป้อมปราการหินรูปดาวห้าแฉกที่เก่าแก่ที่สุดในแอฟริกาใต้ สร้างโดยบริษัทอินเดียตะวันออกของเนเธอร์แลนด์ (VOC) ในปี 1666 ภายในป้อมมีห้องขังมืด ''ดอนเคอร์กัท'' (Donker Gat) ที่เมื่อน้ำขึ้นสูงจะท่วมขังนักโทษจนสำลักน้ำตาย ในศตวรรษที่ 18 ผู้ว่าการ ปีเตอร์ ฟอน นูดต์ ได้สั่งประหารทหาร 7 นาย ทหารคนสุดท้ายได้สาปแช่งให้ผู้ว่าการต้องมารับฟังคำพิพากษาของพระเจ้า ในวันเดียวกันนั้น ผู้ว่าการถูกพบเสียชีวิตคาโต๊ะทำงานด้วยอาการหัวใจวายและใบหน้าบิดเบี้ยวด้วยความกลัว',
      'The Castle of Good Hope, a pentagonal bastion fortress built in 1666 by the Dutch East India Company, is South Africa''s oldest surviving colonial building. In 1728, tyrannical Governor Pieter Gysbert van Noodt condemned seven soldiers to death; before being hanged, the final convict cursed the governor to answer before God''s judgment seat. Later that day, Van Noodt was found dead at his desk, staring in frozen terror. His restless ghost wanders the ramparts.',
      'ปราสาทกู๊ดโฮปยังคงมีตำนานของ ''สตรีชุดเทา'' (Lady in Grey) และระฆังหอคอยที่ลั่นเองโดยไม่มีคนตี ปัจจุบันเป็นพิพิธภัณฑ์ทางทหารและโบราณสถานแห่งชาติของแอฟริกาใต้',
      'A cornerstone of South African colonial heritage, the castle is steeped in ghost accounts confirmed by centuries of military sentries and civilian staff.',
      'ห้ามเดินเข้าไปในห้องขังดอนเคอร์กัทเพียงลำพังในเวลากลางคืน',
      'Never enter the flooded Donker Gat dungeon cells without guide supervision.',
      'https://i.ytimg.com/vi/lalRz8KcYkQ/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/lalRz8KcYkQ/hqdefault.jpg","title":"ปราสาทกู๊ดโฮป (ป้อมปราการห้าแฉกและคำสาปผู้ว่าการดราเกนสไตน์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=lalRz8KcYkQ","title":"Castle of Good Hope part 1","thumbnail":"https://i.ytimg.com/vi/lalRz8KcYkQ/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-muralha-da-china-meng-jiangnu',
      'ตำนานน้ำตาเมิ่งเจียงหนี่ (เสียงร่ำไห้สะเทือนกำแพงเมืองจีน)',
      'The Weeping Tears of Lady Meng Jiang at the Great Wall',
      'legend',
      'เหอเป่ย์',
      'Hebei',
      'ฉินหวงเต่า',
      'Qinhuangdao',
      40.0075,
      119.7439,
      'creepy_wind',
      'หนึ่งในสี่สุดยอดตำนานพื้นบ้านของจีน ยุคราชวงศ์ฉิน สามีของนางเมิ่งเจียงหนี่ถูกเกณฑ์แรงงานไปสร้างกำแพงเมืองจีนทางตอนเหนือ เมื่อฤดูหนาวมาถึง นางได้เย็บเสื้อกันหนาวและเดินเท้าพันลี้เพื่อนำไปให้สามี ทว่าเมื่อไปถึงด่านซานไห่กวน นางพบว่าสามีเสียชีวิตจากความอดอยากและถูกฝังไว้ใต้กำแพง นางเมิ่งเจียงหนี่ร่ำไห้อย่างเจ็บปวดเป็นเวลาสามวันสามคืนจนฟ้าผ่าและกำแพงเมืองจีนพังทลายลงมาเป็นแนวยาว เผยให้เห็นโครงกระดูกของสามี ก่อนที่นางจะกระโดดทะเลตายตาม',
      'One of China''s four great folk tales, Lady Meng Jiang''s story is set during the Qin Dynasty. Her beloved husband Fan Qiliang was seized by imperial soldiers to build the Great Wall. Traveling thousands of li to bring him warm winter clothes, she arrived at Shanhaiguan only to learn he had perished of exhaustion and was buried in the wall. Her heartbroken weeping for three days caused an 800-li section of the Great Wall to collapse, revealing his remains.',
      'ศาลเจ้าเมิ่งเจียงหนี่ (Meng Jiangnü Temple) สร้างขึ้นตั้งแต่สมัยราชวงศ์ซ่งบนเนินเขาใกล้ด่านซานไห่กวน เป็นอนุสรณ์สถานแห่งความรักและความเสียสละของราษฎรในประวัติศาสตร์จีน',
      'The Meng Jiangnü Temple at Shanhaiguan is a state-level cultural relic. The legend symbolizes the immense human sacrifice and grief that built the world-famous Great Wall of China.',
      'ห้ามหัวเราะเยาะหรือลบหลู่รูปปั้นนางเมิ่งเจียงหนี่ที่ศาลเจ้าด่านซานไห่กวน',
      'Never mock or disrespect the mourning statue of Lady Meng Jiang at her memorial.',
      'https://i.ytimg.com/vi/6wMoDlc_Vyw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/6wMoDlc_Vyw/hqdefault.jpg","title":"ตำนานน้ำตาเมิ่งเจียงหนี่ (เสียงร่ำไห้สะเทือนกำแพงเมืองจีน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=6wMoDlc_Vyw","title":"The Legend of Meng Jiangnü: The Cry That Broke the Great Wall","thumbnail":"https://i.ytimg.com/vi/6wMoDlc_Vyw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-castillo-de-san-marcos-ghosts',
      'ป้อมคาสติลโล เด ซาน มาร์กอส (ป้อมหินเปลือกหอยและวิญญาณสเปน)',
      'The Haunted Bastions of Castillo de San Marcos',
      'legend',
      'ฟลอริดา',
      'Florida',
      'เซนต์ออกัสติน',
      'St. Augustine',
      29.8978,
      -81.3119,
      'creepy_wind',
      'ป้อมปราการหินสไตล์สเปนที่เก่าแก่ที่สุดในสหรัฐอเมริกา สร้างขึ้นในปี 1672 จากหินเปลือกหอย ''โคควินา'' (Coquina) ที่สามารถดูดซับแรงกระสุนปืนใหญ่ได้โดยไม่แตก ป้อมแห่งนี้ผ่านศึกสงครามและการล้อมเมืองมานับไม่ถ้วน ในปี 1833 มีการค้นพบห้องลับใต้ดินที่ถูกโบกปูนปิดตาย ภายในพบโครงกระดูกสองร่างถูกล่ามโซ่ติดกับผนังหิน เชื่อว่าเป็นภรรยาของผู้พันชาวสเปนกับชู้รักที่ถูกขังลืมทั้งเป็น วิญญาณของพวกเขายังคงเดินวนเวียนตามเชิงเทินป้อมในยามค่ำคืน',
      'Castillo de San Marcos in St. Augustine is the oldest masonry fort in the continental United States, built from indestructible coquina shell stone. In the 1830s, soldiers discovered a hidden subterranean room walled up centuries prior, finding two human skeletons shackled to the wall—believed to be a Spanish captain''s unfaithful young wife and her lover immured alive. Sentries along the bastions report cold spots, phantom Spanish soldiers, and sorrowful wailing.',
      'เซนต์ออกัสตินเป็นเมืองที่ชาวสเปนเข้ามาตั้งถิ่นฐานอย่างต่อเนื่องที่เก่าแก่ที่สุดในสหรัฐฯ ปัจจุบันป้อมคาสติลโลได้รับการคุ้มครองเป็นอนุสรณ์สถานแห่งชาติ (National Monument)',
      'Now a National Monument managed by the National Park Service, the fort hosts historic cannon firings and remains a centerpiece of America''s colonial ghost stories.',
      'ห้ามขีดเขียนชื่อลงบนกำแพงหินเปลือกหอยโคควินา',
      'Never deface or dislodge the fragile coquina shell stones of the fort walls.',
      'https://i.ytimg.com/vi/Hwf3VR5jKEU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Hwf3VR5jKEU/hqdefault.jpg","title":"ป้อมคาสติลโล เด ซาน มาร์กอส (ป้อมหินเปลือกหอยและวิญญาณสเปน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Hwf3VR5jKEU","title":"What Still Haunts Castillo De San Marcos? | Ghost Adventures S2 Ep3 | Discovery Channel SEA","thumbnail":"https://i.ytimg.com/vi/Hwf3VR5jKEU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-petra-al-khazneh-treasury-urn',
      'โกศมหาสมบัติแห่งอัล-คาซเนห์ (วิหารศิลาแกะสลักนครเปตรา)',
      'The Pharaoh''s Urn & Djinn Chambers of Al-Khazneh (Petra)',
      'legend',
      'มะอาน',
      'Ma''an Governorate',
      'วาดิมูซา',
      'Wadi Musa',
      30.3222,
      35.4516,
      'whisper',
      'วิหารหินทรายสีชมพูขนาดยักษ์ที่แกะสลักเข้าไปในหน้าผาหินของนครโบราณเปตรา ชาวเบดูอินพื้นถิ่นมีตำนานเล่าว่า ''โกศหิน'' บนยอดหน้าผาของวิหารเป็นที่ซ่อนสมบัติทองคำของฟาโรห์อียิปต์ในสมัยที่ไล่ตามโมเสส จึงทำให้ชาวบ้านในอดีตพยายามใช้ปืนไรเฟิลยิงถล่มโกศหินเพื่อหวังให้ทองคำร่วงลงมา (จนปรากฏรอยกระสุนปืนจริงบนหิน) นอกจากนี้ซอกหุบเขาซิก (Siq) ยังมีตำนานเรื่อง ''ญิน'' หรือภูตินรสิงห์แห่งทะเลทรายที่คอยปกป้องสุสานของชาวนาบาเทียน',
      'Carved directly into soaring sandstone cliffs, Al-Khazneh (The Treasury) is the jewel of the Nabataean desert capital of Petra. Local Bedouin lore held that the large carved stone urn atop the façade contained the immense gold treasure of an Egyptian Pharaoh who pursued Moses. Bedouins shot at the urn with rifles hoping to shatter it and release the gold, leaving visible bullet scars. Desert Djinn are believed to guard the subterranean tombs beneath.',
      'เปตราได้รับการสถาปนาเป็น 1 ใน 7 สิ่งมหัศจรรย์ของโลกยุคใหม่ และเป็นมรดกโลกยูเนสโก ในปี 2003 นักโบราณคดีได้ขุดพบสุสานใต้ดิน 4 แห่งซ่อนอยู่ใต้ฐานของวิหารอัล-คาซเนห์',
      'A UNESCO World Heritage Site and New7Wonder of the World, ongoing archaeological excavations continue to unearth Nabataean tombs beneath the iconic sandstone plaza.',
      'ห้ามปีนป่ายขึ้นไปบนด้านหน้าอาคารหิน หรือใช้หินขีดเขียนผนังทราย',
      'Never climb the Treasury façade or scratch names into the fragile rose-red sandstone.',
      'https://i.ytimg.com/vi/SZ5JjLdzQ1o/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/SZ5JjLdzQ1o/hqdefault.jpg","title":"โกศมหาสมบัติแห่งอัล-คาซเนห์ (วิหารศิลาแกะสลักนครเปตรา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=SZ5JjLdzQ1o","title":"Petra, Jordan | Civilisations - BBC","thumbnail":"https://i.ytimg.com/vi/SZ5JjLdzQ1o/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-el-mirador-la-danta-pyramid',
      'เอลมิราดอร์และมหาพีระมิดลาดานตา (มหานครมายาที่สาบสูญ)',
      'The Lost Maya Metropolis of El Mirador & La Danta',
      'legend',
      'เปเตน',
      'Peten',
      'เปเตน',
      'Peten',
      17.7558,
      -89.9214,
      'jungle_curse',
      'มหานครโบราณของอารยธรรมมายายุคก่อนคลาสสิกที่ซ่อนตัวอยู่ลึกในป่าดงดิบกัวเตมาลา ที่นี่เป็นที่ตั้งของ ''พีระมิดลาดานตา'' (La Danta) หนึ่งในสิ่งก่อสร้างที่มีปริมาตรใหญ่ที่สุดในโลก (กว่า 2.8 ล้านลูกบาศก์เมตร) ชนพื้นเมืองเล่าขานถึงอาณาจักรโบราณของกษัตริย์เสือจากัวร์ที่ล่มสลายลงอย่างเป็นปริศนา ผู้ที่เดินทางบุกป่าเข้าไปมักได้ยินเสียงกลองศึกดังกึกก้องในยามค่ำคืน และเห็นเงาของนักรบมายาโบราณลาดตระเวนอยู่บนยอดพีระมิดเหนือยอดไม้',
      'Deep within the dense rainforest of the Petén basin lies El Mirador, the pre-Columbian cradle of Maya civilization. Its crowning monument, the La Danta pyramid complex, is by volume one of the largest ancient structures on the planet (2.8 million cubic meters). Abandoned mysteriously around 150 AD, local Maya legends tell of supernatural jaguar kings and guardians whose spectral war drums still echo across the jungle canopies at twilight.',
      'เอลมิราดอร์ได้รับการสำรวจโดย ดร. ริชาร์ด แฮนเซน การเดินทางเข้าสู่ซากเมืองต้องเดินเท้าหรือขี่ล่อฝ่าป่าทึบนานถึง 2 วัน ปัจจุบันกำลังอยู่ระหว่างการเสนอชื่อเป็นมรดกโลก',
      'Predating Tikal by centuries, El Mirador''s monumental causeways (sacbeob) reveal a sophisticated Preclassic society that collapsed through environmental exhaustion.',
      'ห้ามตัดไม้ ล่าสัตว์ หรือเก็บชิ้นส่วนหินแกะสลักในเขตโบราณสถานมิราดอร์',
      'Never hunt wildlife, cut timber, or remove Maya artifacts from the jungle ruins.',
      'https://i.ytimg.com/vi/fwuUyrEBdbs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/fwuUyrEBdbs/hqdefault.jpg","title":"เอลมิราดอร์และมหาพีระมิดลาดานตา (มหานครมายาที่สาบสูญ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=fwuUyrEBdbs","title":"The Tombs of El Mirador | National Geographic","thumbnail":"https://i.ytimg.com/vi/fwuUyrEBdbs/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-lalibela-rock-hewn-churches',
      'โบสถ์หินแกะสลักแห่งลาลิเบลา (วิหารทูตสวรรค์สร้างข้ามคืน)',
      'The Angel-Built Monolithic Churches of Lalibela',
      'legend',
      'อัมฮารา',
      'Amhara Region',
      'ลาลิเบลา',
      'Lalibela',
      12.0319,
      39.0411,
      'temple_bell',
      'กลุ่มโบสถ์คริสต์ออร์โธด็อกซ์เอธิโอเปีย 11 แห่งในศตวรรษที่ 12 ที่ไม่ได้สร้างขึ้นจากอิฐหรือปูน แต่สลักเจาะลึกลงไปในภูเขาหินภูเขาไฟก้อนเดียวลงสู่ใต้ดิน โดยเฉพาะ ''โบสถ์เซนต์จอร์จ'' ที่มีผังเป็นรูปกางเขนสมบูรณ์แบบ ตำนานศักดิ์สิทธิ์เล่าว่า กษัตริย์เกเบร เมสเคล ลาลิเบลา ทรงได้รับบัญชาจากพระเจ้าให้สร้าง ''เยรูซาเลมใหม่'' โดยในตอนกลางวันมีมนุษย์ขุดเจาะหิน และในตอนกลางคืนมีเหล่า ''ทูตสวรรค์'' เสด็จลงมาช่วยขุดสร้างจนเสร็จอย่างน่าอัศจรรย์',
      'In the rugged highlands of Ethiopia stand 11 medieval rock-hewn monolithic churches, carved downwards out of solid red volcanic tuff without mortar or scaffolding. The most iconic, Bet Giyorgis (Church of Saint George), forms a pristine monolithic cross 12 meters deep. Ethiopian Orthodox tradition maintains that King Gebre Mesqel Lalibela had human stonemasons working by day, while hosts of heavenly angels worked through the night to complete the subterranean sanctuaries.',
      'ลาลิเบลาได้รับการขึ้นทะเบียนเป็นมรดกโลกยูเนสโกรุ่นแรกในปี 1978 ยังคงเป็นสถานที่แสวงบุญที่ศักดิ์สิทธิ์และมีชีวิตของชาวคริสต์เอธิโอเปียมานานกว่า 800 ปี',
      'An active center of Ethiopian Christianity, pilgrims dressed in traditional white shamma robes gather here in their hundreds of thousands for Timkat (Epiphany).',
      'ทุกคนต้องถอดรองเท้าก่อนก้าวเข้าสู่พื้นโบสถ์หินใต้ดินทุกแห่ง',
      'Always remove shoes before stepping onto the woven carpets inside the rock churches.',
      'https://i.ytimg.com/vi/excYNB26fhs/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/excYNB26fhs/hqdefault.jpg","title":"โบสถ์หินแกะสลักแห่งลาลิเบลา (วิหารทูตสวรรค์สร้างข้ามคืน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=excYNB26fhs","title":"Inside Lalibela, the mysterious holy site visited by 200,000 Ethiopian Christians on their annual…","thumbnail":"https://i.ytimg.com/vi/excYNB26fhs/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-gobekli-tepe-stone-pillars',
      'เกอเบกลี เทเป (วิหารแห่งแรกของมนุษยชาติและเสาหินรูปตัว T)',
      'The Enigma of Göbekli Tepe & The Vulture Stone',
      'legend',
      'ชันลืออูร์ฟา',
      'Sanliurfa',
      'ฮาลีลีเย',
      'Haliliye',
      37.2232,
      38.9224,
      'whisper',
      'ศาสนสถานหินยุคก่อนประวัติศาสตร์อายุเก่าแก่กว่า 11,500 ปี (สร้างขึ้นก่อนเกษตรกรรม ยุคโลหะ และการประดิษฐ์ล้อ) ประกอบด้วยวงกลมหินขนาดยักษ์ที่มีเสาหินรูปตัว T น้ำหนักหลายสิบตัน สลักลายนูนต่ำรูปสัตว์ดุร้าย เช่น เสือดาว งู แมงป่อง และนกแร้ง โดยเฉพาะ ''หินนกแร้ง'' (เสาหินหมายเลข 43) ที่นักวิชาการเชื่อว่าอาจเป็นการบันทึกเหตุการณ์ดาวหางพุ่งชนโลกในยุคยังเกอร์ ดรายแอส สถานที่แห่งนี้ถูกฝังกลบอย่างตั้งใจด้วยมือมนุษย์ก่อนถูกทิ้งร้างไปเป็นปริศนา',
      'Dating back to 9500 BC, Göbekli Tepe in southeastern Turkey upended human history: hunter-gatherers erected monumental megalithic stone circles thousands of years before agriculture or metal tools existed. Massive T-shaped limestone pillars weighing up to 20 tons are carved with high-relief beasts—lions, snakes, vultures, and headless humans. Column 43 (The Vulture Stone) is debated as an astronomical record of a comet impact that plunged Earth into the Younger Dryas.',
      'ขุดค้นโดยนักโบราณคดีชาวเยอรมัน เคลาส์ ชมิดต์ ตั้งแต่ปี 1994 ได้รับการยกย่องเป็นมรดกโลกยูเนสโก และเปลี่ยนกระบวนทัศน์ทางประวัติศาสตร์ว่า ''ศาสนาเกิดก่อนอารยธรรม''',
      'UNESCO inscribed Göbekli Tepe in 2018. It fundamentally challenged the narrative that farming preceded organized religion, demonstrating complex spiritual temples at civilization''s dawn.',
      'ห้ามสัมผัสหรือเหยียบย่ำโครงสร้างเสาหินแกะสลักโบราณ',
      'Never touch or climb upon the delicate 11,000-year-old carved limestone monoliths.',
      'https://i.ytimg.com/vi/n-phVB-EmR8/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/n-phVB-EmR8/hqdefault.jpg","title":"เกอเบกลี เทเป (วิหารแห่งแรกของมนุษยชาติและเสาหินรูปตัว T)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=n-phVB-EmR8","title":"The OLDEST temple in the world 🤯 - BBC","thumbnail":"https://i.ytimg.com/vi/n-phVB-EmR8/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-mausoleum-of-halicarnassus',
      'สุสานแห่งฮาลิคาร์นัสซัส (1 ใน 7 สิ่งมหัศจรรย์โลกยุคโบราณ)',
      'The Splendor and Ruins of the Mausoleum of Halicarnassus',
      'legend',
      'มูลา',
      'Mugla',
      'โบดรุม',
      'Bodrum',
      37.0379,
      27.4241,
      'creepy_wind',
      'อนุสรณ์สถานสุสานหินอ่อนขนาดยักษ์สูง 45 เมตร สร้างขึ้นในช่วง 350 ปีก่อนคริสตกาล สำหรับมอโซลัส เจ้าผู้ครองแคว้นคาเรีย ออกแบบโดยสถาปนิกชาวกรีกผู้ยิ่งใหญ่ ล้อมรอบด้วยเสาหินอ่อน 36 ต้น และประดับรูปปั้นรถม้าเทียมม้าสี่ตัวบนยอดแหลม ความวิจิตรตระการตาทำให้ชื่อ ''Mausoleum'' กลายเป็นคำสากลที่ใช้เรียกสุสานขนาดใหญ่มาจนถึงปัจจุบัน สุสานยืนยงผ่านศึกสงครามของอเล็กซานเดอร์มหาราชมาได้นานกว่า 1,500 ปี ก่อนจะพังทลายลงจากแผ่นดินไหวครั้งใหญ่',
      'Standing 45 meters tall in ancient Caria (modern Bodrum, Turkey), the Mausoleum at Halicarnassus was built around 350 BC for Mausolus, satrap of Caria, and his queen Artemisia II. Adorned with 36 Ionic columns and reliefs sculpted by the greatest Greek artists (including Scopas), its summit bore a colossal bronze chariot. So magnificent was its architecture that the word ''mausoleum'' became the universal term for monumental burial tombs.',
      'ซากหินอ่อนของสุสานถูกอัศวินแห่งเซนต์จอห์นนำไปสร้างปราสาทโบดรุมในศตวรรษที่ 15 ชิ้นส่วนรูปสลักนูนต่ำบางส่วนถูกค้นพบและนำไปจัดแสดงที่บริติชมิวเซียมในลอนดอน',
      'One of the Seven Wonders of the Ancient World, its ruins in Bodrum reveal the ingenious subterranean burial chambers and surviving carved reliefs.',
      'ห้ามขุดค้นหรือเคลื่อนย้ายเศษหินอ่อนโบราณในบริเวณโบราณสถาน',
      'Never displace or loot ancient marble fragments from the archaeological foundations.',
      'https://i.ytimg.com/vi/Dbf6O9_RmeI/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/Dbf6O9_RmeI/hqdefault.jpg","title":"สุสานแห่งฮาลิคาร์นัสซัส (1 ใน 7 สิ่งมหัศจรรย์โลกยุคโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=Dbf6O9_RmeI","title":"The Lost Wonder of the Ancient World: The Mausoleum at Halicarnassus | Full 4K Documentary","thumbnail":"https://i.ytimg.com/vi/Dbf6O9_RmeI/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-skellig-michael-hermitage',
      'สเกลลิกไมเคิล (อารามหินรังผึ้งสุดขอบโลกแห่งไอร์แลนด์)',
      'The Sea-Crag Monastic Fortress of Skellig Michael',
      'legend',
      'เคอร์รี',
      'County Kerry',
      'ไอเวอราห์',
      'Iveragh Peninsula',
      51.7708,
      -10.5397,
      'water_spirit',
      'เกาะหินปิรามิดสูงชันกลางมหาสมุทรแอตแลนติกอันเชี่ยวกราก ในศตวรรษที่ 6 นักพรตชาวคริสต์ได้ล่องเรือฝ่าเกลียวคลื่นมาสร้างอารามหินทรง ''รังผึ้ง'' (Clochán) บนความสูง 180 เมตรเหนือระดับน้ำทะเล โดยเรียงหินซ้อนกันโดยไม่ใช้ปูน พวกเขาดำเนินชีวิตอย่างโดดเดี่ยวด้วยการจับปลาและเก็บไข่นกเพื่อภาวนาตัดขาดจากกิเลส ตำนานเล่าว่านี่คือจุดที่อัครเทวทูตมีคาเอลเสด็จลงมาช่วยนักบุญแพทริกขับไล่งูและปิศาจร้ายออกจากเกาะไอร์แลนด์',
      'Rising sheer and forbidding out of the Atlantic Ocean off southwest Ireland, Skellig Michael was home to early Christian monks in the 6th century. Seeking the ultimate desert solitude at the edge of the known world, ascetic hermits built drystone beehive huts (clocháin) clinging to dizzying 600-foot sea precipices without mortar. Celtic mythology associates the crag with Saint Michael''s celestial battle casting Lucifer into the abyss.',
      'สเกลลิกไมเคิลเป็นมรดกโลกยูเนสโก และโด่งดังไปทั่วโลกในฐานะสถานที่ถ่ายทำวิหารเจไดโบราณบนดาวอัคโต (Ahch-To) ในภาพยนตร์ Star Wars: The Force Awakens และ The Last Jedi',
      'Inscribed as a UNESCO World Heritage Site in 1996, the island is globally recognized as the remote Jedi sanctuary in the Star Wars sequel trilogy.',
      'ห้ามปีนออกนอกบันไดหิน 600 ขั้นโบราณเด็ดขาดเนื่องจากหน้าผาสูงชันอันตรายถึงชีวิต',
      'Strictly adhere to the 600 ancient hand-carved stone steps; sheer drops are fatal.',
      'https://i.ytimg.com/vi/g_0lk8BY0Vk/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/g_0lk8BY0Vk/hqdefault.jpg","title":"สเกลลิกไมเคิล (อารามหินรังผึ้งสุดขอบโลกแห่งไอร์แลนด์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=g_0lk8BY0Vk","title":"Star Wars Island - Skellig Michael","thumbnail":"https://i.ytimg.com/vi/g_0lk8BY0Vk/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-tiwanaku-gate-of-sun',
      'ติวานากูและประตูดวงอาทิตย์ (อารยธรรมแอนดีสปริศนาแห่งโบลิเวีย)',
      'The Mystery of Tiwanaku & The Gate of the Sun (Bolivia)',
      'legend',
      'ลาปาซ',
      'La Paz Department',
      'อินกาวี',
      'Ingavi',
      -16.5547,
      -68.6736,
      'whisper',
      'อารยธรรมโบราณบนที่ราบสูงอัลติปลาโน สูงเกือบ 4,000 เมตรเหนือระดับน้ำทะเล ใกล้ทะเลสาบติติกากา โดดเด่นด้วย ''ประตูดวงอาทิตย์'' (Gate of the Sun) ที่แกะสลักจากหินแอนดีไซต์ก้อนเดียวหนักกว่า 10 ตัน สลักภาพเทพเจ้าแห่งดวงอาทิตย์ (วิราโคชา) ถือคทาสายฟ้าทั้งสองมือและมีน้ำตาเป็นสายฝนไหลอาบแก้ม บล็อกหินในวิหารปูมาปุนกูถูกตัดเจาะเป็นมุมฉากและร่องลิ่มเดือยอย่างแม่นยำราวกับการตัดด้วยเลเซอร์ จนชนพื้นเมืองไอมาราเชื่อว่านครแห่งนี้ถูกสร้างขึ้นโดย ''เหล่ายักษ์ในชั่วข้ามคืนก่อนมีแสงอาทิตย์''',
      'Perched at 3,850 meters on the Bolivian Altiplano, Tiwanaku was the pre-Inca imperial center of the southern Andes. Its most famed monument is the Gate of the Sun (Puerta del Sol), carved from a single 10-ton block of volcanic andesite. The lintel depicts the weeping Staff God (Viracocha), crowned with solar rays. Nearby Puma Punku features megalithic H-blocks precision-cut with sharp interior right angles that indigenous Aymara legends say were crafted by giants overnight.',
      'ติวานากูเจริญรุ่งเรืองระหว่างปี 500 ถึง 1000 ก่อนจะล่มสลายลงจากการเปลี่ยนแปลงของสภาพอากาศและความแห้งแล้ง ได้รับการขึ้นทะเบียนเป็นมรดกโลกยูเนสโกในปี 2000',
      'A UNESCO World Heritage Site, Tiwanaku''s sophisticated astronomical alignments and monumental stonework inspired the later Inca Empire''s sacred cosmology.',
      'ห้ามปีนป่ายหรือสัมผัสภาพสลักพระเจ้าวิราโคชาบนประตูดวงอาทิตย์',
      'Never touch or climb upon the fragile engravings of the Gate of the Sun.',
      'https://i.ytimg.com/vi/IqNvWlxLBSk/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/IqNvWlxLBSk/hqdefault.jpg","title":"ติวานากูและประตูดวงอาทิตย์ (อารยธรรมแอนดีสปริศนาแห่งโบลิเวีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=IqNvWlxLBSk","title":"Ancient Aliens: Mysterious Megalithic Stones of Puma Punku | History","thumbnail":"https://i.ytimg.com/vi/IqNvWlxLBSk/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-legend-chan-chan-adobe-city',
      'ชาน ชาน (มหานครดินดิบที่ใหญ่ที่สุดในทวีปอเมริกา)',
      'Chan Chan: The Colossal Adobe Citadel of the Chimú (Peru)',
      'legend',
      'ลาลีเบอร์ตาด',
      'La Libertad',
      'ตรูฮีโย',
      'Trujillo',
      -8.1092,
      -79.0747,
      'whisper',
      'เมืองหลวงของจักรวรรดิชิมู (Chimú) สร้างขึ้นจากอิฐโคลนดินดิบ (Adobe) ครอบคลุมพื้นที่กว่า 20 ตารางกิโลเมตร ถือเป็นเมืองดินดิบที่ใหญ่ที่สุดในทวีปอเมริกา กำแพงดินสูงกว่า 10 เมตรสลักลวดลายเรขาคณิตคลื่นน้ำ ฝูงปลา นกกระทุง และตัวนากทะเลอย่างวิจิตร ตามตำนานของชาวชิมู กษัตริย์ผู้ก่อตั้งนามว่า ทาคายนาโม ได้ล่องแพทองคำมาจากโพ้นทะเลเพื่อสร้างนครแห่งนี้ นครชานชานถูกอินคาพิชิตในปี 1470 หลังจากถูกปิดล้อมและตัดทางน้ำชลประทาน',
      'Spanning 20 square kilometers in coastal Peru, Chan Chan was the capital of the Chimú Empire and the largest adobe metropolis in the Americas, housing over 60,000 inhabitants. Its towering mud-brick walls are sculpted with intricate friezes of ocean waves, fish, pelicans, and crabs. Legend says founder-king Tacaynamo sailed from across the sea on a golden balsa raft to establish the kingdom, which fell to the Incas in 1470 after its irrigation aqueducts were diverted.',
      'ได้รับการขึ้นทะเบียนเป็นมรดกโลกยูเนสโกในปี 1986 ปัจจุบันกำลังเผชิญกับการกัดเซาะจากปรากฏการณ์เอลนีโญและพายุฝน ทำให้ต้องมีการสร้างหลังคาป้องกันโบราณสถานอย่างเข้มงวด',
      'Inscribed on UNESCO''s Danger list due to torrential rains from El Niño events, Chan Chan stands as a fragile masterpiece of pre-Columbian urban hydraulic engineering.',
      'ห้ามสัมผัสหรือพิงกำแพงลวดลายดินเหนียวโบราณ',
      'Never lean on or scrape the ancient friezes sculpted into the mud walls.',
      'https://i.ytimg.com/vi/QOcd1CLABZw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/QOcd1CLABZw/hqdefault.jpg","title":"ชาน ชาน (มหานครดินดิบที่ใหญ่ที่สุดในทวีปอเมริกา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=QOcd1CLABZw","title":"Chan Chan: The Sunken Capital of the Chimu","thumbnail":"https://i.ytimg.com/vi/QOcd1CLABZw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-amphisbaena-two-headed',
      'แอมฟิสเบนา (อสรพิษสองหัวแห่งทะเลทรายลิเบีย)',
      'The Amphisbaena (Two-Headed Serpent of the Libyan Sands)',
      'monster',
      'ไซเรไนกา',
      'Cyrenaica',
      'คูฟรา',
      'Kufra',
      24.1802,
      23.3183,
      'creepy_wind',
      'สัตว์ในตำนานปรัมปรากรีกและแอฟริกาเหนือโบราณ มีลักษณะเป็นงูพิษที่มีหัวอยู่ทั้งสองด้านของลำตัว โดยหัวที่สองจะงอกออกมาแทนหาง ทำให้มันสามารถเลื้อยและจู่โจมเหยื่อได้ทั้งสองทิศทางโดยไม่ต้องหันหลัง ดวงตาของมันส่องประกายดั่งแสงเทียนในความมืด ตามมหากาพย์ของโอวิด เล่าว่าแอมฟิสเบนาถือกำเนิดขึ้นมาจากหยดเลือดของนางเมดูซาที่หยดลงบนผืนทรายขณะที่เพอร์ซีอุสบินผ่านทะเลทรายลิเบีย พิษของมันกัดกร่อนกระดูกจนแหลกสลายในพริบตา',
      'In classical Greek and Roman bestiaries, the Amphisbaena is a fearsome mythical serpent possessing a head at both ends of its body, allowing it to strike in either direction simultaneously without turning. According to Lucan''s Pharsalia, it spawned from the venomous blood dripping from Medusa''s severed head as Perseus flew across the Libyan desert. Its eyes glowed like candles, and its venom was said to calcify flesh instantly.',
      'บันทึกโดย พลินีผู้เฒ่า (Pliny the Elder) ในหนังสือ Naturalis Historia ในยุคกลาง หนังของแอมฟิสเบนาถูกเชื่อว่าเป็นเครื่องรางรักษาไข้หนาวสั่นและการตั้งครรภ์',
      'Documented in medieval heraldry and ancient natural histories, the creature inspired the real-world scientific naming of the limbless Amphisbaenia reptile order.',
      'ห้ามข้ามรอยเลื้อยของงูที่เป็นเส้นตรงคู่ขนานบนเนินทรายกลางทะเลทราย',
      'Never step across parallel two-track serpent trails in the desert sands.',
      'https://i.ytimg.com/vi/P0-evd3elBw/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/P0-evd3elBw/hqdefault.jpg","title":"แอมฟิสเบนา (อสรพิษสองหัวแห่งทะเลทรายลิเบีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=P0-evd3elBw","title":"Amphisbaena Ancient Greek Mythological","thumbnail":"https://i.ytimg.com/vi/P0-evd3elBw/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-stymphalian-birds-arcadia',
      'ฝูงนกกินคนแห่งสติมฟาเลียน (วิหคขนสำริดแห่งอาร์คาเดีย)',
      'The Man-Eating Stymphalian Birds of Arcadia',
      'monster',
      'เพโลพอนนีส',
      'Peloponnese',
      'สติมฟาเลีย',
      'Stymphalia',
      37.8631,
      22.4636,
      'creepy_wind',
      'ฝูงนกปีศาจกินคนขนาดยักษ์ที่อาศัยอยู่ในหนองน้ำสติมฟาเลียตามตำนานกรีกโบราณ พวกมันมีจงอยปาก เล็บเท้า และปีกที่ทำจากโลหะสำริดแหลมคม สามารถยิงขนสำริดออกมากลางอากาศใส่เหยื่อได้ราวกับห่าลูกธนู และมีมูลเป็นพิษร้ายแรงทำลายพืชผลทางการเกษตรจนวอดวาย เฮอร์คิวลิสได้รับภารกิจที่ 6 ให้มากำจัดนกเหล่านี้ โดยได้รับความช่วยเหลือจากเทพีเอธีนาที่มอบ ''โครทาลา'' (กรับสำริดศักดิ์สิทธิ์) ให้เคาะจนเกิดเสียงดังสนั่น นกตกใจบินหนีขึ้นฟ้า และเฮอร์คิวลิสจึงใช้ธนูยิงสังหารพวกมันจนหมดสิ้น',
      'In Greek mythology, the Stymphalian Birds were voracious, man-eating avian terrors sacred to the war god Ares, nesting in the marshes of Lake Stymphalia. Armed with beaks of bronze, sharp talons, and metallic feathers that they could shoot like arrows into victims below, their toxic dung poisoned local farmlands. In his sixth labor, Heracles used bronze castanets (krotala) forged by Hephaestus to frighten them into flight before shooting them with hydra-poisoned arrows.',
      'ทะเลสาบสติมฟาเลียมีอยู่จริงในแคว้นโครินเทียของกรีซ เป็นพื้นที่ชุ่มน้ำอนุรักษ์ตามอนุสัญญาแรมซาร์ (Ramsar) และมีพิพิธภัณฑ์สิ่งแวดล้อมสติมฟาเลียจัดแสดงประวัติศาสตร์โบราณ',
      'The ancient ruins of Stymphalos sit along Lake Stymphalia in the Peloponnese, where classical coins featured depictions of the ferocious metallic birds.',
      'ห้ามเคาะโลหะสำริดส่งเสียงรบกวนในบึงน้ำสติมฟาเลียในยามพลบค่ำ',
      'Never strike metallic bronze chimes over the marshes of Lake Stymphalia.',
      'https://i.ytimg.com/vi/nIIjhAuC76g/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/nIIjhAuC76g/hqdefault.jpg","title":"ฝูงนกกินคนแห่งสติมฟาเลียน (วิหคขนสำริดแห่งอาร์คาเดีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=nIIjhAuC76g","title":"The myth of Hercules: 12 labors in 8-bits - Alex Gendler","thumbnail":"https://i.ytimg.com/vi/nIIjhAuC76g/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-barmanou-hindukush',
      'บาร์มานู (มนุษย์วานรขนดกแห่งเทือกเขาฮินดูกูช ปากีสถาน)',
      'The Barmanou (Wild Mountain Hominid of Hindukush)',
      'monster',
      'ไคเบอร์ปัคตูนควา',
      'Khyber Pakhtunkhwa',
      'ชิตราล',
      'Chitral',
      35.851,
      71.7864,
      'creepy_wind',
      'สิ่งมีชีวิตลึกลับคล้ายมนุษย์วานรขนาดใหญ่ที่อาศัยอยู่ตามแนวเทือกเขาสูงของฮินดูกูชในหุบเขาชิตราล ชนเผ่าคาลาชและคนเลี้ยงแกะในท้องถิ่นเล่าว่า ''บาร์มานู'' มีความสูงกว่า 2 เมตร ลำตัวปกคลุมด้วยขนสีน้ำตาลแดงหนาทึบ ส่งกลิ่นสาบฉุนรุนแรง และมีพละกำลังมหาศาล สามารถเดินสองขาและชอบส่งเสียงร้องโหยหวนในยามค่ำคืน บางครั้งมันจะลงมาขโมยวัว แกะ หรือลักพาตัวผู้หญิงชาวบ้านเข้าไปในถ้ำหิมะ',
      'The Barmanou is the cryptid wild man of the rugged Hindu Kush range, documented by shepherds in northwestern Pakistan and eastern Afghanistan. Standing between six to eight feet tall, the creature is described as a bipedal, ape-like hominid covered in thick reddish-brown fur, emitting a nauseating musky stench. Kalash tribal lore recounts the Barmanou preying on livestock and carrying off maidens into deep glacial caves.',
      'นักสัตววิทยาชาวสเปน ฆอร์ดี มากราเนอร์ (Jordi Magraner) ได้เดินทางมาทำวิจัยและสัมภาษณ์พยานผู้พบเห็นบาร์มานูกว่าร้อยคนในชิตราลระหว่างปี 1992-2002 ก่อนที่เขาจะถูกฆาตกรรมอย่างเป็นปริศนาในหุบเขา',
      'Spanish cryptozoologist Jordi Magraner spent a decade cataloging eyewitness testimonies in the Chitral valley, compiling extensive anatomical reports before his mysterious murder in 2002.',
      'ห้ามเดินตามรอยเท้าขนาดใหญ่ที่มีกลิ่นสาบในหุบเขาชิตราลตามลำพัง',
      'Never follow gigantic bare bipedal footprints emanating strong musk in the snow.',
      'https://i.ytimg.com/vi/4RMdeZVsvBg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/4RMdeZVsvBg/hqdefault.jpg","title":"บาร์มานู (มนุษย์วานรขนดกแห่งเทือกเขาฮินดูกูช ปากีสถาน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=4RMdeZVsvBg","title":"The Barmanou: Pakistan''s Elusive Bigfoot-like Cryptid THE WEEKLY STRANGE Episode 59","thumbnail":"https://i.ytimg.com/vi/4RMdeZVsvBg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-lusca-andros-blue-hole',
      'ลัสกา (อสูรหมึกยักษ์ฉลามแห่งบลูโฮลบาฮามาส)',
      'The Lusca: Monster of the Andros Blue Holes (Bahamas)',
      'monster',
      'แอนดรอส',
      'Andros Island',
      'เซ็นทรัลแอนดรอส',
      'Central Andros',
      24.7042,
      -77.7844,
      'water_spirit',
      'สัตว์ประหลาดใต้ทะเลในตำนานพื้นบ้านของชาวบาฮามาส อาศัยอยู่ใน ''บลูโฮล'' (Blue Holes) หรือหลุมยุบใต้น้ำลึกสีน้ำเงินเข้มรอบเกาะแอนดรอส ลัสกาถูกพรรณนาว่ามีท่อนบนเป็นปลาฉลามยักษ์ที่มีฟันแหลมคม และท่อนล่างเป็นหนวดยักษ์ของปลาหมึกแปดหนวดขนาดยาวกว่า 20 เมตร มันสามารถสร้างวังน้ำวนขนาดใหญ่เพื่อดูดเรือประมงและนักดำน้ำลงสู่ก้นบึ้งมืดมิด ชิ้นส่วนเรือที่พังยับเยินและร่างเหยื่อที่เหลือแต่กระดูกมักถูกพ่นกลับขึ้นมาผิวน้ำในวันถัดมา',
      'In Bahamian folklore, the Lusca is a colossal sea monster inhabiting the deep subterranean cave systems of the ocean blue holes surrounding Andros Island. Described as a terrifying hybrid possessing the ferocious jaws and head of a great white shark and the massive tentacles of an octopus exceeding 75 feet, the Lusca creates violent whirlpools when the tide shifts, sucking fishing vessels and divers into flooded underwater caverns.',
      'เกาะแอนดรอสมีบลูโฮลหนาแน่นที่สุดในโลก ปรากฏการณ์กระแสน้ำขึ้นลงที่รุนแรงดูดน้ำลงไปในถ้ำใต้น้ำอย่างรวดเร็วจนเกิดเป็นวังน้ำวนจริง ซึ่งเป็นรากฐานของตำนานอสูรลัสกา',
      'Marine scientists attribute whirlpools to tidal shifts across underwater cave networks, but local fishermen swear sightings of multi-armed apex predators lurking in the cobalt depths.',
      'ห้ามว่ายน้ำหรือทอดสมอเรือใกล้ปากปล่องบลูโฮลขณะกระแสน้ำกำลังดูดลง',
      'Never anchor small skiffs or dive into ocean blue holes during strong outgoing tidal shifts.',
      'https://i.ytimg.com/vi/bnWg7hM07Qg/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/bnWg7hM07Qg/hqdefault.jpg","title":"ลัสกา (อสูรหมึกยักษ์ฉลามแห่งบลูโฮลบาฮามาส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=bnWg7hM07Qg","title":"Jeremy May Have Found The Lusca Monster Of The Blue Holes | River Monsters","thumbnail":"https://i.ytimg.com/vi/bnWg7hM07Qg/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-dwayyo-gambrill-forest',
      'ดเวย์โย (อสูรครึ่งคนครึ่งหมาป่าแห่งป่าแมริแลนด์)',
      'The Dwayyo: Wolf-Beast of Gambrill State Park (Maryland)',
      'monster',
      'แมริแลนด์',
      'Maryland',
      'เฟรเดอริก',
      'Frederick County',
      39.4673,
      -77.4958,
      'creepy_wind',
      'สิ่งมีชีวิตประหลาดที่ยืนสองขาคล้ายมนุษย์หมาป่า มีขนสีดำดกหนา ใบหน้าเหมือนสุนัขป่า และมีหางยาวเป็นพวง อาศัยอยู่ในป่าเขาแกมบริลล์และเทือกเขาเซาท์เมาน์เทน ในปี 1965 ชาวบ้านได้เผชิญหน้ากับสัตว์ร้ายตัวนี้ในป่า มันยืนประจันหน้า ขู่คำรามเสียงดังก้องป่า และพุ่งเข้าโจมตีรถยนต์จนตัวถังบุบ ตำนานพื้นบ้านระบุว่าดเวย์โยเป็นคู่ปรับตลอดกาลของ ''สแนลลีกัสเตอร์'' (Snallygaster) มังกรมีปีกในตำนาน และมักเกิดการต่อสู้อย่างดุเดือดระหว่างสัตว์ประหลาดทั้งสองตัวนี้',
      'The Dwayyo is an aggressive, bipedal wolf-man cryptid prowling the dense hardwood forests of Gambrill State Park along South Mountain. Witnesses describe a creature over six feet tall covered in bristly dark fur, with a snarling wolfish snout, claws, and a bushy tail. In 1965, front-page reports in the Frederick News-Post detailed attacks on forestry workers. Local lore portrays the Dwayyo locked in an eternal blood feud with the winged Snallygaster.',
      'รายงานการพบเห็นดเวย์โยในทศวรรษที่ 1960 สร้างความตื่นตระหนกจนมีกลุ่มนักล่าสัตว์ติดอาวุธรวมตัวกันออกค้นหาในป่า ปัจจุบันเป็นตำนานคริปทิดที่โด่งดังของรัฐแมริแลนด์',
      'Documented extensively by folklorist George C. Rhoderick in local newspapers, the creature remains a favorite fixture of Appalachian forest folklore.',
      'ห้ามเดินป่าแถบเซาท์เมาน์เทนหลังเที่ยงคืนโดยไม่มีไฟฉายแรงสูง',
      'Never hike isolated trails in Gambrill State Park alone after midnight.',
      'https://i.ytimg.com/vi/_OW7DSGWkIU/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/_OW7DSGWkIU/hqdefault.jpg","title":"ดเวย์โย (อสูรครึ่งคนครึ่งหมาป่าแห่งป่าแมริแลนด์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=_OW7DSGWkIU","title":"What Is the Dwayyo? Maryland’s Forgotten Wildman Mystery","thumbnail":"https://i.ytimg.com/vi/_OW7DSGWkIU/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-lamassu-winged-bull-nineveh',
      'ลามัสซู (ทวารบาลวัวปีกหน้ามนุษย์แห่งนิเนเวห์ เมโสโปเตเมีย)',
      'The Lamassu: Celestial Winged Bull Guardians of Nineveh',
      'monster',
      'นิเนเวห์',
      'Nineveh Governorate',
      'โมซุล',
      'Mosul',
      36.3587,
      43.1528,
      'temple_bell',
      'สัตว์ศักดิ์สิทธิ์และทวารบาลผู้พิทักษ์พระราชวังแห่งจักรวรรดิอัสซีเรียโบราณ มีเรือนร่างเป็นวัวหรือสิงโต มีปีกนกอินทรีสยายกว้าง และมีศีรษะเป็นบุรุษสวมมงกุฎเขาสัตว์ชั้นสูง ซึ่งสื่อถึงปัญญาของมนุษย์ พละกำลังของวัว และความรวดเร็วของนกอินทรี รูปสลักหินลามัสซูขนาดมหึมาจะถูกสลักให้มี ''ห้าขา'' อย่างชาญฉลาด เพื่อให้ผู้ที่มองจากด้านหน้าเห็นทวารบาลยืนตระหง่านอย่างสงบนิ่ง แต่เมื่อมองจากด้านข้างจะเห็นมันกำลังก้าวเดินอย่างองอาจเพื่อขับไล่สิ่งชั่วร้าย',
      'In ancient Mesopotamian and Assyrian mythology, the Lamassu is a celestial protective deity possessing the body of a bull or lion, the majestic wings of an eagle, and a horned human head symbolizing supreme wisdom, physical power, and divine vigilance. Carved from single alabaster megaliths standing 4 meters high at the gates of Nineveh, sculptors ingeniously gave them five legs: appearing steadfast when viewed from the front, yet striding forward when viewed from the side.',
      'รูปสลักลามัสซูแห่งพระราชวังเซนนาเชริบในนิเนเวห์มีอายุเก่าแก่กว่า 2,700 ปี บางชิ้นถูกจัดแสดงในบริติชมิวเซียมและพิพิธภัณฑ์ลูฟวร์ และเป็นมรดกทางประวัติศาสตร์ที่สำคัญที่สุดของลุ่มแม่น้ำไทกริส-ยูเฟรตีส',
      'Dating to the 8th century BC, these monolithic palace gate sentinels protected Assyrian kings from demonic forces, surviving as supreme masterpieces of ancient world sculpture.',
      'ห้ามทำลาย ทำเครื่องหมาย หรือลบหลู่รอยแกะสลักอักษรลิ่มบนตัวลามัสซู',
      'Never deface or chisel cuneiform inscriptions carved upon the flank of a Lamassu.',
      'https://i.ytimg.com/vi/4PByGg7wuj4/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/4PByGg7wuj4/hqdefault.jpg","title":"ลามัสซู (ทวารบาลวัวปีกหน้ามนุษย์แห่งนิเนเวห์ เมโสโปเตเมีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=4PByGg7wuj4","title":"the Assyrian winged bull as a woman from ancient Iraq","thumbnail":"https://i.ytimg.com/vi/4PByGg7wuj4/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-cetus-sea-beast-jaffa',
      'ซีตัส (อสูรทะเลโบราณแห่งยัฟฟาและตำนานเพอร์ซีอุส)',
      'Cetus: The Primordial Sea Monster of Jaffa (Levant)',
      'monster',
      'เทลอาวีฟ',
      'Tel Aviv District',
      'ยัฟฟา',
      'Jaffa',
      32.0543,
      34.7505,
      'water_spirit',
      'อสูรทะเลมหึมาที่ถูกส่งมาโดยเทพโพไซดอนเพื่อลงทัณฑ์ราชินีแคสสิโอเปียที่โอ้อวดว่าบุตรสาว แอนโดรเมดา งดงามกว่าพรายน้ำเนรีดส์ แอนโดรเมดาถูกล่ามโซ่ตรึงไว้กับโขดหินริมทะเลที่เมืองยัฟฟาเพื่อสังเวยแก่ซีตัส ทว่าเพอร์ซีอุสได้เหาะมาช่วยทันเวลาด้วยการใช้ศีรษะของนางเมดูซาสาปให้ซีตัสกลายเป็นหินยักษ์กลางทะเล พลินีผู้เฒ่าบันทึกว่า ในสมัยโรมันยังคงมีซากกระดูกสันหลังขนาดยักษ์ยาวกว่า 40 ฟุตของอสูรตนนี้จัดแสดงอยู่ในเมือง',
      'In classical Greek myth, Cetus was a monstrous sea beast sent by Poseidon to ravage the coast after Queen Cassiopeia boasted her daughter Andromeda was more beautiful than the Nereids. Andromeda was chained naked to Andromeda''s Rock in ancient Jaffa to appease the leviathan. Perseus arrived on winged sandals, petrifying the beast using the severed head of Medusa. Pliny recorded that Roman governor Marcus Scaurus transported Cetus''s 40-foot skeletal ribs to Rome in 58 BC.',
      'โขดหินแอนโดรเมดา (Andromeda''s Rock) ยังคงตั้งตระหง่านอยู่ริมอ่าวท่าเรือโบราณยัฟฟาจนถึงปัจจุบัน ถือเป็นหนึ่งในท่าเรือที่เก่าแก่ที่สุดในประวัติศาสตร์โลก',
      'The legendary rock outcrop still breaks the surf outside Jaffa''s historic harbor, anchoring millennia of seafaring legends from Perseus to the biblical story of Jonah.',
      'ห้ามปีนป่ายขึ้นไปบนโขดหินแอนโดรเมดาขณะคลื่นลมทะเลรุนแรง',
      'Never attempt to scale Andromeda''s Rock during heavy offshore swells.',
      'https://i.ytimg.com/vi/qTwnVxWm0sM/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/qTwnVxWm0sM/hqdefault.jpg","title":"ซีตัส (อสูรทะเลโบราณแห่งยัฟฟาและตำนานเพอร์ซีอุส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qTwnVxWm0sM","title":"The Epic Story of Perseus Explained | Best Greek Mythology Documentary","thumbnail":"https://i.ytimg.com/vi/qTwnVxWm0sM/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-dobhar-chu-glenade-lough',
      'ดอบาร์-ชู (สุนัขน้ำกินคนแห่งเกลเนดลอค ไอร์แลนด์)',
      'The Dobhar-chú: Water Hound of Glenade Lough (Ireland)',
      'monster',
      'ลีทริม',
      'County Leitrim',
      'เกลเนด',
      'Glenade Lough',
      54.3414,
      -8.3128,
      'water_spirit',
      'สัตว์ประหลาดกึ่งนากกึ่งสุนัขล่าเนื้อขนาดยักษ์ในตำนานพื้นบ้านไอริช ลำตัวยาว ผิวหนังเหนียวลื่นสีดำ มีฟันแหลมคม และว่องไวทั้งบนบกและในน้ำ ในปี 1722 กรานเนีย คอนนอลลี หญิงสาวกำลังซักผ้าอยู่ริมฝั่งทะเลสาบเกลเนดลอค ได้ถูกดอบาร์-ชูจู่โจมลากลงน้ำและฉีกร่างสังหารอย่างทารุณ สามีของเธอตามมาพบศพและใช้กริชแทงหัวใจของมันจนตาย ทว่าก่อนตายมันได้ส่งเสียงหวีดร้องเรียกคู่ของมันขึ้นมาจากก้นทะเลสาบเพื่อไล่ล่าล้างแค้น',
      'Known in Irish folklore as the ''King Otter'' or ''Water Hound'', the Dobhar-chú is a ferocious aquatic beast resembling a massive half-dog, half-otter with impenetrable skin. In 1722, Grace Connolly was washing clothes at Glenade Lough when the beast tore her to pieces. Her husband tracked the sleeping beast and stabbed it through the heart, only for it to emit a dying whistle that summoned its vengeful mate from the depths for a desperate horse chase.',
      'หลุมศพของกรานเนีย คอนนอลลี ยังคงตั้งอยู่ในสุสานคอนวอลล์ (Conwall Cemetery) ริมทะเลสาบ โดยมีภาพสลักรูปอสูรดอบาร์-ชูถูกแทงด้วยกริชปรากฏอยู่อย่างชัดเจนบนแผ่นศิลาจารึก',
      'The gravestone of Grace Connolly in Conwall Cemetery bears a detailed relief carving of the slain Dobhar-chú, serving as tangible folkloric evidence of this terrifying encounter.',
      'ห้ามซักผ้าหรือยืนอยู่ริมฝั่งน้ำเกลเนดลอคในยามที่ผิวน้ำนิ่งสนิทผิดปกติ',
      'Never wash clothes or loiter on the reeds of Glenade Lough at dusk.',
      'https://i.ytimg.com/vi/NBTpL5gbc2w/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/NBTpL5gbc2w/hqdefault.jpg","title":"ดอบาร์-ชู (สุนัขน้ำกินคนแห่งเกลเนดลอค ไอร์แลนด์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=NBTpL5gbc2w","title":"The Dobhar-Chú - Ireland''s Lake Monster","thumbnail":"https://i.ytimg.com/vi/NBTpL5gbc2w/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-nandi-bear-chemosit-kenya',
      'หมีนันดี เชโมซิต (อสูรผ่ากะโหลกแห่งเทือกเขานันดี เคนยา)',
      'The Nandi Bear (Chemosit: Brain-Eating Cryptid of Kenya)',
      'monster',
      'ริฟต์แวลลีย์',
      'Rift Valley',
      'นันดี',
      'Nandi County',
      0.1667,
      35.1667,
      'jungle_curse',
      'สัตว์ประหลาดดุร้ายในตำนานชนเผ่าพื้นเมืองนันดีทางตะวันตกของเคนยา พรรณนาว่าเป็นสัตว์เลี้ยงลูกด้วยนมกินเนื้อขนาดใหญ่ คล้ายหมีผสมไฮยีนายักษ์ มีขนหนาสีน้ำตาลเข้ม หลังลาดต่ำ และมีกรงเล็บคมกริบ เชโมซิตมีพฤติกรรมสยดสยองคือชอบซุ่มโจมตีเหยื่อมนุษย์จากกิ่งไม้สูงในเวลากลางคืน และใช้กรงเล็บเจาะกะโหลกศีรษะเพื่อกินสมอง ในยุคอาณานิคม วิศวกรสร้างทางรถไฟและเจ้าหน้าที่อังกฤษหลายคนรายงานว่าเคยเผชิญหน้ากับมันตัวต่อตัวในป่าทึบ',
      'In Kenyan tribal folklore, the Nandi Bear (or Chemosit) is a nocturnal demon-beast described as a hulking, hyena-bear hybrid with dark shaggy fur, a sloping back, and massive paws. Feared across East Africa, tradition says it drops silently from trees upon human travelers, biting open their skulls to devour brains. During British colonial railway construction in the early 1900s, dozens of experienced European engineers and game wardens reported sightings of the creature.',
      'นักบรรพชีวินวิทยาเสนอทฤษฎีว่าเรื่องเล่าของหมีนันดีอาจเป็นความทรงจำของชนพื้นเมืองที่สืบทอดมาจาก ''คาลิโคเธียร์'' (Chalicothere) สัตว์ดึกดำบรรพ์ที่มีกรงเล็บคล้ายหมี หรือไฮยีนายักษ์ยุคไพลสโตซีนที่เพิ่งสูญพันธุ์ไป',
      'Paleontologists theorize the Nandi Bear legend may represent surviving pockets of prehistoric giant hyenas or chalicotheres remembered through indigenous oral lore.',
      'ห้ามเดินป่าแถบสันเขาเทือกเขานันดีในคืนเดือนมืดโดยไม่มีคบเพลิง',
      'Never traverse the Nandi forest canopies alone at night without a burning firebrand.',
      'https://i.ytimg.com/vi/D1aDu2q1qvA/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/D1aDu2q1qvA/hqdefault.jpg","title":"หมีนันดี เชโมซิต (อสูรผ่ากะโหลกแห่งเทือกเขานันดี เคนยา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D1aDu2q1qvA","title":"The Nandi Bear Track of Fritz Schindler","thumbnail":"https://i.ytimg.com/vi/D1aDu2q1qvA/hqdefault.jpg"}]'
    );

INSERT OR REPLACE INTO ghost_pins (
      id, title_th, title_en, category, province_th, province_en, district_th, district_en,
      lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
      taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
    ) VALUES (
      'pin-monster-burrunjor-arnhem-predator',
      'เบอร์รุนจอร์ (ไดโนเสาร์กินเนื้อดึกดำบรรพ์แห่งออสเตรเลีย)',
      'The Burrunjor: Relic Theropod Predator of Arnhem Land',
      'monster',
      'นอร์เทิร์นเทร์ริทอรี',
      'Northern Territory',
      'อาร์เนมแลนด์',
      'Arnhem Land',
      -12.6845,
      133.0416,
      'jungle_curse',
      'สิ่งมีชีวิตลึกลับในตำนานดรีมไทม์ (Dreamtime) ของชาวอะบอริจินในแถบอาร์เนมแลนด์และแม่น้ำโรเปอร์ มีลักษณะเป็นสัตว์เลื้อยคลานขนาดยักษ์สูงกว่า 6-7 เมตร ยืนสองขา มีแขนหน้าขนาดเล็ก และมีฟันแหลมคมคล้ายไดโนเสาร์เทอโรพอด (ไทรันโนซอรัส) ในทศวรรษ 1950 คนเลี้ยงปศุสัตว์พบเห็นสัตว์ยักษ์สองขาฉีกกินซากวัวทั้งตัว และพบรอยเท้าสามนิ้วขนาดใหญ่ที่มีรอยเล็บแหลมฝังลึกในดินโคลน ชนพื้นเมืองเตือนให้หลีกเลี่ยงดินแดนต้องห้ามที่เบอร์รุนจอร์ครอบครอง',
      'Across the vast, untamed wilderness of Arnhem Land and the Gulf of Carpentaria, Aboriginal Dreamtime traditions speak of the Burrunjor: a monstrous, bipedal reptilian apex predator resembling a living theropod dinosaur. Between 1950 and 1980, Australian cattle ranchers reported dozens of cattle mauled and partially devoured in seconds, discovering colossal three-toed tracks with deep claw depressions leading into impenetrable scrub.',
      'เรื่องเล่าเรื่องเบอร์รุนจอร์สอดคล้องกับภาพเขียนสีบนหินโบราณของชาวอะบอริจินที่แสดงภาพสัตว์ยักษ์สองขา ถือเป็นหนึ่งในตำนานคริปทิดที่น่าตื่นเต้นที่สุดของเอาต์แบ็กออสเตรเลีย',
      'Documented by Australian cryptozoologist Rex Gilroy, sightings of bipedal reptilian predators in the Outback mirror ancient indigenous rock art of extinct megafauna.',
      'ห้ามตั้งแคมป์ริมแม่น้ำในเขตอาร์เนมแลนด์หากพบรอยเท้าสัตว์สามนิ้วขนาดใหญ่',
      'Never camp near river floodplains if giant three-toed claw prints are discovered.',
      'https://i.ytimg.com/vi/rPDsZwcFc_s/hqdefault.jpg',
      0,
      1,
      '[{"type":"image","url":"https://i.ytimg.com/vi/rPDsZwcFc_s/hqdefault.jpg","title":"เบอร์รุนจอร์ (ไดโนเสาร์กินเนื้อดึกดำบรรพ์แห่งออสเตรเลีย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=rPDsZwcFc_s","title":"AUSTRALIA’S LIVING DINOSAUR? | The Mystery of the Burronjor 🦖","thumbnail":"https://i.ytimg.com/vi/rPDsZwcFc_s/hqdefault.jpg"}]'
    );